/* 常识模块：地理国情（第 1/2 段） */
window.COMMON_BANK = window.COMMON_BANK || {};
window.COMMON_BANK["geo"] = window.COMMON_BANK["geo"] || {name:"地理国情", items:[]};
window.COMMON_BANK["geo"].items.push(
{"id": "geo-1", "q": "图中所示的是“一带一路”沿线的中亚地区，下列说法正确的是：", "options": ["甲湖在成因上属于构造湖", "乙湖是世界陆地的最低处", "丙河处于亚欧两洲分界线上", "丁河水源是由冰雪融水供给"], "a": 3, "e": "D】本题考查地理常识。A项错误，湖泊按照成因类型，可划分为构造湖、火口湖、堰塞湖、海迹湖、河成湖、冰川湖等。构造湖是指由地壳的构造运动(断裂、断层、地堑)所造成的洼陷，积水而成的湖，特点是湖泊的形状狭长，湖岸平直、湖坡陡峻，深度较大，如我国的青海湖、滇池、洱海等，此外还有亚洲的贝加尔湖、东非大裂谷中的一连串湖泊等。甲湖是里海，从形成原因来看，里海曾是古地中海的一部分，经过海陆演变，古地中海逐渐缩小，最后形成的湖泊，因此在成因上属于海迹湖。杭州西湖、太湖等均为海迹湖。B项错误，世界陆地的最低处位于死海。乙湖是咸海。C项错误，丙河是伏尔加河，处于亚欧两洲分界线上的是乌拉尔河和里海。D项正确，丁河是锡尔河，发源于天山山脉，水源主要是由冰雪融水供给。故正确答案为D。", "tag": "地理国情"},
{"id": "geo-2", "q": "下列表述正确的是：", "options": ["内陆国也可拥有并发展海军力量", "参与联合国维和行动的经费由各派驻国负担，但前提是派驻国的参谋军官、军事观察员及维和分队人员可以在被派驻", "当发生超过里氏8 级的地震时，国际医疗卫生组织及救援队伍可以不经地震发生国同意直接进入该国领土进行搜救工", "根据动力分类，潜艇可分为常规潜艇和核潜艇，其中常规潜艇属于战略潜艇，核潜艇属于攻击型潜艇"], "a": 0, "e": "A】A项：正确。首先主权国家有权发展自己武装力量；其次世界上有蒙古、巴拉圭等至少8个内陆国有成建制的海军部队。B项：错误。因为维和行动属非强制性行动，所以军事观察员等不得携带武器。C项：错误，国际救援仅是联合国和国际救灾组织的一个倡议，未经允许进入主权国家是对主权国的侵犯。D项：错误，战略潜艇和攻击潜艇是按照用途分类法，核动力潜艇和常规潜艇均可以既有战略潜艇，又有攻击潜艇。故正确答案为A。", "tag": "地理国情"},
{"id": "geo-3", "q": "国家生态安全主要是指一国具有支撑国家生存发展的较为完整和不受威胁的生态系统，以及应对内外重大生态问题的能力。关于我国生态安全，下列表述错误的是：", "options": ["自然生态空间过度挤压，草原超载现象严重", "土地沙化退化以及水土流失不容忽视", "生物多样性面临挑战，外来物种入侵事件频发", "近海生态恶化趋势得到全面遏制"], "a": 3, "e": "D】本题主要考查地理常识。生态安全是指一国生态环境在确保国民身体健康、为国家经济提供良好的支撑和保障能", "tag": "地理国情"},
{"id": "geo-4", "q": "刘某乘火车从徐州出发去乌鲁木齐，列车行驶在徐新高铁线上，下列情况不可能发生的是：", "options": ["刘某看到了黄河", "列车经过太原站", "列车驶入河南省境内", "列车速度达到300 千米/小时"], "a": 1, "e": "B】本题考查地理国情。徐新高铁，是从江苏徐州到新疆乌鲁木齐的一条高速线路，途经江苏、安徽、河南、陕西、甘肃、青海、新疆7省/自治区。A项正确，徐新高铁途经郑州、西安、兰州等城市，在兰州跨越黄河，通向乌鲁木齐，因此，刘某在火车上可以看到黄河。B项错误，徐新高铁途经河南郑州后直接向西通向陕西西安，不经过山西太原。C项正确，徐新高铁途经河南郑州后直接向西通向陕西西安，因此要经过河南。D项正确，目前我国“复兴号”动车组已实现350公里时速运营，因此列车速度达到300千米/小时是可能发生的。本题为选非题，故正确答案为B。", "tag": "地理国情"},
{"id": "geo-5", "q": "“海上丝绸之路”是古代中国与外国交通贸易和文化交往的海上通道，包括东海航线和南海航线。以下城市不属于“海上丝绸之路”航线中主要港口的是：", "options": ["广州", "泉州", "宁波", "厦门"], "a": 3, "e": "D】D项符合题意：中国境内海上丝绸之路主要有广州、泉州、宁波三个主港和其他支线港组成。《汉书.地理志》中记载，秦汉时期，广州已成为海上丝绸之路的主港；唐宋时期，广州成为中国第一大港，明初、清初海禁，广州长时间处于“一口通商”局面，是世界海上交通史上唯一的2000多年长盛不衰的大港。宋末至元代时，泉州成为中国第一大港，与埃及的亚历山大港并称为“世界第一大港”，后因明清海禁而衰落，泉州是唯一被联合国教科文组织承认的海上丝绸之路起点。在东汉初年，宁波地区已与日本有交往，到了唐朝，宁波成为中国的大港之一，两宋时，靠北的外贸港先后为辽、金所占，或受战事影响，外贸大量转移到宁波。其中，广州和泉州属于南海航线，宁波属于东海航线。本题为选非题，故正确答案为D。", "tag": "地理国情"},
{"id": "geo-6", "q": "关于我国农业国情，下列说法错误的是：", "options": ["五大牧区的简称为新、藏、青、蒙和陇", "南北方最主要的糖料作物分别是甘蔗和甜菜", "“湖广熟，天下足”，江汉平原是最大的商品粮产区", "红壤是一种粘性酸壤，主要分布于长江以南的低山丘陵区"], "a": 2, "e": "C】新疆、西藏、青海、内蒙古、甘肃是我国的五大牧区，A项中的简称“新、藏、青、蒙、陇”是正确的，故A项正确。我国的糖料作物主要包括甘蔗和甜菜，甘蔗主要分布在南方沿海的各省区，甜菜主要分布在北方各省区，被称为“南蔗北菜”，故B项正确。我国最大的商品粮产区是松嫩平原，故C项错误。红壤在中国主要分布于长江以南的低山丘陵区，故D项正确。本题为选非题，故正确答案为C。", "tag": "地理国情"},
{"id": "geo-7", "q": "下列有关山东省“三大经济圈”表述正确的是：", "options": ["淄博、泰安、德州、滨州、潍坊都属于省会经济区", "水浒故里、黄河口生态旅游区位于胶东经济圈", "东方圣地、亲情沂蒙等旅游品牌都属于鲁南经济区", "省会经济区的定位包括金融中心和乡村振兴先行区"], "a": 2, "e": "C】本题考查地理国情。A项错误，根据《山东省人民政府关于加快省会经济圈一体化发展的指导意见》，省会经济圈涵盖济南、淄博、泰安、聊城、德州、滨州、东营7市，潍坊不属于省会经济圈，而属于胶东经济圈。B项错误，根据《山东省人民政府关于加快胶东经济圈一体化发展的指导意见》，胶东经济圈涵盖青岛、烟台、威海、潍坊、日照5市。黄河口生态旅游区位于东营市，属于省会经济圈，水浒故里位于菏泽市，属于鲁南经济圈。C项正确，根据《山东省人民政府关于加快鲁南经济圈一体化发展的指导意见》，鲁南经济圈涵盖临沂、枣庄、济宁、菏泽4市。“东方圣地”是济宁市旅游品牌，“亲情沂蒙”是临沂市旅游品牌，均属于鲁南经济圈。D项错误，省会经济圈的定位是打造黄河流域生态保护和高质量发展示范区、全国动能转换区域传导引领区、世界文明交流互鉴新高地，其建设的是济南区域性金融中心；打造全国金融中心是胶东经济圈的定位，而乡村振兴先行区则是鲁南经济圈的定位。故正确答案为C。", "tag": "地理国情"},
{"id": "geo-8", "q": "茶马古道是位于我国西南地区的贸易通道。它从云南和四川茶叶产地出发，穿过横断山脉、跨越几大河流向西延伸，覆盖云贵高原和青藏高原，通往喜马拉雅山脉南部南亚次大陆。以下河流不流经茶马古道的是：", "options": ["左江", "金沙江", "怒江", "雅砻江"], "a": 0, "e": "A】A项符合题意：左江是西江水系上游支流郁江的最大支流，发源于越南与广西交界的枯隆山。上游在越南境内称奇穷河（又叫黎溪），于凭祥市边境平而关进入中国境内后称平而河。左江既不流经云贵高原，也不流经青藏高原，故不可能流经茶马古道。B项不符合题意：金沙江的发源地为青海省唐古拉山主峰各拉丹冬雪山，位于青藏高原，故流经茶马古道。C项不符合题意：怒江是中国西南地区的大河流之一，发源于青藏高原的唐古拉山南麓的吉热拍格，流经茶马古道。D项不符合题意：雅砻江是金沙江的最大支流，是中国水能资源最富集的河流之一，发源于巴颜喀拉山（位于青藏高原）南麓，流经茶马古道。本题为选非题，故正确答案为A。", "tag": "地理国情"},
{"id": "geo-9", "q": "下列与我国四大盆地有关的说法不正确的是：", "options": ["柴达木盆地盛产小麦和青稞", "准噶尔盆地呈不规则三角形", "罗布泊位于塔里木盆地东部", "四川盆地的气温高于同纬度其他地区"], "a": 0, "e": "A】本题考查地理国情。A项错误，柴达木盆地位于青藏高原东北部青海省境内，盆地内部大部分为戈壁、沙漠，东部多沼泽、盐湖，矿藏丰富并非农作物的主要产区。B项正确，准噶尔盆地位于中国新疆的北部，阿尔泰山与天山之间，盆地呈不规则三角形，地势向西倾斜，北部略高于南部。C项正确，罗布泊位于新疆塔里木盆地东部，由于气候变迁及人类水利工程影响，导致上游来水减少，现已干涸，仅为大片盐壳。D项正确，四川盆地位于我国四川省和重庆市境内，盆地四周被山岭和高原环绕，盆地内部低山丘陵起伏，西部有成都平原。四川盆地地形闭塞，四周高中间低，白天热气聚集在低地内，晚上不易散出去，气温高于同纬度其他地区。本题为选非题，故正确答案为A。", "tag": "地理国情"},
{"id": "geo-10", "q": "某村是贫困村，县扶贫工作队调研后认为该村有种植天麻的先天优势，遂决定将推动天麻种植作为扶贫工作的重要内容。县扶贫工作队采取的下列措施中不正确的是：", "options": ["加强宣传引导，调动村民种植天麻的积极性", "确定种植任务，规定每户村民的种植面积", "统筹扶贫资金，做好良种引进和技术服务", "吸引社会资本，推进天麻产品的深度加工"], "a": 1, "e": "【B】B项错误：县扶贫工作队定点做好扶贫工作，应当按照精准扶贫的工作要求，进一步加大资金投入、智力支持、项的措施是强制性规定任务，不能从根本上帮助贫困户通过自我发展来实现脱贫，与“增强贫困地区造血功能”的扶贫理念相悖。A、C、D项正确：这三项措施均能有效推动该村结合实际，因地制宜实现脱贫。A项“加强宣传引导”能帮助贫困村民认清本村的优势，理清发展思路；C项和D项通过借助技术服务和社会资本的投入，能帮助村民实现良性持续地发展，共享发展成果，实现集体脱贫。本题为选非题，故正确答案为B。", "tag": "地理国情"},
{"id": "geo-11", "q": "网络黑客攻击是全球性问题。我国是黑客攻击的最大受害国之一，我国政府一贯坚决反对黑客攻击行为，并愿就推动互联网安全和打击网络黑客攻击等违法犯罪活动加强国际合作。这说明：", "options": ["我国在国际事务中发挥主导作用", "维护国家利益是我国对外活动的目的和依据", "我国与其他各国的国家利益相同", "独立自主是我国处理国际关系的基本准则"], "a": 1, "e": "【B】A项错误，“主导作用”在题干中没有体现，而且不符合实际国情；B项正确，中国是网络攻击受害国，中国政府一贯反对黑客攻击，并倡导国际合作，提出国际社会应共建和平、安全、开放、合作的网络空间，说明我国在对外活动中，是以维护我国的国家利益为目的和依据的；C项错误，国与国的利益有相同点，但是国家的利益不可能完全相同（比如发达国家和发展中国家之间）；D项错误，我国处理国际关系的基本准则是奉行“互相尊重主权和领土完整、互不侵犯、互不干涉内政、平等互利、和平共处”五项原则的外交政策。独立自主是我国外交政策的基本立场。故正确答案为B。", "tag": "地理国情"},
{"id": "geo-12", "q": "2018 年男排世锦赛，国际排联第一次专门为中国观众安排了适合中国球迷观看的比赛时间。在不同时区国家举办国际赛事，通常会让想熬夜观赛的体育迷们很纠结。下列有关时区的说法中，正确的是", "options": ["由于世界各国与地区的纬度不同，地方时也有所不同，因此会划分为不同的时区", "出国旅行的人，凡是往东走，每过一个时区，就要把表拨慢一小时", "1884 年召开的国际子午线会议上，规定将全球划分为12 个时区", "我国采用首都北京所在的东八区的区时"], "a": 3, "e": "【D】本题考查地理国情。A项错误，地球不停的自西向东自转，会导致地球上同一纬度地区地方时不同。即就是由于世界各国与地区的经度不同，地方时有所不同，因此会划分为不同的时区。B项错误，全球24个时区，相邻时区相差1小时。由于地球自西向东自转，中时区向东，每增加1时区，时间增加1小时；向西则相反。所以往东走，每过一个时区，应把表拨快一小时。C项错误，为了克服时间上的混乱，1884年在华盛顿召开的国际经度会议上，规定将全球划分为24个时区（东、西各", "tag": "地理国情"},
{"id": "geo-13", "q": "下列说法正确的是：", "options": ["长白山地属暖温带的湿润地区", "我国夏季气温分布的特点是：全国大多数地方普遍高温，南北方气温相差不大", "农作物能够生长的时间被称为生长期，生长期一般比当地的无霜期要短十五天左右", "河北的天气特点是：春季温暖，常有风沙；夏季炎热，雨量充沛；秋季凉爽，天气晴朗；冬季寒冷，有时下雪"], "a": 1, "e": "【B】本题考查地理国情。A项错误，在我国，秦岭—淮河线以北，包括塔里木盆地、华北平原和黄土高原，以及辽宁省南部等地区属于暖温带；大兴安岭北段及其两侧地区属于寒温带；在暖温带与寒温带之间，是东西延伸、面积广阔的中温带地区，包括准噶尔盆地、内蒙古高原、东北平原等。我国湿润地区包括东北山地、秦岭—淮河线以南、青藏高原东南部等。长白山地是指我国辽宁、吉林、黑龙江三省东部山地，属于中温带湿润地区。B项正确，我国冬季气温分布特点是南北温差很大，越往北气温越低；夏季气温分布的特点是南北普遍高温，南北方气温相差不大。C项错误，一年中植物显著可见的生长期间，称为生长期，也称为生季。生长期与温度条件有着密切的关系，在一定以上的温度可继续生长的时期就称为生长期。无霜期指一年中终霜后至初霜前的一整段时间，在这一期间内，没有霜的出现。农作物的生长期与无霜期有密切关系。无霜期愈长，生长期也愈长。无霜期的长短因地而异，一般纬度、海拔高度愈低，无霜期愈长。故“生长期一般比当地的无霜期要短十五天”表述不当，二者时间长短应一致或基本一致。D项错误，河北地处华北平原，属温带季风气候，四季分明，同时，河北属于我国的半湿润地区，夏季雨量并不充沛，故“夏季炎热，雨量充沛”表述不当。故正确答案为B。", "tag": "地理国情"},
{"id": "geo-14", "q": "关于中国外交，下列说法错误的是：", "options": ["二十世纪八九十年代，邓小平提出“韬光养晦、有所作为”的外交战略", "“另起炉灶”是毛泽东在新中国成立前夕提出的外交方针", "周恩来和陈毅都曾担任过外交部长", "委内瑞拉是第一个同新中国建交的拉丁美洲国家"], "a": 3, "e": "【D】D项错误：第一个和新中国建交的拉丁美洲国家是古巴，两国于1960年建立外交关系；中国与委内瑞拉建立外交关系是在1974年，当选；A项正确：“韬光养晦、有所作为”是邓小平在20世纪八十年代末九十年代初面对国际国内局势急剧变化时提出的外交战略方针，排除；B项正确：“另起炉灶”是毛泽东在中共七届二中全会前后提出的三大外交政策之一，七届二中全会于1949年3月召开，正处新中国成立前夕，排除；C项正确：在中华人民共和国成立后，周恩来于1949年-1958年担任第一任外交部长，陈毅于1958年-1972年担任第二任外交部长，排除。本题为选非题，故正确答案为D。", "tag": "地理国情"},
{"id": "geo-15", "q": "下列哪种情形最可能发生在诗句“绿槐高柳咽新蝉”描写的季节？（）", "options": ["华北地区开始播种水稻", "黄河的刘家峡到包头段出现凌汛", "中山站上方出现极光现象", "陕西富平地区开始制作柿饼"], "a": 2, "e": "【C】本题考查地理国情。“绿槐高柳咽新蝉”出自宋代苏轼的《阮郎归初夏》，营造出一种清丽欢快的情调，描写的是初夏时节的闺阁生活。A项错误，华北地区种植的水稻是单季稻，一季水稻播种时间为清明前，四月底五月初移栽。不符合题干中描述的季节。B项错误，凌汛是黄河常见的一种自然现象。由于黄河所处纬度较高，下游河道冬季结冰封河，而春初解冻开河后冰水齐下，冰凌壅塞，水位上涨，形成凌汛洪水，此时期为黄河凌汛期。不符合题干中描述的季节。C项正确，极光是发生在地球高磁纬地区的一种大规模放电现象。由于中山站特殊的地理位置，一天穿越两次极光带，是世界上进行极光观测的最佳场所之一。一般来说，观测极光通常都是在每年夏至前后的夜晚。D项错误，富平柿饼，陕西省富平县特产，中国国家地理标志产品。富平柿饼以当地生产的传统名优柿子品种“富平尖柿”为原料，10月中下旬手工采摘后经过清洗削皮、日晒压捏、捏晒整形、定型捂霜等多道工序精细制作而成。故正确答案为C。", "tag": "地理国情"},
{"id": "geo-16", "q": "为了适应全球科技创新发展的趋势，我国制定了《中国制造2025》的行动纲领，下列对《中国制造2025》理解错误的是：", "options": ["全球制造业格局面临重大调整是制定《中国制造2025》的重要背景", "《中国制造2025》的覆盖范围包括国民经济门类中的所有产业", "制定《中国制造2025》是为了通过“三步走”实现制造强国的战略目标", "《中国制造2025》与美国工业物联网，德国的工业4.0 都强调生产效率"], "a": 1, "e": "【B】B项错误：《中国制造2025》规划是我国实施制造强国战略第一个十年的行动纲领，围绕实现制造强国的战略目标明确了九大任务、十大重点领域和五项重大工程，主要针对制造业，没有覆盖国民经济门类中的所有产业；A项正确：全球制造业发展格局和我国经济发展环境发生重大变化，是我国制定《中国制造2025》的重要背景；C项正确：制造业是国民经济的主体，是科技创新的主战场，是立国之本、兴国之器、强国之基。制定《中国制造", "tag": "地理国情"},
{"id": "geo-17", "q": "下列关于世界人口发展趋势的判断，错误的是：", "options": ["人口总量增速放缓", "人均寿命不断延长", "总和出生率上升", "人口加速老年化"], "a": 2, "e": "【C】本题主要考查国情社情相关知识。A项正确，联合国发布的《世界人口展望》2017年修订版报告指出：世界人口数量已达76亿，预计2030年将达86亿，", "tag": "地理国情"},
{"id": "geo-18", "q": "关于我国防震减灾和抗震救灾工作的说法，不正确的是：", "options": ["防震减灾工作应当纳入县级以上国民经济和社会发展计划", "国家鼓励和支持防震减灾科研活动和先进科研成果推广工作", "国务院抗震救灾指挥机构负责统一组织各级各类抗震救灾工作", "中国人民解放军按照国务院和中央军委的命令执行抗震救灾任务"], "a": 2, "e": "【C】A项说法正确，《中华人民共和国防震减灾法》第四条规定：“县级以上人民政府应当加强对防震减灾工作的领导，将防震减灾工作纳入本级国民经济和社会发展规划，所需经费列入财政预算。”B项说法正确，该法第十一条规定：“国家鼓励、支持防震减灾的科学技术研究，逐步提高防震减灾科学技术研究经费投入，推广先进的科学研究成果，加强国际合作与交流，提高防震减灾工作水平。”C项说法错误，该法第六条规定：“国务院抗震救灾指挥机构负责统一领导、指挥和协调全国抗震救灾工作。县级以上地方人民政府抗震救灾指挥机构负责统一领导、指挥和协调本行政区域的抗震救灾工作。”D项说法正确，该法第九条规定：“中国人民解放军、中国人民武装警察部队和民兵组织，依照本法以及其他有关法律、行政法规、军事法规的规定和国务院、中央军事委员会的命令，执行抗震救灾任务，保护人民生命和财产安全。”本题为选非题，故正确答案为C。", "tag": "地理国情"},
{"id": "geo-19", "q": "下列诗句与描写的景点对应正确的是（）", "options": ["会当凌绝顶，一览众山小——安徽黄山", "水光潋滟晴方好，山色空蒙雨亦奇——杭州西湖", "二十四桥明月夜，玉人何处教吹箫——北京昆明湖", "飞流直下三千尺，疑是银河落九天——贵州黄果树瀑布"], "a": 1, "e": "【B】A项对应错误：出自杜甫的《望岳》，描写的是东岳泰山。B项对应正确：出自苏轼的《饮湖上初晴后雨》，描写的是杭州西湖。C项对应错误：出自杜牧的《寄扬州韩绰判官》，描写的是扬州二十四桥。D项对应错误：出自李白的《望庐山瀑布》，描写的是江西省九江市的庐山。故正确答案为B。", "tag": "地理国情"},
{"id": "geo-20", "q": "山东省政府提出，要促进信息化和工业化深度融合，推动云计算、物联网等信息技术广泛应用，建设包括北斗系统示范工程、量子通信在内的新型信息技术类基础设施，健全信息安全保障措施，加快构建（）。", "options": ["智慧山东", "美丽山东", "科技山东", "信息山东"], "a": 0, "e": "【A】山东省省长姜大明在山东省第十二届人民代表大会第一次会议中提出了“智慧山东”的概念。故正确答案为A。", "tag": "地理国情"},
{"id": "geo-21", "q": "关于我国的农民工现象，下列说法错误的是：", "options": ["农民工是我国特有的城乡二元体制的产物", "近年来跨省流动农民工所占比重继续下降", "从输出地看，中部地区输出农民工最多，西部次之，东部最少"], "a": 2, "e": "【C】A项正确，农民工，是指在本地乡镇企业或者进入城镇务工的农业户口人员，农民工是我国特有的城乡二元体制", "tag": "地理国情"},
{"id": "geo-22", "q": "下列关于我国河流的说法不正确的是：", "options": ["黑龙江是中国的内河", "长江最大的支流是汉江", "黄果树瀑布、桂林山水都位于珠江流域", "“大漠孤烟直，长河落日圆”中的“河”指黄河"], "a": 0, "e": "【A】本题考查地理国情。A项错误，黑龙江是流经蒙古、中国、俄罗斯的国际河流，位于亚洲东北部。黑龙江分为南北两源，南侧以额尔古纳河为河源（中国境内），北侧以克鲁伦河为源头（蒙古境内），最后流入鄂霍次克海峡，入海口在俄罗斯的尼古拉耶夫斯克。黑龙江原为中国内河，19世纪中后期沙俄强行占领中国黑龙江以北、乌苏里江以东大片领土之后，成为中俄界河。", "tag": "地理国情"},
{"id": "geo-23", "q": "（）在新疆境内，是中国第二大盆地，海拔500 米，中间是沙漠戈壁，边缘是绿洲。", "options": ["准噶尔盆地", "塔里木盆地", "柴达木盆地", "吐鲁番盆地"], "a": 0, "e": "【A】A项正确：准噶尔盆地是我国第二大盆地，位于新疆，面积约38万平方公里。B项错误：塔里木盆地是我国第一大盆地，位于新疆，面积约53万平方公里。C项错误：柴达木盆地是我国第三大盆地，位于青海，面积约22万平方公里。D项错误：吐鲁番盆地紧跟中国十大盆地，居第11位，位于新疆，面积约50140平方公里。故正确答案为A。", "tag": "地理国情"},
{"id": "geo-24", "q": "吉林省盛产驰名中外的特产，如长白人参、黄松甸灵芝、梅花鹿茸、林蛙油、黑木耳等。假如吉林省应邀到美国加利福尼亚州参加土特产展览会，请你为此次文化交流拟一个主题，你认为最合适的是", "options": ["弘扬传统，推陈出新", "面向世界，为我所用", "求同存异，文化共享", "相互尊重，因地制宜"], "a": 2, "e": "【C】主题是指文艺作品中或者社会活动等所要表现的中心思想，泛指主要内容。A项错误，根据题干信息“吉林省应邀到美国加利福尼亚州参加土特产展览会”进行文化交流活动，并没有体现出推陈出新信息，故排除。B项错误，根据题干信息“吉林省应邀到美国加利福尼亚州参加土特产展览会”中的美国加利福尼亚州参加土特产展览会并不能代表世界范围，且吉林省参加此次展览会属于文化交流活动，没有体现“为我所用”，更侧重文化交流。C项正确，根据题干信息吉林省特产资源丰富，被邀请到美国参加土特产展览会进行文化交流活动，体现了差异性，差异性也促进了文化之间的交流和共享。D项错误，因地制宜的意思是根据各地的具体情况，制定适宜的办法。根据题干信息“吉林省应邀到美国加利福尼亚州参加土特产展览会”属于文化交流活动，因地制宜不能够体现文化交流这一主题。故正确答案为C。", "tag": "地理国情"},
{"id": "geo-25", "q": "从新中国成立到党的十八届四中全会，中国法治建设经历了多个重大节点。下列关于我国法治建设过程中的重大举措，按时间先后排序正确的一项是（）。①宣布中国特色社会主义法律体系形成②提出依法治国并写入宪法③提出发展社会主义民主与社会主义法制④提出全面推进依法治国", "options": ["③②①④", "①②③④", "③①④②", "①③④②"], "a": 0, "e": "【A】③1978年党的十一届三中全会提出发展社会主义民主，健全社会主义法制；②1997年中国共产党第十五次全国代表大会提出依法治国，并将其写入党的十五大报告，在1999年第九届全国人民代表大会第二次会议通过的《中华人民共和国宪法修正案》中，把“依法治国”写入宪法；①2011年3月，原全国人大常委会委员长吴邦国作全国人大常委会工作报告时宣布，中国特色社会主义法律体系已经形成；④2014年党的十八届四中全会提出全面推进依法治国。按时间先后的顺序为③②①④。故正确答案为A。", "tag": "地理国情"},
{"id": "geo-26", "q": "我国人口分布有一条明显的地理分界线，该线东南部人口多，西北部人口少，这条分界线是：", "options": ["漠河—腾冲连线", "黑河—腾冲连线", "秦岭—淮河连线", "天山—阴山连线"], "a": 1, "e": "【B】由东北至西南，从黑龙江黑河到云南腾冲作一直线，就是我国的人口地理分界线，由地理学家胡焕庸于20世纪", "tag": "地理国情"},
{"id": "geo-27", "q": "2016 年中央一号文件提出，要牢固树立和深入贯彻落实创新、协调、绿色、开放、共享的发展理念，用发展新理念破解“三农”新难题。下列选项中，体现了“农业绿色发展理念”的是：", "options": ["落实和完善耕地占补平衡制度，坚决防止占多补少、占优补劣、占水田补旱地，严禁毁林开垦", "加快农产品批发市场升级改造，加强粮食等重要农产品仓储物流设施建设", "大力推进“互联网+”现代农业，应用现代信息技术，推动农业全产业链改造升级", "加大对农产品出口支持力度，巩固农产品出口传统优势，培育新的竞争优势，扩大特色和高附加值农产品出口"], "a": 0, "e": "【A】A项正确：2016中央一号文件中“加强资源保护和生态修复，推动农业绿色发展”的措施中包括：加强农业资源保护和高效利用、加快农业环境突出问题治理、加强农业生态保护和修复、实施食品安全战略。A选项中的做法体现了加强农业生态保护和修复，属于农业绿色发展的理念；B项错误：B项的做法属于“推进农村产业融合，促进农民收入持续较快增长”中的“加强农产品流通设施和市场建设”的措施；C项错误：C项的做法属于“持续夯实现代农业基础，提高农业质量效益和竞争力”中的“强化现代农业科技创新推广体系建设”的措施；D项错误：D项的做法属于“持续夯实现代农业基础，提高农业质量效益和竞争力”中的“统筹用好国际国内两个市场、两种资源”的措施。故正确答案为A。", "tag": "地理国情"},
{"id": "geo-28", "q": "对我国现阶段“三农”政策的理解不准确的是：", "options": ["扶贫标准是农民人均纯收入2300 元", "农村最低生活保障制度就是扶贫开发", "农村集体土地指农民集体所有的建设用地、农用地和未利用地", "农业补贴政策包括种粮农民直接补贴、农资综合补贴、良种补贴和农机具购置补贴"], "a": 1, "e": "【B】农村最低生活保障制度和扶贫开发是两项制度。农村最低生活保障制度指由地方政府为家庭人均纯收入低于当地定期定量生活救济制度的基础上逐步发展和完善的一项规范化的社会救助制度。本题为选非题，故正确答案为B。", "tag": "地理国情"},
{"id": "geo-29", "q": "关于国家，下列说法中错误的是：", "options": ["丹麦是世界上纬度最高的国家", "俄罗斯是世界上跨经度最广的国家", "芬兰拥有世界上最多的湖泊", "沙特阿拉伯有世界上面积最大的沙漠"], "a": 3, "e": "【D】本题考查国情社情，主要涉及各个国家的相关知识。格陵兰岛位于世界上纬度最高的国家——丹麦，面积平方公里，是世界第一大岛。格陵兰在地理纬度上属于高纬度，它最北端莫里斯•耶苏普角位于，故格陵兰岛所在的丹麦是世界上纬度最高的国家。B项正确，俄罗斯横跨个经度。地跨欧亚两大洲，是世界上面积最大，东西距离最长，跨经度最广的国家。C项正确，芬兰，位于欧洲北部，北欧五国之一，与瑞典、挪威、俄罗斯接壤，南临芬兰湾，西濒波的尼亚湾。海岸线长公里，内陆水域面积占全国面积的，有岛屿约万个，湖泊约万个，是世界上拥有湖泊最多的国家，有“千湖之国”之称。D项错误，世界上面积最大的沙漠是撒哈拉沙漠，横贯非洲大陆北部,东西长达公里,南北宽约公里，约占非洲总面积。撒哈拉沙漠西从大西洋沿岸开始，北到地中海，东部直抵红海，南部到苏丹热带草原。而沙特阿拉伯位于亚洲西南部的阿拉伯半岛。撒哈拉沙漠并不经过沙特阿拉伯。本题为选非题，故正确答案为D。", "tag": "地理国情"},
{"id": "geo-30", "q": "建设海绵城市是中国提出的、适合中国国情的城市水问题综合治理理念。关于海绵城市，下列表述错误的是：", "options": ["城市像海绵一样，遇到降雨，能够就地或者就近吸收、渗透、净化径流雨水，补充地下水，需要时再将蓄存的水释放", "海绵城市建设要注重巧做生态大文章，实现更多利益，需要水利、气象水文、市政等广泛参与", "海绵城市建设不仅要与黑臭水体治理结合，还要和城市内涝治理结合", "我国分两批确定了30 个海绵城市建设试点，部分试点城市仍然出现明显的积水和内涝"], "a": 0, "e": "【A】本题命题不严谨，无参考价值，了解知识点即可。A项错误，海绵城市是指通过加强城市规划建设管理，充分发挥建筑、道路和绿地、水系等生态系统对雨水的吸收、存蓄、渗透、净化作用，有效控制雨水径流，实现自然积存、自然渗透、自然净化的城市发展方式。B项正确，海绵城市是一种理念，它的建设要注重巧做生态大文章，实现更多效益，需要水利、气象水文、市政等广泛参与。C项正确，推进海绵城市建设，不仅要与黑臭水体治理结合，还要和城市内涝治理结合。使城市既有“面子”、更有“里子”，统筹解决内涝、城市面源污染、合流制溢流污染，水生态破坏等问题。D项正确，2015年4月以来，国家先后公布两批中央财政支持海绵城市建设试点，据《中国经济周刊》记者不完全统计，第一批试点的16个海绵城市中有10个发生内涝；第二批试点的14个海绵城市中有9个发生内涝。总体计算，目前已纳入试点的30个城市中，部分试点城市仍然出现明显的积水和内涝。但是作为一道公务员考题，粉笔倾向性答案为A，因为题干中的“吸收、渗透、净化”比常规的表述少了个“存蓄”，加上的话会跟后半句的“再将蓄存的水释放出来加以利用”对应搭配。本题为选非题，故正确答案为A。", "tag": "地理国情"},
{"id": "geo-31", "q": "下列说法错误的是：", "options": ["中关村位于北京市，是我国最早的高新区", "深圳是我国改革开放建立的第一个经济特区", "截至2017 年年底，我国共有上海浦东新区、天津滨海新区、重庆两江新区及河北雄安新区4 个国家级新区", "开发区包括经济技术开发区、保税区、高新技术产业开发区、国家旅游度假区等"], "a": 2, "e": "【C】本题主要考查国情社情的相关知识。A项正确，中关村科技园，位于北京市海淀区，是中国第一个国家级高新技术产业开发区，被誉为“中国硅谷”。选项正确。B项正确，1980年8月，中国政府正式批准建立深圳经济特区，随后又在珠海、汕头、厦门、海南建立特区。因此深圳是我国改革开放建立的第一个经济特区。选项正确。C项错误，截至2017年年底，中国国家级新区总数共19个，分别是上海浦东新区、天津滨海新区、重庆两江新区、浙府新区、湖南湘江新区、南京江北新区、福建福州新区、云南滇中新区、哈尔滨新区、长春新区、江西赣江新区、河北雄安新区。选项错误。D项正确，开发区是指由国务院和省、自治区、直辖市人民政府批准在城市规划区内设立的经济技术开发区、保税区、高新技术产业开发区、国家旅游度假区等实行国家特定优惠政策的各类开发区。选项正确。本题为选非题，故正确答案为C。", "tag": "地理国情"},
{"id": "geo-32", "q": "关于世界著名工业或科技区的地理特点，下列说法错误的是：", "options": ["德国的鲁尔区崛起得益于丰富的煤炭资源", "美国的“硅谷”位于安第斯山脉以东", "中国的中关村科技园区位于华北平原", "日本的“硅岛”九州岛是日本第三大岛"], "a": 1, "e": "【B】本题考查地理常识，主要涉及世界著名工业区和科技区。A项正确，德国鲁尔区有着丰富的煤炭资源，由于二战前钢铁市场需求强劲，鲁尔区因其自身的煤炭资源优势得到迅速发展。B项错误，美国的“硅谷”位于旧金山附近，临近美国西海岸，位于落基山脉以西，是新兴电子工业的中心。而安第斯山脉位于南美洲，故B选项错误。C项正确，中关村科技园位于北京，是中国第一个国家级高新技术产业开发区。北京位于华北平原的西北部，故C选项正确。D项正确，九州岛是日本的第三大岛，次于本州和北海道，而比四国稍大，位于日本西南端。九州岛是日本高科技产业的主要集散地，70年代以来，电子工业迅速发展，有“硅岛”之称。本题为选非题，故正确答案为B。", "tag": "地理国情"},
{"id": "geo-33", "q": "对联是中华语言独特的艺术形式，它要求两行文字字数相同，意义相关，词性相当，结构相称，对仗工整，如能藏典更佳。下列选项是以不同地方为题材所作的对联，其中最恰当的一项是：", "options": ["安徽和陕西：黄山为九州增色；瓷器与中国同名", "湖南和湖北：八百里洞庭凭岳阳壮阔；两千年赤壁览黄鹤风流", "四川和贵州：川肴蜀绣渝州城，花径草堂；苗寨黔山黄果树，茅台赤水", "内蒙古和黑龙江：碧草毡房，春风马背牛羊壮；苍松雪岭，沃野豆谷千里香"], "a": 1, "e": "【B】A项错误，黄山位于安徽，上联正确；与中国同名中的“瓷器”指的是景德镇的瓷器，下联描述的应当为江西省，故排除。B项正确，上联中的洞庭湖和岳阳楼均位于湖南省；下联黄鹤楼和赤壁古战场均位于湖北省，且运用了三国时期“赤壁之战”的典故，符合题意。C项错误，上联中渝州城指今重庆，重庆为直辖市，不属于四川省，故排除。D项错误，上下联分别描述了内蒙古和黑龙江的景象，但是“牛羊壮”与“千里香”对仗不工整，“壮”是“牛羊”的特征，而“香”并不是“千里”特征，故排除。故正确答案为B。", "tag": "地理国情"},
{"id": "geo-34", "q": "人口增长模式包括原始型、传统型、现代型三种。目前，我国已基本实现了从（）的转变。", "options": ["原始型向传统型", "原始型向现代型", "现代型向传统型", "传统型向现代型"], "a": 3, "e": "【D】D项符合题意：人口增长模式，又称人口转变模式，它反映了不同国家和地区的人口出生率、死亡率和自然增长率随社会经济条件变化而变化的规律。人口增长模式有三种类型：①原始型：高出生率，高死亡率，低自然增长率（高高低）；②传统型：高出生率，低死亡率，高自然增长率（高低高）；③现代型：低出生率，低死亡率，低自然增长率（低低低）。我国的人口模式已基本实现了从高、低、高向低、低、低的转变，即由传统型向现代型的转变。故正确答案为D。", "tag": "地理国情"},
{"id": "geo-35", "q": "世界上多数国家都采用以区时为单位的标准时。关于时间，以下认识不正确的是：", "options": ["所有时区都以格林尼治本初子午线为基础", "国际日期变更线的西边要比东边晚一天", "许多国家在夏季人为地把时钟拨快一小时，使用夏令时间", "全球共分为24 个时区，每个时区都有自己的时间"], "a": 1, "e": "【B】A项正确，为了克服时间上的混乱，1884年在华盛顿召开的一次国际经度会议上，规定将全球划分为24个时区（东、西各12个时区）。规定英国（格林尼治天文台旧址）为中时区（零时区），向东为东1~12区，向西为西1~12区。每个时区横跨经度15度，时间正好是1小时。故所有时区都以格林尼治本初子午线为基础。B项错误，按照规定，凡越过国际日期变更线时，日期都要发生变化：从东向西越过这条界线时，日期要加一天；从西向东越过这条界线时，日期要减去一天。即国际日期变更线的西边要比东边早一天。C项正确，夏时制，是一种为节约能源而人为规定地方时间的制度，在这一制度实行期间所采用的统一时间称为“夏令时间”。一般在天亮早的夏季人为将时间调快一小时，可以使人早起早睡，减少照明量，以充分利用光照资源，从而节约照明用电。D项正确，“区时系统”规定，地球上每15°经度范围作为一个时区。这样，整个地球的表面就被划分为24个时区。每一时区都按它的中央子午线来计量时间，即采用它的中央子午线的地方平时，叫作标准时。本题为选非题，故正确答案为B。", "tag": "地理国情"},
{"id": "geo-36", "q": "根据《联合国海洋法公约》，下列四幅示意图中，关于三个区域位置，表示正确的是：", "options": ["A", "B", "C", "D"], "a": 0, "e": "【A】A项正确：根据《联合国海洋法公约》的规定：领海是指沿海国的主权及于其陆地领土及其内水以外邻接的一带定的基线量起不超过十二海里的界限为止。毗连区从测算领海宽度的基线量起，不得超过二十四海里。专属经济区从测算领海宽度的基线量起，不应超过二百海里。因此，选项中从内至外应该依次为领海、毗连区、专属经济区。A项正确。故正确答案为A。", "tag": "地理国情"},
{"id": "geo-37", "q": "我国地大物博，许多风景名胜和古迹分布在名山大川之中。下列关于我国风景名胜的叙述中，有错误的是：", "options": ["九寨沟国家级自然保护区以丹霞地貌而闻名，这里赋予大熊猫、金丝猴等珍稀动物以优良的自然生态环境", "澜沧江、怒江、金沙江并流称为“三江并流”，是地质地貌类型多样性的博物馆", "地处武陵山脉腹地的我国第一个国家森林公园——由张家界、天子山、索溪峪、杨家界四个景区组成", "青海西南部玉树藏族自治州境内的可可西里自然保护区，拥有野牦牛、藏羚羊、野驴等青藏高原上特有的野生动物"], "a": 0, "e": "【A】本题考查的是我国的地理国情，考查了考生对我国著名风景名胜的了解。A项错误：九寨沟地处青藏高原向四川盆地过渡地带，地质背景复杂，碳酸盐分布广泛，褶皱断裂发育，新构造运动强烈，发育了大规模喀斯特作用的钙华沉积，以喀斯特地貌闻名，而非丹霞地貌。B项正确：“三江并流”是指金沙江、澜沧江和怒江这三条发源于青藏高原的大江，“三江并流”地区是世界上蕴藏最丰富的地质地貌博物馆。C项正确：张家界国家森林公园地处武陵山脉东段，境内多山，是我国第一个国家森林公园，由张家界、天子山、索溪峪、杨家界四个景区组成。D项正确：青海可可西里国家级自然保护区位于青海省玉树藏族自治州西部，是21世纪初世界上原始生态环境保存较好的自然保护区，主要是保护藏羚羊、野牦牛、藏野驴、藏原羚等珍稀野生动物、植物及其栖息环境。本题为选非题，故正确答案为A。【备注】本题A项存在明显的知识性错误，应为当选项（本题为单选题）。小粉笔经教研后认为，本题C项表述存在一些缺漏，准确的表述应为：地处武陵山腹地的武陵源风景区由我国第一个国家森林公园——张家界国家森林公园、天子山、索溪峪、杨家界四个景区组成。因无法查证考场中试卷中原表述版本，小粉笔现就网友回忆版题目存在的值得商榷之处作以说明，学员掌握C项中知识点即可。", "tag": "地理国情"},
{"id": "geo-38", "q": "人口红利是指一个国家的劳动年龄人口占总人口比重较大，抚养率比较低，为经济发展创造了有利的人口条件。目前，我国正处于人口红利的（）阶段。", "options": ["成熟", "发展", "停滞", "下降"], "a": 3, "e": "【D】1990年我国进入人口红利期，1990年—2010年人口红利逐步提升，2010年抚养比下降到34.2%最低值、人口红利上升到峰值；其后人口红利逐渐衰减，2030年前后衰减为零并随即转变到人口负债期；而后负债率逐步走高，2050年抚养比将达到62%左右，负债率也将创出新高。A应属于2010年的成熟时期。B属于90年代到2010年的上升时期，目前我国人口红利是下降趋势。C是未来的老龄化社会时期，也排除。故正确答案为D。", "tag": "地理国情"},
{"id": "geo-39", "q": "2016 年一号文件聚焦加快农业现代化，对此，下列理解正确的是：", "options": ["一号文件将促进农业的规模经营，提升农业在产业结构中的比重", "一号文件将激发农业的科技创新，以服务业带动农业现代化的发展", "一号文件将推动农村的产业融合，促进农民收入的持续较快增长", "一号文件将带动农村基础设施建设，依靠社会资本加快新农村建设"], "a": 2, "e": "【C】C项正确：2016年中央一号文件《中共中央国务院关于落实发展新理念加快农业现代化实现全面小康目标的若干意见》包括六个部分，其中第三部分为“推进农村产业融合，促进农民收入持续较快增长”；A项错误：一号文件将促进农业的规模经营，但产业结构比重需要提升的是先进制造业、现代服务业和战略性新兴产业，而不是农业；B项错误：一号文件将推进农业供给侧结构性改革，但不是以服务业来带动农业现代化发展，而是通过加快转变农业发展方式，保持农业稳定发展和农民持续增收，有序推动农业现代化发展；D项错误：一号文件将加快农村基础设施建设，但不是依靠社会资本加快新农村建设，而是通过把国家财政支持的基础设施建设重点放在农村，建好、管好、护好、运营好农村基础设施，实现城乡差距显著缩小。故正确答案为C。", "tag": "地理国情"},
{"id": "geo-40", "q": "农业是国民经济中的第一产业，对于中国这样的人口大国，农业具有战略性地位。以下关于我国农业的表述，错误的是：", "options": ["我国最早的耕作技术是原始社会的人力耕作", "《三字经》中，将稻、粱、菽、麦、黍、稷并称为六谷", "今天我国广为种植的一些作物并非原产我国，而是外来引进，例如玉米", "休闲农业是利用农业景观资源和农业生产条件，发展观光、休闲、旅游的一种新型农业生产经营形态"], "a": 0, "e": "【A】A项错误：我国最早的耕作技术是原始社会的火耕。《淮南子•本经训》记载的“焚林而田”，以及人们常说的“刀耕火种”，即是火耕法。B项正确：《三字经》原文为“稻粱菽，麦黍稷，此六谷，人所食”。C项正确：除了玉米，我国广为种植的一些外来作物还有番薯、马铃薯、南瓜、花生、番茄等。D项正确：休闲农业是利用农业景观资源和农业生产条件，发展观光、休闲、旅游的一种新型农业生产经营形态。本题为选非题，故正确答案为A。", "tag": "地理国情"},
{"id": "geo-41", "q": "在民族大团结邮票中，下列图案和民族对应正确的是：", "options": ["", "", "", ""], "a": 3, "e": "【D】A项错误，不是朝鲜族而是傣族。图中出现了象脚鼓，该乐器是傣族的重要民间乐器。B项错误，不是藏族而是满族。图中有明显的满族头饰。C项错误，不是回族而是维吾尔族。从图中女孩子的小皮靴和帽子就可以看出来明显具有维吾尔族的特点。回族男的一般戴小白帽子。D项正确，该项为蒙古族。故正确答案为D。", "tag": "地理国情"},
{"id": "geo-42", "q": "“一带一路”是中国全新的对外开放战略。下列关于“一带一路”说法错误的是：", "options": ["可纳入的国家和地区范围是开放的", "吉林省是“一带一路”圈定的重点省份之一", "指“丝绸之路经济带”和“21 世纪海上丝绸之路”", "是区域经济合作发展的实体"], "a": 3, "e": "【D】D项说法错误，“一带一路”是习近平主席在2013年9月和10月出访中亚和东南亚国家期间先后提出的，“一带一路”是“丝绸之路经济带”和“21世纪海上丝绸之路”的简称。它是一项有利于促进沿线各国经济繁荣与区域经济合作的重大倡议，并非区域经济合作发展的实体。A、B、C项说法均正确。本题为选非题，故正确答案为D。", "tag": "地理国情"},
{"id": "geo-43", "q": "根据《中共中央关于全面推进依法治国若干重大问题的决定》，下列哪些属于重大行政决策的法定程序？①公众参与②专家论证③风险评估④合法性审查⑤集体讨论", "options": ["①②③⑤", "②③④⑤", "①②④⑤", "①②③④⑤"], "a": 3, "e": "【D】党的十八届四中全会通过了《中共中央关于全面推进依法治国若干重大问题的决定》。该《决定》提出，要把公众参与、专家论证、风险评估、合法性审查、集体讨论决定确定为重大行政决策法定程序，确保决策制度科学、程序正当、过程公开、责任明确。本题中，①②③④⑤均属于重大行政决策的法定程序。故正确答案为D。", "tag": "地理国情"},
{"id": "geo-44", "q": "关于2015 年山东省重大基础设施建设规划，下列表述不正确的是：", "options": ["启动建设济青高速公路扩容项目", "加快建设济南至东营等15 条高速公路", "争取青岛新机场、菏泽机场、聊城机场开工建设", "加快济青高铁、鲁南铁路、石济客专、青连城际等9 条铁路的建设"], "a": 3, "e": "【D】2015年1月，山东省省长郭树清代表山东省人民政府作了《政府工作报告》，提出2015年要继续加强重大基础设施建设，开工建设济青高铁、鲁南快速铁路，加快石济客专、青连城际等8条铁路建设进度；启动建设济青高速公路扩容项目，加快建设济南至东营等15条高速公路；争取青岛新机场、菏泽机场、聊城机场开工建设，基本完成日照机场主体工程。A、B、C三项表述均正确，D项“9条铁路”的表述错误。本题为选非题，故正确答案为D。", "tag": "地理国情"},
{"id": "geo-45", "q": "下列关于国家主权及国防地理的表述，不正确的是：", "options": ["主权是联合国赋予国家的最基本的权利", "一国的领海和领空都是其领土的组成部分", "我国与越南、缅甸、吉尔吉斯斯坦等十几个国家接壤"], "a": 0, "e": "【A】A项错误，主权是一种对某地域、人民或个人所施展的至高无上、排他的政治权威，是国家最基本的特征之一，其法律形式对内常规定于宪法或基本法中，对外则是国际的相互承认，并非由某一机构组织赋予。联合国成立于1945年，在其成立之前，国家就具有主权。B、C、D三项均正确。本题为选非题，故正确答案为A。", "tag": "地理国情"},
{"id": "geo-46", "q": "改革开放以来，我国主要区域政策经历了不同的阶段：①以经济特区为重心的沿海地区优先发展阶段；②以缩小区域差异为导向的西部大开发阶段；③以浦东开发为龙头的沿江沿边地区重点发展阶段；④以区域协调发展为导向的共同发展阶段。这四个阶段按时间顺序排列为：", "options": ["①②③④", "①③②④", "②③①④", "②①③④"], "a": 1, "e": "【B】本题是从宏观上来阐述经济区域的发展。首先，我国区域经济政策选了一个点，就是经济特区，1979年开始建立深圳特区；其次，我们国家的经济政策是趋向于“以点带面”来发展，所以有了以浦东开发为龙头的沿江沿边地区重点发展；随着我国经济区域发展的面越来越广，因此有了“西部大开发”战略；随着以点带面的成功，最后走向共同发展，即以区域协调发展为导向的共同发展阶段。故正确答案为B。", "tag": "地理国情"},
{"id": "geo-47", "q": "下列各省份及其对应的广告宣传语中，最不恰当的是：", "options": ["广东：看漓江碧水，听春天故事", "海南：享南国椰风，望江东新区", "山西：魅力山西，晋善晋美", "河南：华夏之源，天下之中"], "a": 0, "e": "【A】本题考查地理国情。A项错误，“听春天故事”是指听《春天的故事》这首歌，这首歌是为了纪念改革开放与深圳特区的开创而创作的，因此符合广东的定位。但是漓江属珠江流域西江水系，位于广西壮族自治区东北部，不在广东，因此不恰当。B项正确，海南省位于我国最南端，自然资源丰富，物种多样，其中椰子树是海南岛典型的树种。江东新区是海南省海口市的一个市辖区，到2035年，将建设成为全面深化改革试验区的创新区，为全球未来城市建设树立“江东样板”。C项正确，“晋善晋美”是山西旅游主题宣传口号，用简洁的文字浓缩了山西旅游的整体印象，用直白的语言告诉公众，山西是人善景美、适宜旅游观光的好地方，同时寓意山西旅游产业蓬勃向上，追求尽善尽美。D项正确，河南历史文化悠久，是世界华人宗祖之根、华夏历史文明之源；文化灿烂，人杰地灵，名人辈出，是中国姓氏的重要发源地。河南地区孕育了裴李岗文化、龙山文化，建立了中国第一个奴隶制国家-夏朝。以后，商代的首都西亳和殷均在河南境内。在安阳殷墟发现的甲骨文，是世界上最早的文字，也是世界上最早的历史文献。河南区位优越，位居天地之中，素有“九州腹地，十省通衢”之称，因此“华夏之源，天下之中”的宣传语是恰当的。本题为选非题，故正确答案为A。", "tag": "地理国情"},
{"id": "geo-48", "q": "发源于长白山的松花江滋养了东北大地，与东北人的生活息息相关。下列关于松花江表述错误的是：", "options": ["松花江是东北境内航运价值较大的河流", "松花江流域属温带大陆性季风气候", "松花江是中国黑龙江最小的支流", "吉林市位于松花江沿岸"], "a": 2, "e": "【C】本题考查的是地理国情相关知识。A项正确，松花江通航里程约1500公里，吉林市、齐齐哈尔市以下可通航汽轮；哈尔滨市以下可通航千吨江轮。通航期一般为4月中旬至11月上旬，是东北境内航运价值较大的河流。B项正确，温带季风气候在我国主要分布在东部秦岭—淮河一线以北地区。松花江流域地处温带季风气候区，气候特点为夏季高温多雨，冬季寒冷干燥，松花江属于温带大陆性季风气候。C项错误，松花江是黑龙江在中国最大的支流，而非最小的支流。D项正确，吉林市位于吉林省中部，东北腹地长白山脉，长白山向松嫩平原过渡地带的松花江畔。吉林市满语名为“吉林乌拉”，意为“沿江的城池”。本题为选非题，故正确答案为C。", "tag": "地理国情"},
{"id": "geo-49", "q": "2017 年12 月5 日，世界互联网大会在浙江乌镇落下帷幕。下列有关表述错误的是:", "options": ["乌镇是世界互联网大会永久会址", "乌镇地处杭嘉湖平原腹地，属典型的温带季风气候", "乌镇已举办四届世界互联网大会", "乌镇是著名作家茅盾的故乡"], "a": 1, "e": "【B】本题考查地理国情，主要涉及乌镇的相关知识。A项正确，世界互联网大会是由中华人民共和国倡导并每年在浙江省嘉兴市桐乡市乌镇举办的世界性互联网盛会。2014年开始，乌镇成为世界互联网大会永久会址。B项错误，乌镇，位于浙江省嘉兴市桐乡市，地处江浙沪“金三角”之地、杭嘉湖平原腹地，属亚热带季风气候。C项正确，第一届世界互联网大会于2014年11月19日-21日在浙江乌镇举办；第二届世界互联网大会于2015年12月", "tag": "地理国情"},
{"id": "geo-50", "q": "下列各银行英文缩写中，不正确的是：", "options": ["中国工商银行：ICBC.", "中国农业银行：ABC.", "中国银行：BOC.", "中国建设银行：COB."], "a": 3, "e": "【D】A项正确，中国工商银行，IndustrialandCommercialBankofChina，简称ICBC。B项正确，中国农业银行，AgriculturalBankofChina，简称ABC。C项正确，中国银行，BankofChinaLimited，简称BOC。D项错误，中国建设银行，ChinaConstructionBank，简称CCB。本题为选非题，故正确答案为D。", "tag": "地理国情"},
{"id": "geo-51", "q": "“陕北大红枣”是驰名中外的陕西特产之一，其主要产地位于黄河沿岸各县区。下列不属于“陕北大红枣”主要产区的是：", "options": ["定边、靖边、吴起", "神木、吴堡、佳县", "神木、府谷、绥德", "宜川、延川、清涧"], "a": 0, "e": "【A】陕北大红枣主要产于黄河沿岸的宜川、延川、清涧、吴堡、佳县、神木、府谷、绥德等县，故B、C、D三项全部正确。本题为选非题，故正确答案为A。", "tag": "地理国情"},
{"id": "geo-52", "q": "下列关于我国地理位置的表述，不正确的是：", "options": ["中国领土东西跨经度有60 多度，跨了5 个时区", "中国与尼泊尔等16 个国家陆地接壤", "同中国隔海相望的国家共有6 个", "中国濒临渤海、黄海、东海、南海四大海域"], "a": 1, "e": "【B】本题考查地理国情。中国位于亚洲东部、太平洋的西岸。领土辽阔广大，总面积约960万平方千米，仅次于俄罗斯、加拿大，居世界第3位。A项正确，中国领土东西跨越经度60多度，最东端的乌苏里江畔和最西端的帕米尔高原相差5个时区；南北跨越的纬度近50度，大部分在温带，小部分在热带，没有寒带。B项错误，我国陆上接壤的国家有14个：朝鲜、俄罗斯、蒙古、哈萨克斯坦、吉尔吉斯斯坦、塔吉克斯坦、阿富汗、巴基斯坦、印度、尼泊尔、不丹、缅甸、老挝、越南。C项正确，同中国隔海相望的国家有六个：隔南海相望的有菲律宾、马来西亚、文莱、印度尼西亚；隔黄海相望的是韩国；隔东海相望的是日本。D项正确，中国领海自北向南为渤海、黄海、东海和南海，渤海为内海。本题为选非题，故正确答案为B。", "tag": "地理国情"},
{"id": "geo-53", "q": "下列关于“中国之最”的表述正确的是：", "options": ["四川盆地是中国陆地最低点", "华北平原是中国面积最大的平原", "洞庭湖是中国最深的湖泊", "舟山渔场是中国最大的渔场"], "a": 3, "e": "【D】本题考查地理国情。A项错误，我国陆地最低点在新疆吐鲁番盆地的艾丁湖。吐鲁番盆地大部分海拔在500米以下，艾丁湖海拔为-155米，而四川盆地山地海拔多在1000米-3000米之间，所以吐鲁番盆地的艾丁湖才是中国陆地最低点。B项错误，东北平原是中国面积最大的平原。东北平原或称松辽平原、关东平原，是中国三大平原之一，面积达35万平方千米，华北平原地势平坦，河湖众多，交通便利，经济发达，自古即为中国政治、经济、文化中心，面积约30万平方千米。C项错误，长白山天池是中国最深的湖泊，湖面海拔2155米，面积9.2平方公里，平均水深204米，为中朝两国界湖。D项正确，舟山渔场位于杭州湾以东，长江口东南的浙江东北部，面积约5.3万平方公里，是中国最大的渔场，是浙江省、江苏省、福建省和上海市三省一市及台湾渔民的传统作业区域，以大黄鱼、小黄鱼、带鱼和墨鱼(乌贼)四大经济鱼类为主要渔产。故正确答案为D。", "tag": "地理国情"},
{"id": "geo-54", "q": "“紫荆绽后白莲开，喜事蹁跹接踵来。神州大地齐欢庆，一国两制添新彩。”这首诗最可能创作于（）。", "options": ["1984 年", "1997 年", "1999 年", "2005 年"], "a": 2, "e": "【C】本题考查了国情社情。紫荆花是香港特别行政区的区花，白莲花是澳门特别行政区的区花。全诗描述的是，邓小平同志为了实现中国统一的目标而提出了“一国两制”的方针，并成功解决了香港问题和澳门问题，香港于1997年回归，澳门于1999年回归，即本诗的创作时间最有可能是1999年。故正确答案为C。", "tag": "地理国情"},
{"id": "geo-55", "q": "北京作为世界著名古都，名胜古迹众多，其中在市二环路边坐落着一座藏传佛教皇家寺院，它是：", "options": ["恭王府", "雍和宫", "大钟寺", "历代帝王庙"], "a": 1, "e": "【B】本题主要考查北京的市情，考查考生对于北京名胜古迹的了解。A项错误：恭王府是清代规模最大的一座王府，曾经是文华殿大学士和珅、庆亲王永璘的宅邸，位于北京西城区前海西街；B项正确：雍和宫是北京现存最大的一座藏传佛教寺院，位于北京东城区二环路边上；C项错误：大钟寺原名觉生寺，原为皇家佛教寺庙，现为古钟博物馆，位于北京海淀区北三环路；D项错误：历代帝王庙俗称帝王庙，是明清两代皇帝祭祀先祖的地方，位于北京西城区阜成门内大街路北。故正确答案为B。", "tag": "地理国情"},
{"id": "geo-56", "q": "下列关于我国的国家中心城市的说法，错误的是：", "options": ["目前确定的国家中心城市中已包含了所有的直辖市", "目前确定的国家中心城市中最靠西的城市是重庆市", "国家中心城市的政治、经济、文化等多方面具备引领、辐射、集散功能", "国家中心城市在《全国城镇体系规划》中处于城镇体系层级的最高位置"], "a": 1, "e": "【B】划》中首次明确提出，成都要以建设国家中心城市为目标，增强成都西部地区重要的经济中心、科技中心、文创中心、对外交往中心和综合交通枢纽功能。而北京、天津、上海和广州均位于我国东部，只有重庆和成都位于我国的西南地区。而成都比重庆更靠西，因此，目前确定的国家中心城市中，最靠西的城市是成都市。A、C、D正确：国家中心城市是住房和城乡建设部编制的《全国城镇体系规划》中提出的处于城镇体系最高位置的城镇层级。国家中心城市在全国具备引领、辐射、集散功能的城市，这种功能表现在政治、经济、文化、对外交流等多方面。", "tag": "地理国情"},
{"id": "geo-57", "q": "下列关于对外开放的历史事件，按照实际先后顺序排列正确的是：①设立经济特区②推进“一带一路”建设③开放沿海城市④全面开放沿边、沿江及内陆省会城市⑤开发开放浦东新区", "options": ["①③④⑤②", "①③⑤④②", "①④③⑤②", "①⑤③④②"], "a": 1, "e": "【B】①1979年4月30日，邓小平首次提出要开办“出口特区”，后于1980年3月24日将“出口特区”改名为“经济特区”，并在深圳加以实施。1980年5月，中共中央和国务院决定将深圳、珠海、汕头和厦门这四个出口特区改称为经济特区。②2013年9月和10月，中国国家主席习近平在出访中亚和东南亚国家期间，先后提出共建“丝绸之路经济带”和“21世纪海上丝绸之路”的重大倡议，得到国际社会高度关注。2016年04月23日，中国“一带一路”规划正式公布。③沿海开放城市是中国沿海地区对外开放的、并在对外经济活动中实行经济特区的某些特殊政策的一系列港口城市。", "tag": "地理国情"},
{"id": "geo-58", "q": "北京天然河道自西向东有五大水系，其中位于最西部的水系是（）", "options": ["北运河水系", "永定河水系", "潮白河水系", "拒马河水系"], "a": 3, "e": "【D】北京天然河道自西向东贯穿五大水系：拒马河水系、永定河水系、北运河水系、潮白河水系、蓟运河水系。多由西北部山地发源，向东南蜿蜒流经平原地区，最后分别汇入渤海。A项错误，发源于北京军都山，流经昌平、顺义和朝阳至通州区北关，始称北运河，是北京最主要的排水渠道。B项错误，永定河古称漯水、治水，又名卢沟河、浑河、无定河。其上源分南北两支流：北支为洋河，发源于内蒙兴和县，经怀安、宣化、怀来流入官厅水库；南支为桑干河，发源于山西省宁武县，经朔州市朔城区、山阴、大同县、阳原、怀来流入官厅水库。C项错误，由潮河和白河两条水系组成，潮河发源于河北丰宁县，白河发源于河北沽源县，两河交汇于密云城南十里堡，潮白河是密云水库的主要水源。D项正确，发源于河北省涞源县西北太行山麓，在北京市房山区十渡镇套港村入市界，流经十渡风景区、张坊镇、南尚乐乡。故正确答案为D。", "tag": "地理国情"},
{"id": "geo-59", "q": "马基雅维利的法律思想颇有几分中国古代儒家的民本主义色彩。在《君主论》一书中，他强调说“君主统治稳固的基本条件就是他的臣民不憎恨他”，“君主最坚固的堡垒就是人民的支持”，“人民的支持是挫败阴谋的保障”。关于君主如何赢得人民的支持，马基雅维利言简意赅地指出：“只要不对公民或臣民的财产妻女打主意就行了。至关重要的是，不要妄动别人的财产。”从材料可看出，马基雅维利思想与下列儒家思想表述最接近的一项是：", "options": ["君之视臣如手足，则臣之视君如腹心；君之视臣如土芥，则臣之视君如寇仇", "鸡豚狗彘之畜，无失其时，七十者可以食肉矣。百亩之田，勿夺其时，数口之家，可以无饥也", "得天下有道，得其民，斯得天下也。得其民有道，得其心，斯得民矣。得其心有道，所欲与之聚之，所恶勿施尔也", "王如好货，与百姓同之，于王何有？王如好色，与百姓同之，于王何有"], "a": 2, "e": "【C】A项：该项说的是君臣关系，不符合题目人民和君主的范围界定，排除。B项：该项大致意思是鸡狗与猪这类家畜，不去打乱它的繁殖期，那么，七十岁以上的人就都有肉可吃了。一家给他一百亩土地，并且不去打乱它季节生长的规律，那么数口人的家庭便都可以吃得饱饱的了，排除。C项：该项意思是要得天下的办法就是去获得民众的支持，做到了就能得到天下；要获得支持的办法就是获得他们的认可，做到了就能得到；要获得民众认可的办法就是做民众期望的，不要做他们反感的。此项与材料中马基雅维利的思想最接近，当选。D项错误，该项意思是王如喜好财货（女色），能和百姓共同享用它。对比题干中的逻辑关系只有C项最为合适。故正确答案为C。", "tag": "地理国情"},
{"id": "geo-60", "q": "下列依次与蒙古族、回族、傣族关系最密切的是：", "options": ["酥油茶、馓子、青稞酒", "马头琴、冬不拉、葫芦丝", "那达慕大会、开斋节、泼水节", "努尔哈赤、阿凡提、刘三姐"], "a": 2, "e": "【C】A项：酥油茶和青稞酒是藏族的特色饮食，馓子在我国的南北方都有分布，少数民族中以维吾尔族、东乡族和纳西族以及宁夏回族的馓子最为有名，排除；B项：马头琴是蒙古族的特色乐器，冬不拉是哈萨克族的乐器，葫芦丝是云南少数民族乐器，主要流传于傣、彝、阿昌、德昂等民族中，排除；C项：那达慕大会是蒙古族历史悠久的传统节日，在每年七、八月牲畜肥壮的季节举行，是人们为了庆祝丰收而举行的文体娱乐大会。开斋节是伊斯兰三大宗教节日之一（另两个为古尔邦节与圣纪）。泼水节是傣族以及泰语民族和东南亚地区的传统节日，是傣族的新年，相当于公历的四月中旬，一般持续3至7天，当选；D项：努尔哈赤是清王朝的奠基者，是女真（今满族）的历史人物。阿凡提是伊斯兰世界传说人物。刘三姐是民间传说的壮族人物，排除。故正确答案为C。", "tag": "地理国情"},
{"id": "geo-61", "q": "大量议案、提案是每年两会的焦点。关于议案与提案的区别，下列说法错误的是：", "options": ["议案用于人大会议，提案用于政协会议", "议案一经通过便具有法律效力，提案没有法律效力", "议案内容应在受案者职权范围内，提案不限内容", "议案可由个人提出，提案必须由团体提出"], "a": 3, "e": "【D】议案是具备提议案的法定资格的机构或符合法定联名人数的人大代表向国家权力机关即人民代表大会提出的议事原案。提出议案的主体，必须具备提议案的法定资格或符合法定的代表联名人数。所提内容必须是属于议事机关职权范围内的事项。提案是政协委员、政协各专门委员会和政协各参加单位通过人民政协组织向人民代表大会或人民政府就有关国家或地方大政方针、社会生活等重大问题提出意见和建议的形式。政协提案实行提出提案的时间不限、内容不限、人数不限的“三不限制”原则。故D项说法错误，A、C两项说法正确。由于人民代表大会是国家最高权力机关，人大的议案一经通过，就具有法律效力，而人民政协是爱国统一战线组织，政协委员提案是民主监督的一种形式，没有法律约束力。B项说法也正确。本题为选非题，故正确答案为D。", "tag": "地理国情"},
{"id": "geo-62", "q": "“四个全面”是党中央治国理政的全新战略布局，奏响了实现中华民族伟大复兴中国梦的强劲旋律。“四个全面”是指：", "options": ["全面建成小康社会、全面深化改革、全面推进依法治国、全面从严治党", "全面建设生态文明、全面对外开放、全面推进经济转型、全面治理腐败", "全面建设文化强国、全面深化改革、全面推进依法治国、全面治理环境", "全面建成小康社会、全面对外开放、全面推进农村改革、全面从严治党"], "a": 0, "e": "【A】党的十八大以来，以习近平同志为总书记的党中央从坚持和发展中国特色社会主义全局出发，提出并推动形成了“四个全面”全新战略布局，即全面建成小康社会、全面深化改革、全面推进依法治国、全面从严治党，确立了新形势下党和国家各项工作的战略目标和战略举措，开辟了党中央治国理政的新境界，奏响了实现中华民族伟大复兴中国梦的强劲旋律。故正确答案为A。", "tag": "地理国情"},
{"id": "geo-63", "q": "下列我国的世界遗产所在省（区）不属于黄河流域的是：", "options": ["五台山", "莫高窟", "避暑山庄", "孔庙、孔府及孔林"], "a": 2, "e": "【C】C项“避暑山庄”位于河北省承德市市区北部，不属于黄河流域。A项“五台山”位于山西省；B项“莫高窟”位于甘肃省；D项“孔庙、孔府及孔林”位于山东省，这些省份均属于黄河流域的范围。本题为选非题，故正确答案为C。", "tag": "地理国情"},
{"id": "geo-64", "q": "关于我国农业，下列说法正确的是：", "options": ["农民直接从棉株上采下来的棉花称作皮棉", "甘蔗是我国最主要的糖料作物", "花生是我国播种面积最大的油料作物", "“三大谷物”指的是稻谷、小麦和高粱"], "a": 1, "e": "【B】B项正确，我国的糖料作物，南方以甘蔗为主，北方以甜菜为主，但甘蔗的种植范围和规模远大于甜菜。因此，总体上看，我国最重要的糖料作物是甘蔗。A项错误，农民直接从棉株上采下来的棉花是“籽棉”，皮棉是把籽棉进行扎花，脱离了棉籽的棉纤维。C项错误，我国播种面积最大的油料作物是油菜，主要分布在长江流域。D项错误，“三大谷物”指的是稻谷、玉米和小麦。故正确答案为B。", "tag": "地理国情"},
{"id": "geo-65", "q": "2014 年政府工作报告指出要着重解决好现有“三个1 亿人”问题，指的是：", "options": ["促进约1 亿农业转移人口落户城镇，改造约1 亿人居住的城镇棚户区和城中村，引导约1 亿人在中西部地区就近城镇", "解决约1 亿农村人口的吃饭问题，解决约1 亿农村人口的饮水安全问题，改善约1 亿贫困地区农村儿童营养状况", "促进约1 亿城镇人口就业，解决约1 亿城镇人口就近就医问题，解决约1 亿城镇老年人口养老问题", "引导约1 亿农民工在中西部地区就近就业，促进约1 亿城镇下岗人员再就业，减少约1 亿贫困人口"], "a": 0, "e": "【A】2014年，李克强总理在政府工作报告中提出，今后一个时期，着重解决好现有“三个1亿人”问题，促进约1亿农业转移人口落户城镇，改造约1亿人居住的城镇棚户区和城中村，引导约1亿人在中西部地区就近城镇化。故正确答案为A。", "tag": "地理国情"},
{"id": "geo-66", "q": "今天，社会经济和结构调整，价值和利益多元多样，任何一项改革措施的出台，都要遇到不同声音，遭受很多阻力，这很正常，重要的是统筹各方利益，汇聚真知灼见，找到改革的“最大约数”，形成推动改革的合力。从哲学角度讲，这个“最大公约数”应该是：", "options": ["党和政府的政策主张", "人们对改革的正确认识", "改革开放的伟大实践", "最广大人民的根本利益"], "a": 3, "e": "【D】从题干可知，要改革，就会触碰到各方利益，只有平衡好各方利益，找到平衡点，才能激发社会内生动力的关键大人民的根本利益。故正确答案为D。", "tag": "地理国情"},
{"id": "geo-67", "q": "如果一个社会10 个人只有4 个人就业，另外6 个人失业，社会保障体系就要用4 个人的收入支持另外6 个人的保障；如果一个社会10 个人中有9 个人就业，只有1 个人失业，那么社会保障体系就很容易高质量地建立起来。这说明：", "options": ["健全社会保障制度是维护劳动者合法权益的根本措施", "社会保障体系的完善需要经济发展为其奠定物质基础", "就业是民生之本，我们要实施积极的就业政策", "坚持权利与义务相统一是每个劳动者的正确选择"], "a": 1, "e": "【B】从题干叙述“一个社会10个人中有9个人就业，只有1个人失业，那么社会保障体系就很容易高质量地建立起来”，9个人就业，意味着经济得到发展，就业充分，而就业一旦充分，社会保障体系便得以高效高质地建立，由此说明，社会保障体系的完善需要经济发展为其奠定物质基础，B项正确。A项错误，维护劳动者合法权益的根本措施是签订劳动合同。C项强调的是实施积极的就业政策，题干并没有谈及就业政策的问题，属于无关选项。D项强调的是劳动者权利与义务，同样与题干无关。故正确答案为B。", "tag": "地理国情"},
{"id": "geo-68", "q": "我国水能资源分布不均，水能资源最集中的地区是（）。", "options": ["东北地区", "中南地区", "西南地区", "东部沿海地区"], "a": 2, "e": "【C】C项正确：水能资源丰富需要满足有大江大河、水量丰沛且落差较大等条件。贵州、西藏、云南、四川等省区多大江大河，且横断山脉等地地势高低起伏变化较大，水流湍急，蕴藏着丰富的水能资源。A项错误：东北地区以平原为主，地势变化小，水能资源不丰富。B项错误：中南地区多为丘陵、平原等，水能资源没有西南地区丰富。D项错误：东部沿海地区虽然降水量大，但地势变化较小，水能资源也不丰富。故正确答案为C。", "tag": "地理国情"},
{"id": "geo-69", "q": "下列有关地理知识的表述不正确的是：", "options": ["“丹霞山世界地质公园”经联合国教科文组织批准为中国首批世界地质公园之一", "秦始皇为沟通湘江和漓江之间的航运，开挖了灵渠", "“和田玉”是我国四大名玉之一，主要产自新疆", "我国位于北温带内，属于温带气候"], "a": 3, "e": "【D】丹霞山世界地质公园总面积319平方公里，2004年经联合国教科文组织批准为中国首批世界地质公园之一，故A项正确。灵渠位于今广西桂林市兴安县境内，开凿于秦始皇三十三年（公元前214年），它的出现沟通了湘江（长江支流）与漓江（珠江支流），从而将长江和珠江这两大南方水系联系在一起，故B项正确。中国四大名玉分别指新疆的“和田玉”、河南南阳的“独山玉”、陕西西安的“蓝田玉”及辽宁岫岩的“岫玉”，故C项正确。我国地域辽阔，南北跨度大，具有热带、亚热带和温带等多种热量带，故D项表述片面。本题为选非题，故正确答案为D。", "tag": "地理国情"},
{"id": "geo-70", "q": "关于2013 年我国各项工作的完成情况，下列表述不正确的是：", "options": ["城乡居民收入差距继续缩小", "进出口总额突破4 万亿美元", "粮食产量较上年略有减少", "国内生产总值超过50 万亿元"], "a": 2, "e": "【C】本题考查2014年政府工作报告中的内容。A项正确，城镇居民人均可支配收入实际增长7%，农村居民人均纯收入实际增长9.3%，农村贫困人口减少1650万人，城乡居民收入差距继续缩小，排除；B项正确，进出口总额突破4万亿美元，再上新台阶。居民收入和经济效益持续提高，排除；C项错误，粮食产量超过1.2万亿斤，实现“十连增”，当选；D项正确，经济运行稳中向好。国内生产总值达到56.9万亿元，比上年增长7.7%，排除。本题为选非题，故正确答案为C。", "tag": "地理国情"},
{"id": "geo-71", "q": "由于地理位置、宗教信仰、历史文化等方面的差异，世界各地存在截然不同的饮食习惯。下列情况中，符合现实的是：", "options": ["在新德里的餐厅里，咖喱牛肉拌饭十分受当地人欢迎", "在慕尼黑啤酒节上，当地人一边喝着啤酒一边吃着咸猪手", "在梵蒂冈当地家庭的餐桌上，通常会有来自当地港口的海鲜", "在北海道的冬天，当地人自古以来都食用胡椒以抵御严寒"], "a": 1, "e": "【B】A项错误，新德里是印度共和国首都。在印度，牛被印度教教徒视为“圣兽”，印度教教徒认为，牛既是繁殖后代的象征，又是人类维持生存的基本保证。所以印度不可能吃咖喱牛肉拌饭；B项正确，在慕尼黑啤酒节上，当地人一边喝着啤酒一边吃着咸猪手；C项错误，梵蒂冈是一个内陆的小国家，因此不会有港口；D项错误，胡椒原产地不在日本，没有自古以来的说法。故正确答案为B。", "tag": "地理国情"},
{"id": "geo-72", "q": "下列国家和首都对应正确的是：", "options": ["新西兰——惠灵顿", "意大利——米兰", "加拿大——蒙特利尔", "澳大利亚——悉尼"], "a": 0, "e": "【A】A项正确，惠灵顿，新西兰首都、港口和主要商业中心，全国政治中心，新西兰全国第二大城市，是大洋洲国家中人口最多的首都，当选；B项错误，罗马为意大利首都，是意大利最大的城市，也是其国家政治、经济、文化和交通中心，世界著名的历史文化名城，古罗马帝国的发祥地，因建城历史悠久而被昵称为“永恒之城”，排除；C项错误，渥太华，加拿大首都，地处安大略省东南部与魁北克省交界处，横跨渥太华河，面积4715平方公里，春季市内一片葱绿，到处可见大块草地上开放着色彩艳丽的郁金香花，因此渥太华又称“郁金香城”，排除；D项错误，堪培拉是澳大利亚的首都，在澳大利亚所有城市里排名第八，排除。故正确答案为A。", "tag": "地理国情"},
{"id": "geo-73", "q": "四川青城山、江西龙虎山、安徽齐云山与湖北武当山合称道教四大名山。四大名山中属于中国丹霞地貌且被列入《世界遗产名录》的是：", "options": ["青城山", "龙虎山", "齐云山", "武当山"], "a": 1, "e": "【B】龙虎山位于江西省鹰潭市西南20公里处贵溪市境内，是道教正一派的祖庭。东汉中叶，正一道创始人张道陵（本名张陵）曾在此炼丹，传说“丹成而龙虎现”，山因得名。据道教典籍记载，张陵第四代孙张盛在三国或西晋时已赴龙虎山定居，此后张天师后裔世居龙虎山，至今承袭63代，历经1900多年。北京时间2010年8月2日，龙虎山与龟峰被一并列入《世界自然遗产名录》。B项正确。故正确答案为B。", "tag": "地理国情"},
{"id": "geo-74", "q": "作为世界上人口最多的国家，我国必须立足自身解决粮食安全问题，要牢牢把饭碗端在自己手里。要保障我国粮食安全，下列哪项行为最有效：", "options": ["提高农民种粮收益", "全面推行“光盘行动”", "改造中低产田", "培训农民科学种田"], "a": 3, "e": "【D】邓小平在1982年10月14日发表的《前十年为后十年做好准备》一文中，指出“我们整个经济发展的战略，能源、交通是重点，农业也是重点。农业的发展一靠政策，二靠科学。科学技术的发展和作用是无穷无尽的。”中国面临的粮食安全问题要通过农业的科学技术现代化来解决，A、B、C三项措施并不能从根本上解决问题。故正确答案为D。", "tag": "地理国情"},
{"id": "geo-75", "q": "下列有关我国南、北方人民生活方面的比较，错误的是：", "options": ["南方居民多以大米为主食，北方居民多以面食为主", "南方房屋的层高比北方矮，屋顶坡度也比北方小", "北方过去农村住房多用土坯垒墙，南方旧式民居多用砖瓦、竹木", "“南船北马”是我国传统交通工具的显著特色"], "a": 1, "e": "【B】A项正确，受自然地理条件的限制，由于气候、光照、降水、土壤等原因，北方不适宜种水稻，适宜种植小麦；而南方雨热同期、光照充足，利于水稻的生长，所以，北方多种小麦，食面食；南方则种植水稻，食大米，排除；B项错误，因为南方多雨水，而北方多风沙，南方大多屋顶较陡是为了方便雨水流下而不积存在屋顶，而北方大多屋顶较平是为了能让风顺利地吹过而更好地保护房子，当选；C项正确，北方过去农村住房多就地取土，用土坯垒墙，南方旧式民居的建筑材料多用砖瓦、竹木，排除；D项正确，“南船北马”也是我国传统交通地理的体现，排除。本题为选非题，故正确答案为B。", "tag": "地理国情"},
{"id": "geo-76", "q": "在数千年历史发展过程中，陕西人创造了独具特色的“陕西精神”。下列不属于“陕西精神”的是：", "options": ["爱国守信", "弃农兴商", "宽厚包容", "勤劳质朴"], "a": 1, "e": "【B】陕西近日出台了弘扬践行”陕西精神“工作方案，要求全省上下宣传好、弘扬好、践行好”爱国守信、勤劳质朴、宽厚包容、尚德重礼、务实进取“的陕西精神，切实发挥其在陕西全面建设西部强省进程中的导向、支撑、凝聚和激励作用。本题为选非题，故正确答案为B。", "tag": "地理国情"},
{"id": "geo-77", "q": "关于矿产资源及其主要分布国，下列对应错误的是：", "options": ["硝石：加拿大", "磷矿：摩洛哥", "铜矿：智利、秘鲁", "金矿：南非"], "a": 0, "e": "【A】A项错误，智利硝石的产量和出口量都居世界第一位，不是加拿大；B项正确，美国佛罗里达磷矿和摩洛哥磷矿是世界著名的磷矿生产基地；C项正确，秘鲁、智利的铜矿资源绝大多数集中分布在中部和北部地区，这里有一条斑岩铜矿化带；D项正确，南非以丰富的矿物资源驰名世界，现已探明储量并开采的矿产有70余种，黄金、铂族金属、锰、钒、铬、硅铝酸盐的储量居世界第一位，其中黄金储量占全球的60%，铂族金属储量占全球的90%。本题为选非题，故正确答案为A。", "tag": "地理国情"},
{"id": "geo-78", "q": "关于我国在过去五年来取得的成绩，说法不正确的是：", "options": ["国内生产总值跃升到世界第二位。", "载人航空、探月工程、载人深潜、北斗卫星导航系统等实现重大突破，第一艘航母“辽宁舰”入列。", "非化石能源快速发展，水电装机容量位居世界第一。", "进出口总额从世界第三位提升到第二位，其中进口额跃居世界第一位。"], "a": 3, "e": "【D】A、B项正确，这两项同样出自温家宝总理所作的政府工作报告。报告中指出，过去五年，我国国内生产总值从", "tag": "地理国情"},
{"id": "geo-79", "q": "下列建筑中，位于北京南北向中轴线上的是：", "options": ["天坛祈年殿", "中华世纪坛", "人民英雄纪念碑", "东便门城楼"], "a": 2, "e": "【C】本题考查城市地理知识。北京市中轴线为正阳门、景山、天安门、紫禁城、全城报时中心钟、鼓楼等。新中国成立以后，又陆续扩建了天安门广场、人民英雄纪念碑、毛主席纪念堂。A项错误，天坛祈年殿位于北京中轴线东侧；B项错误，中华世纪坛位于天安门正西；D项错误，东便门位于明清北京城内外城交界，位于中轴线以东。故正确答案为C。", "tag": "地理国情"},
{"id": "geo-80", "q": "下列国家与别称对应错误的是：", "options": ["加拿大――枫叶之邦", "荷兰――风车王国", "印度――万塔之国", "奥地利――音乐王国"], "a": 2, "e": "【C】C项错误，正确的对应是印度——孔雀之国；缅甸——万塔之国。本题为选非题，故正确答案为C。", "tag": "地理国情"},
{"id": "geo-82", "q": "关于我国的地理环境，下列说法不正确的是：", "options": ["领土总面积居世界第三位", "领土最东端位于黑龙江和乌苏里江主航道中心线汇合处", "南北跨越纬度近50 度，大部分在温带，小部分在热带、寒带", "我国与14 个国家接壤"], "a": 2, "e": "【C】A项正确，中国面积仅次于俄罗斯、加拿大，排世界第三；B项正确，中国最东端在黑龙江与乌苏里江主航道中上的曾母暗沙（约4°N），因此C项前半句“南北跨越纬度近50度”正确，但是我国并没有在寒带的地区，因此C项的后半句“大部分在温带，小部分在热带、寒带”表述错误；D项正确，中国与14个国家接壤：东为朝鲜，东北为俄罗斯，北为蒙古，西北为哈萨克斯坦，西为吉尔吉斯斯坦、塔吉克斯坦、阿富汗，西南为巴基斯坦、印度、尼泊尔、不丹，南为缅甸、老挝、越南。本题为选非题，故正确答案为C。", "tag": "地理国情"},
{"id": "geo-83", "q": "下列说法中，不属于习近平同志关于“中国梦”明确表述的是：", "options": ["国家富强", "民族振兴", "美丽中国", "人民幸福"], "a": 2, "e": "【C】“中国梦”的本质内涵是实现国家富强、民族振兴、人民幸福、社会和谐。本题为选非题，故正确答案为C。", "tag": "地理国情"},
{"id": "geo-84", "q": "党的十八大首次把（）与经济建设、政治建设、文化建设、社会建设并成为中国特色社会主义事业“五位一体”的总布局。", "options": ["党的建设", "制度建设", "法制建设", "生态文明建设"], "a": 3, "e": "【D】党的十八大提出，建设中国特色社会主义事业总体布局由经济建设、政治建设、文化建设、社会建设“四位一体”拓展为包括生态文明建设的“五位一体”，这是总揽国内外大局、贯彻落实科学发展观的一个新部署。故正确答案为D。", "tag": "地理国情"},
{"id": "geo-85", "q": "作为拉动陕西经济的火车头，陕西省的“一线两带”建设受到全国的广泛关注，下面关于“一线两带”的说法中，不正确的是：", "options": ["一线指陇海陕西段和宝潼高速", "两带指关中技术产业开发带和关中星火产业带", "一线两带以线串点，以点带面，形成高新、先进的产业体系", "它包括创新层、核心层、辐射层和制度层"], "a": 3, "e": "【D】A、B、C三项均正确，“一线两带”就是以西安为中心，以陇海铁路陕西段和宝潼高速公路为轴线，以国家级关中高新技术产业开发带和国家级关中星火产业带为依托，以线串点、以点带面形成的以高新技术和先进技术为特点的产业经济体系；D项不正确，“一线两带”大体由三个层次构成：创新层、核心层、辐射层。本题为选非题，故正确答案为D。", "tag": "地理国情"},
{"id": "geo-86", "q": "2013 年（），航天员（）在天宫一号中，为全国青少年进行太空授课。", "options": ["6 月19 日王亚平", "6 月19 日刘洋", "6 月20 日王亚平", "6 月20 日刘洋"], "a": 2, "e": "【C】6月20日上午10时许，神舟十号航天员在天宫一号中进行中国首次太空授课，王亚平担任主讲，成为中国首位“太空讲师”。故正确答案为C。", "tag": "地理国情"},
{"id": "geo-87", "q": "关于山东省情，下列说法不正确的是：", "options": ["截至2012 年，山东省粮食产量实现“九连增”", "聊城、菏泽两市和东平县被纳入中原经济区规划", "目前发现最早的山东人——“沂源人”，可以把山东的历史推到四五十万年以前", "山东省2013 年生产总值预期增长目标是9.5%左右"], "a": 0, "e": "【A】本题考查山东省情。A项表述错误：《2013年山东省政府工作报告》在“大力推进经济结构战略性调整，发展方式加快转变”部分指出，“实施千亿斤粮食生产能力规划和农业十大特色产业振兴规划，大力推进农业科技创新，粮食产量实现‘十连增’，达到902.3亿斤”，并非“九连增”。B项表述正确：《2013年山东省政府工作报告》在“突出‘蓝黄’引领重点带动，城乡区域发展更趋协调”部分指出，“支持菏泽科学发展和沂蒙革命老区各项政策得到较好落实。聊城、菏泽两市和东平县纳入中原经济区规划”。一块猿人头盖骨化石，后经国家有关单位命名为“沂源猿人”，把山东的历史推到四五十万年以前。D项表述正确：《2013年山东省政府工作报告》在“2013年主要工作”部分指出，“今年全省经济社会发展的主要预期目标是，生产总值增长9.5%左右，地方财政收入增长12%左右，固定资产投资增长17%左右，社会消费品零售总额增长", "tag": "地理国情"},
{"id": "geo-88", "q": "关于中国共产党的会议，下列说法不正确的是：", "options": ["中共十三大开幕式第一次提出“建设有中国特色的社会主义”的崭新命题", "中共十四大确立了我国经济体制改革的目标是建立社会主义市场经济体制", "中共十五大确立了依法治国的基本方略", "中共十六大确立了全面建设小康社会的奋斗目标"], "a": 0, "e": "【A】本题考查中共党史。A项表述错误：中共十二大邓小平提出，走自己的道路，建设有中国特色的社会主义，当选。B项表述正确：中共十四大明确提出了我国经济体制改革的目标是建立社会主义市场经济体制，排除。立了依法治国的基本方略，排除。D项表述正确：中共十六大提出全面建设小康社会，加快推进社会主义现代化，为开创中国特色社会主义事业新局面而奋斗，排除。本题为选非题，故正确答案为A。", "tag": "地理国情"},
{"id": "geo-89", "q": "中国是世界上稀土资源最丰富的国家，素有“稀土王国”之称。下列关于稀土的表述，错误的是：", "options": ["稀土一般是以氧化物状态分离出来的，稀土的得名是因为很稀少", "美国是稀土的主要使用国，目前中国出口的稀土数量居全球之首", "我国是稀土资源储藏大国，也是稀土产品生产、应用和出口大国", "我国的稀土储量占世界稀土储量的百分比近年来因开发已经下降"], "a": 1, "e": "【B】B项错误，中国稀土的实际储量占全球稀土总储量的30%，但是全球95%的稀土产品由中国长期以低廉的价格供应。日本本国没有稀土矿，却是世界稀土主要消费国。本题为选非题，故正确答案为B。", "tag": "地理国情"},
{"id": "geo-90", "q": "与我国接壤的金砖国家有：", "options": ["1 个", "2 个", "3 个", "4 个"], "a": 1, "e": "【B】金砖国家一共有五个，除中国外，还有俄罗斯、印度、巴西、南非四个国家，其中与中国接壤的国家为俄罗斯和印度。故正确答案为B。", "tag": "地理国情"},
{"id": "geo-91", "q": "十八大报告提出“两个翻番”，到2020 年实现国内生产总值（GDP）和城乡居民人均收入比2010 年翻一番。下列关于“两个翻番”，表述错误的是：", "options": ["党的十八大首次对城乡居民收入增长提出了量化目标", "到2020 年我国城乡居民每人收入预计都能够实现倍增", "城乡居民人均收入翻番是GDP 翻番的出发点和落脚点", "到2020 年我国GDP 预计将超过2000 年GDP 的4 倍"], "a": 1, "e": "【B】B项表述错误，党的十八大报告首次提出，到2020年“实现国内生产总值和城乡居民人均收入比2010年翻一番”的目标，B项偷换概念，“城乡居民人均收入”并不等同于“城乡居民每人收入”。本题为选非题，故正确答案为B。", "tag": "地理国情"},
{"id": "geo-92", "q": "经过改革开放30 多年来的努力，中国人民享受了前所未有的开放和自由，中国的人权事业取得了举世瞩目的成就。中国政府高度重视人权的根本原因是：", "options": ["中国全面落实依法治国的方略", "国家最高权力机关是人民代表大会", "我国人民民主具有真实性", "我国是人民当家做主的社会主义国家"], "a": 3, "e": "【D】本题要求回答根本原因，实际上就是要找出中国政府高度重视人权的本质的必然性因素。我国的政权组织形式是人民代表大会制度，国家的一切权力属于人民，人民当家做主是社会主义民主政治的本质和核心，这就决定了我国政府必须高度重视人权，让人民享受应有的开放和自由。故正确答案为D。", "tag": "地理国情"},
{"id": "geo-93", "q": "党的十八大报告指出，是中国特色社会主义的内在要求，是中国特色社会主义的根本原则，是中国特色社会主义的本质属性。", "options": ["公平正义共同富裕社会和谐", "共同富裕公平正义社会和谐", "社会和谐共同富裕公平正义", "社会和谐公平正义共同富裕"], "a": 0, "e": "【A】党的十八大报告指出，公平正义是中国特色社会主义的内在要求，共同富裕是中国特色社会主义的根本原则，社会和谐是中国特色社会主义的本质属性。故正确答案为A。", "tag": "地理国情"},
{"id": "geo-94", "q": "2012 年北京市第十一次党代会提出，北京必须坚持首都城市功能定位，认真履行“四个服务”职责。下列选项中，不属于上述“四个服务”内容的是：", "options": ["为国家的国际交往服务", "为国家教育、科技事业的发展服务", "为经济又好又快发展服务"], "a": 2, "e": "【C】刘淇在北京市第十一次党代会上作报告时提出，北京作为13亿人口大国的首都，必须以更高标准履行好“四个服务”职责。首都各项工作必须更加有利于为中央党政军领导机关服务，为日益扩大的国际交往服务，为国家教育、科技、文化和卫生事业的发展服务，为市民的工作和生活服务。A、B、D正确，均属于“四个服务”的内容；C项错误，不属于“四个服务”的内容。本题为选非题，故正确答案为C。", "tag": "地理国情"},
{"id": "geo-95", "q": "我国加快转变经济发展方式的主攻方向是：", "options": ["加快投入，拉动内需", "保障和改善民生", "建设环境友好型社会", "经济结构战略性调整"], "a": 3, "e": "【D】中共中央政治局在研究制定国民经济和社会发展“十二五”规划建议时明确提出，要坚持把经济结构战略性调整作为加快转变经济发展方式的主攻方向。故正确答案为D。", "tag": "地理国情"},
{"id": "geo-96", "q": "针对其他国家对南海油气资源虎视眈眈的状况，我国政府多次重申立场：“主权归我”，“南海是我国核心利益的一部分”。这充分表明：", "options": ["我国是社会主义法治国家", "我国坚定地维护国家利益", "油气资源是我国的核心利益", "我国反对单纯以武力形式解决国际争端"], "a": 1, "e": "【B】针对南海领土问题，我国政府多次提出南海的“主权归我”，并提出南海是关系到中国领土完整的“核心利益”，把南海问题看作领土完整问题上事关存亡的重要问题。坚定南海是我国领土的一部分的立场，就是坚定地维护国家主权利益。故正确答案为B。", "tag": "地理国情"},
{"id": "geo-97", "q": "坚持和完善中国共产党领导的多党合作和政治协商制度，就必须坚持“长期共存、、肝胆相照、荣辱与共”的方针。", "options": ["互相监督", "互惠互利", "团结友爱", "参政议政"], "a": 0, "e": "【A】1987年，中国共产党的十三大政治报告在谈到政治体制改革时，明确指出：“要坚持‘长期共存、互相监督、肝胆相照、荣辱与共’的方针，完善共产党领导下的多党合作和政治协商制度，进一步发挥民主党派和无党派爱国人士在国家政治生活中的作用”。故正确答案为A。", "tag": "地理国情"},
{"id": "geo-98", "q": "从2013 年1 月1 日起，北京将对美国、英国、法国等45 个国家持有第三国签证和机票的外国人实行小时过境免签政策。", "options": ["24", "48", "72", "96"], "a": 2, "e": "【C】从2013年1月1日起，北京将对美国、英国、法国等45个国家持有第三国签证和机票的外国人实行72小时过境免签政策。故正确答案为C。", "tag": "地理国情"},
{"id": "geo-99", "q": "经国务院批准，从2012 年11 月1 日起，福建省、广东省及厦门市、深圳市实施营业税改征改革试点。", "options": ["印花税", "消费税", "增值税", "企业所得税"], "a": 2, "e": "【C】经国务院批准，福建省、广东省及厦门市、深圳市从11月1日起实施营业税改征增值税改革试点。故正确答案为C。", "tag": "地理国情"},
{"id": "geo-100", "q": "党的十八大报告指出，我国发展仍处于可以大有作为的。", "options": ["重要快速发展期", "重要战略机遇期", "重要改革机遇期", "重要战略转折期"], "a": 1, "e": ".【B】党的十八大报告提到，“综观国际国内大势，我国发展仍处于可以大有作为的重要战略机遇期。”故正确答案为B。", "tag": "地理国情"},
{"id": "geo-101", "q": "《国家“十二五”规划纲要》提出，要把扩大需求作为扩大内需的战略重点，逐步使我国国内市场总体规模位居世界前列。", "options": ["消费", "投资", "出口", "生产"], "a": 0, "e": ".【A】《国家“十二五”规划纲要》提出“要把扩大消费需求作为扩大内需的战略重点，进一步释放城乡居民消费潜力，逐步使我国国内市场总体规模位居世界前列”。故正确答案为A。", "tag": "地理国情"},
{"id": "geo-102", "q": "下列国家属于我国陆上邻国的是：", "options": ["阿富汗", "白俄罗斯", "伊朗", "日本"], "a": 0, "e": ".【A】A项正确，阿富汗位于帕米尔高原，与我国接壤；B项错误，白俄罗斯位于东欧，与我国不接壤；C项错误，伊朗位于伊朗高原，与我国也不接壤；D项错误，日本与我国是海上邻国，并不接壤。故正确答案为A。", "tag": "地理国情"},
{"id": "geo-103", "q": "下列关于我国国情的表述中，不正确的一项是：", "options": ["计划生育是我国的基本国策", "民兵是我国武装力量的组成部分", "我国的耕地面积不足陆地面积的5%", "根据全国第六次人口普查，我国的人口已达13.7 亿"], "a": 2, "e": ".【C】C项错误，我国耕地面积不少于18亿亩，陆地面积960万平方公里。应大于12%。本题为选非题，故正确答案为C。本题相关知识点：耕地红线，是指经常进行耕种的土地面积的最低值。它是一个具有低限含义的数字，有国家耕地红线和地方耕地红线。现行中国耕地红线是18亿亩。2009年6月23日国务院新闻办公室举行新闻发布会，国土资源部提出“保经济增长、保耕地红线”行动，坚持实行最严格的耕地保护制度，耕地保护的红线不能碰。", "tag": "地理国情"},
{"id": "geo-104", "q": "“金砖四国”（BRIC)引用了巴西、俄罗斯、印度和中国四国英文的首字母。由于该词与英语单词的砖（Brick）类似，因此被称为“金砖四国”。后来（）加入，“金砖四国”的英文单词变为“BRICS”，并改称为“金砖国家”。", "options": ["沙特阿拉伯", "苏丹", "南非", "西班牙"], "a": 2, "e": ".【C】2010年11月，二十国集团会议在首尔举行，南非在此次会议上申请加入“金砖四国”。", "tag": "地理国情"},
{"id": "geo-105", "q": "下列属于我国在2012 年取得的重大科技成果的是：", "options": ["神舟八号与天宫一号在太空成功实现首次交会对接", "“蛟龙”号成功下潜7062 米，创我国载人深潜记录", "我国首个超深水钻井平台“海洋石油981”交付使用", "发射嫦娥二号探月卫星，采集月球表面的影像数据"], "a": 1, "e": ".【B】A项错误，2011年11月3日凌晨1时36分，天宫一号目标飞行器与神舟八号飞船成功实现首次交会对接，中国在突破和掌握空间交会对接技术上迈出了重要一步。B项正确，2012年6月27日，中国载人深潜器“蛟龙”号7000米级海试最大下潜深度达7062米，再创中国载人深潜纪录。C项错误，2011年5月23日，中国首座3000米深水半潜式钻井平台“海洋石油981”交付使用。它是当今世界最先进的第六代超深水半潜式钻井装备，标志着中国油气资源的勘探开发正式向深海挺进。D项错误，2010年10月1日18时59分57秒，嫦娥一号卫星的姐妹星嫦娥二号卫星在西昌卫星发射中心发射升空，并获得了圆满成功。故正确答案为B。【本题相关知识点】2012年5月9日，“海洋石油981”在南海海域正式开钻。这是中国石油公司首次独立进行深水油气的勘探，标志着中国海洋石油工业的深水战略迈出了实质性的步伐。", "tag": "地理国情"},
{"id": "geo-106", "q": "2011 年我国改革开放和社会主义现代化建设取得新的重大成就，其中包括：", "options": ["人均GDP 超过3000 美元", "外汇储备首次超过日本居世界第一", "城镇化率超过50%", "粮食总产量首次超过10 万亿斤"], "a": 2, "e": ".【C】A项错误，2008年中国的人均GDP已经达到3266.8美元，登上了3000美元的新台阶；B项错误，2006年2月底，我国已超过日本成为全球外汇储备最多的国家；C项正确，2012年中国政府工作报告第一部分“2011年工作回顾”中提到，“城镇化率超过50%，这是中国社会结构的一个历史性变化”；D项错误，2012年中国政府工作报告第一部分“2011年工作回顾”中提到，“粮食产量57121万吨，再创历史新高”，57121万吨等于1.14242万亿斤，并未达到“10万亿斤”。故正确答案为C。", "tag": "地理国情"},
{"id": "geo-107", "q": "我国：①第一高峰②第一大湖③第一大岛④第一大经济特区从南向北排序，依次是：", "options": ["③②④①", "④③②①", "④③①②", "③④①②"], "a": 2, "e": ".【C】中国第一高峰是珠穆朗玛峰，位于中国西藏自治区。中国第一大湖是青海湖，位于中国青海省。中国第一大岛是台湾岛。第一大经济特区是海南岛。故正确答案为C。", "tag": "地理国情"},
{"id": "geo-108", "q": "2012 年的山东省政府工作报告中提到“制定现代海洋和高效生态示范园区建设标准和管理办法”，重点打造三个海洋经济新区，加快建设三个中外合作园区，着力推动海洋产业联动发展示范基地和黄河三角洲国家现代农业科技示范区发展。“三个海洋经济新区”指的是：", "options": ["青岛海岸、烟台滨海、日照南海", "日照沿海、烟台沿海、威海沿海", "青岛西海岸、潍坊滨海、威海南海", "青岛西海岸、日照滨海、威海南海"], "a": 2, "e": ".【C】山东省政府在工作报告中提到的重点打造三个海洋经济新区，指的是青岛西海岸、潍坊滨海、威海南海。故正确答案为C。", "tag": "地理国情"},
{"id": "geo-109", "q": "根据我国“十二五”发展规划，到2015 年，单位国内生产总值二氧化碳排放量要降低17%。实现这一目标，最主要是：", "options": ["发展低碳经济", "转变经济发展方式", "改善生态环境", "保持经济快速发展"], "a": 1, "e": ".【B】2012年1月13日，国务院印发《“十二五”控制温室气体排放工作方案》。主要目标是：大幅度降低单位国内生产总值二氧化碳排放，到2015年全国单位国内生产总值二氧化碳排放比2010年下降17%。总体要求是：坚持以科学发展为主题，以加快转变经济发展方式为主线，牢固树立绿色、低碳发展理念，统筹国际国内两个大局，把积极应对气候变化作为经济社会发展的重大战略，作为加快转变经济发展方式、调整经济结构和推进新的产业革命的重大机遇，坚持走新型工业化道路。故正确答案为B。", "tag": "地理国情"},
{"id": "geo-110", "q": "2011 年，国家确定的新扶贫标准是农民人均纯收入：", "options": ["2000 元", "2300 元", "2200 元", "2400 元"], "a": 1, "e": ".【B】中央扶贫开发工作会议上，中央决定将农民人均纯收入2300元（2010年不变价）作为新的国家扶贫标准，这个标准比2009年1196元的标准提高了92%，更多低收入人口将享受到国家扶贫优惠政策。故正确答案为B。", "tag": "地理国情"},
{"id": "geo-111", "q": "2012 年中央“一号文件”是《中共中央、国务院关于加快推进农业科技创新持续增强农产品供给保障能力的若干意见》。这表明新世纪以来中央“一号文件”关注“三农问题”已连续至：", "options": ["第十一年", "第十年", "第九年", "第八年"], "a": 2, "e": ".【C】2012年中央“一号文件”继续锁定农业，以《中共中央国务院关于加快推进农业科技创新持续增加农产品供给保障能力的若干意见》为题聚焦“三农”问题，这是继2004年连续第9个以农业为主题的中央“一号文件”。故正确答案为C。", "tag": "地理国情"},
{"id": "geo-112", "q": "温家宝总理在2012 年《政府工作报告》中提出今年我国GDP 增长目标是：", "options": ["9%", "8.5%", "8%", "7.5%"], "a": 3, "e": ".【D】温家宝总理在2012年《政府工作报告》中提出今年我国GDP增长目标是7.5%。故正确答案为D。", "tag": "地理国情"},
{"id": "geo-113", "q": "下列说法正确的是：", "options": ["我国有6 个省级行政区与邻国接壤", "庐山在黄山以北，嵩山以南", "在我国，丹顶鹤的主要栖息地是东北", "新疆和青海的部分地区是属于印度洋流域"], "a": 2, "e": ".【C】A项错误，我国与外国陆域接壤的省级行政区有9个：广西、云南、西藏、甘肃、新疆、内蒙古、黑龙江、吉林、辽宁；B项错误，庐山在江西省，在嵩山、黄山之南；D项错误，新疆和青海没有河流流入印度洋，青海的部分地区属于太平洋流域，新疆的部分地区属于北冰洋流域，大部分是内流区。故正确答案为C。", "tag": "地理国情"},
{"id": "geo-114", "q": "以下货币中最有可能为假币的是（）。", "options": ["印有猎豹的南非纸币", "印有袋鼠的澳大利亚硬币", "印有鸸鹋的加拿大硬币", "印有几维鸟的新西兰硬币"], "a": 2, "e": ".【C】本题考查地理国情。A项正确，猎豹是南非的代表性动物之一。现今的南非纸币共有五种面值：10、20、50、100、200兰特，分别表现了白犀牛、非洲象、非洲狮、非洲水牛、猎豹等五种动物。南非最高面值纸币200兰特的主角就是陆地上奔跑速度最快的动物猎豹，它让南非人引以为傲。B项正确，袋鼠是澳大利亚的象征，澳大利亚80年代发行的一元硬币上的图案就有五只袋鼠。C项错误，鸸鹋是澳洲的特产，是鸟纲鸸鹋科唯一物种，以擅长奔跑而著名，是世界上第二大的鸟类，仅次于鸵鸟，因此也被称作澳洲鸵鸟。加拿大的国宝级动物是河狸，或叫海狸。所以C项中最有可能是假币。D项正确，几维鸟因叫声“几维”得名，被新西兰人看作是自己民族的象征，并且定为国鸟。新西兰币背面多为在新西兰人见人爱的几维鸟。本题为选非题，故正确答案为C。", "tag": "地理国情"},
{"id": "geo-115", "q": "2019 年3 月28 日，博鳌亚洲论坛2019 年年会在博鳌开幕。下面有关博鳌所在省份的说法，错误的是（）。", "options": ["海南经济特区是我国唯一的省级经济特区", "今年是海南建省、办特区30 周年", "海南岛是中国的第二大岛", "三沙市是总面积最大的地级市"], "a": 1, "e": ".【B】本题考查国情社请，主要涉及海南的相关知识。A项正确，海南，简称“琼”，中华人民共和国省级行政区，省会海口。海南经济特区是中国最大的，也是唯一的省级经济特区。B项错误，1988年4月13日，第七届全国人大一次会议正式批准设立海南省，建立海南经济特区。海南行政区从广东省划出，独立建省，海南省和海南经济特区正式成立。所以2018年是海南建省办特区30周年。C项正确，海南岛是我国仅次于台湾岛的第二大岛，海南省是中国国土面积（含海域）第一大省。D项正确，三沙市是中国地理位置最南、总面积最大、陆地面积最小、人口最少的地级市。本题为选非题，故正确答案为B。", "tag": "地理国情"},
{"id": "geo-116", "q": "下列城市所在位置属于同一个大洲的是（）。", "options": ["首尔、吉隆坡、阿姆斯特丹", "麦加、开普敦、约翰内斯堡", "悉尼、惠灵顿、里约热内卢", "都灵、里斯本、斯德哥尔摩"], "a": 3, "e": ".【D】本题考查地理国情常识，主要考查考生对世界国家和城市的了解。A项错误，首尔是韩国的首都，位于亚洲东部、朝鲜半岛的中部。吉隆坡是马来西亚的首都，位于亚洲南部、马来西亚半岛中央偏西海岸。以上两个城市位于亚洲。阿姆斯特丹是荷兰的首都及最大城市，而荷兰是欧洲的国家。B项错误，麦加是伊斯兰教的第一圣地，位于亚洲西部沙特阿拉伯。约翰内斯堡和开普敦分别是南非的第一和第二大城市，两座城市都位于非洲。C项错误，悉尼是澳大利亚第一大城市，惠灵顿是新西兰的首都。以上两个城市都位于大洋洲。而里约热内卢是巴西第二大城市，巴西位于南美洲。D项正确，都灵是意大利的城市。里斯本是葡萄牙的首都，位于该国西部。斯德哥尔摩是瑞典首都。以上三个城市都位于欧洲。故正确答案为D。", "tag": "地理国情"},
{"id": "geo-117", "q": "“乡愁是一湾浅浅的海峡，我在这头，大陆在那头”是余光中漂泊异乡写的诗句，句中的“海峡”位于（）。", "options": ["南海", "渤海", "东海", "黄海"], "a": 2, "e": ".【C】本题考查地理国情。A项错误，南海，中国汉代、南北朝时称为涨海、沸海，清代逐渐改称南海，南海北部沿岸海域是传统经济鱼类的重要产卵场和索饵场。B项错误，渤海，是西太平洋的一部分，也是中国的内海，渤海沿岸有辽东湾、渤海湾、莱州湾、辽河、海河、黄河等河流从陆上带来大量有机物质，使这里成为盛产对虾、蟹和黄花鱼的天然渔场。C项正确，余光中的一生在奔波和迁徙中度过，多次与亲人聚散离合，饱尝了离愁之苦。1971年，20多年没有回过大陆的余光中思乡情切，在台北厦门街的旧居内写下《乡愁》这首诗。诗中提到的海峡是指“台湾海峡”。台湾海峡属东海海区，南通南海，被称为“海上走廊”。D项错误，黄海，位于中国大陆与朝鲜半岛之间，黄海的名称来源于它的大片水域水色呈黄色，由于历史上黄河有七八百年的时间注入黄海，使得河水中携带的大量泥沙将黄海近岸的海水染成了黄色，遂被称为黄海。故正确答案为C。", "tag": "地理国情"},
{"id": "geo-118", "q": "下列诗句所描写的我国名山大川，按照从北到南的顺序，排列正确的是（）。①日照香炉生紫烟，遥看瀑布挂前川②云横秦岭家何在，雪拥蓝关马不前③太行之路能摧车，若比人心是坦途④大别山前古柏寺，神禹当年手自栽", "options": ["③②④①", "③②①④", "②③④①", "②③①④"], "a": 0, "e": ".【A】本题考查地理国情。①“日照香炉生紫烟，遥看瀑布挂前川”出自《望庐山瀑布》。庐山位于江西省九江市庐山市境内，介于之间。②秦岭位于陕西南部，其北面为关中平原，南面为汉水谷地，介于之间。③太行山脉位于山西省与华北平原之间，是中国地形第二阶梯的东缘，也是黄土高原的东部界线，介于之间。④大别山坐落于中国安徽省、湖北省、河南省交界处，是长江与淮河的分水岭，介于之间。因此，按照从北到南的顺序，排列正确的是③②④①。故正确答案为A。", "tag": "地理国情"},
{"id": "geo-119", "q": "下列关于陕西各市的表述，正确的是（）。", "options": ["延安市位于陕西省最北部，地处陕甘宁蒙晋五省（区）接壤地带", "宝鸡市古称陈仓，有“青铜器之乡”的美誉", "西安市位于祖国版图的中心，有“中国金字塔之都”的称号", "渭南黄金年产量全国第一，有“华夏金城”的美誉"], "a": 1, "e": ".【B】本题考查地理国情。A项错误，榆林市位于陕西省最北部，地处陕甘宁蒙晋五省（区）接壤地带。B项正确，宝鸡市古称陈仓，是华夏始祖炎帝的故里、周秦王朝的发祥地，有“青铜器之乡”、“佛骨圣地”的美誉。自汉代以来，青铜器在宝鸡不断出土，数量之巨，精品之多，铭刻内容之重要，均居我国之首，因此，宝鸡被誉为“青铜器之乡”。C项错误，咸阳市位于祖国版图的中心，是中华人民共和国大地原点所在地，自古就是西部战略重镇。咸阳市身处华夏历史文化长河的发端，是秦汉文化的重要发祥地，汉高祖长陵、汉景帝阳陵、汉武帝茂陵、唐太宗昭陵、唐高宗和武则天合葬的乾陵等帝王陵寝在咸阳连绵百里，举世无双，被誉为“中国金字塔之都”。D项错误，渭南市位于关中平原东部，这里矿产资源丰富。其中煤、钼、金储量优势明显，是我国十大煤炭产地之一，黄金年产量全国第三，被誉为“渭北黑腰带”“中国钼都”和“华夏金城”。故正确答案为B。", "tag": "地理国情"},
{"id": "geo-120", "q": "“泾渭分明”是我国历史悠久的一大自然景观，早在《诗经》中，就有“泾以渭浊，湜湜其沚”的记载。“泾渭分明”景观发生于（）。", "options": ["泾阳县", "高陵区", "兴平市", "武功县"], "a": 1, "e": ".【B】本题考查地理国情。泾河、渭河自西向东，在高陵区泾渭堡村东北交会，再向东流入黄河。其中渭河是黄河最大的支流。高陵区隶属陕西省西安市，位于陕西省关中平原腹地，西安市北部，因境内有奉正塬，塬体高隆，称塬为陵，故名高陵。故正确答案为B。", "tag": "地理国情"},
{"id": "geo-122", "q": "西安号称十三朝古都，下列朝代不在西安建都的有（）。", "options": ["西晋", "前秦", "东汉", "北齐"], "a": 3, "e": ".【D】本题考查地理国情。西安有3100多年的建城史和1100多年的国都史，先后有西周、秦、西汉、东汉、新、西晋（愍帝）、前赵、前秦、后秦、西魏、北周、隋、唐13个王朝在此建都。A项正确，西晋本定都洛阳，永嘉之乱后晋愍帝司马邺于长安即帝位，改元建兴，定都长安。B项正确，前秦是东晋十六国时期的政权之一。公元350年氐族人苻洪占据关中，称三秦王。公元352年苻健称帝，定都长安。C项正确，东汉本定都洛阳，董卓之乱以后，汉献帝被董卓胁迫至长安，遂迁都长安。D项错误，北齐（550年—577年），是中国南北朝时期的北朝割据政权，由东魏权臣次子高洋所建，建都邺城，遗址主体位于河北省临漳县境内。本题为选非题，故正确答案为D。", "tag": "地理国情"},
{"id": "geo-123", "q": "下列我国著名工业基地与城市对应错误的是（）。", "options": ["汽车生产基地——长春、广州", "钢铁生产基地——武汉、开滦", "煤炭生产基地——平顶山、六盘水", "石油生产基地——大庆、克拉玛依"], "a": 1, "e": ".【B】本题考查地理国情。A项正确，目前，我国特大型汽车生产基地有上海、长春、武汉、北京、重庆、广州等。其中，长春是我国汽车工业的“摇篮”，我国“第一汽车厂”便位于长春，生产出第一辆解放牌汽车，广州有我国知名的汽车生产企业广汽集团（广州汽车集团股份有限公司）。B项错误，目前我国是世界上钢铁产量最多的国家，钢铁产量占到全球的一半左右，我国大型钢铁工业基地在东部沿海地区的有鞍山、唐山、邯郸和上海等，在中部地区的有太原（太钢）、武汉（武钢）和马鞍山等，在西部地区的有包头、攀枝花等。开滦位于河北，是我国北方重要的煤炭工业基地。C项正确，煤炭是我国第一大能源，占全国能源生产和消费量的70%以上，山西的大同、阳泉，河北的开滦，河南的平顶山，内蒙古的霍林河，黑龙江的鸡西、鹤岗，贵州的六盘水，安徽的淮北、淮南等都是著名的煤炭工业基地。D项正确，石油是我国第二大能源，大庆油田（黑龙江大庆市）、长庆油田（陕甘宁盆地）、胜利油田（山东）、克拉玛依油田（新疆克拉玛依市）是我国重要的石油工业基地。本题为选非题，故正确答案为B。", "tag": "地理国情"},
{"id": "geo-124", "q": "根据合理的城市规划，图中①处最适合建：", "options": ["化工厂", "钢铁厂", "造纸厂", "自来水厂"], "a": 3, "e": ".【D】①处于上风口，风从这里经过会进入市区，化工厂、钢铁厂都会大量排放废气，不适合建在此处，排除A、B两项。①同时处于河流的上游，造纸厂会带来大量的水污染，不适合建在此处，排除C项。故最适合建的是自来水厂。故正确答案为D。", "tag": "地理国情"},
{"id": "geo-125", "q": "某县地处黄土高原，水土流失严重。如果你是该县相关部门的工作人员，你认为采取以下哪些措施能有效治理水土流失？①压缩农业用地，扩大林草种植面积②调整种植结构，发展棉花产业③施用石灰，降低土壤酸性④打坝淤地，平整土地", "options": ["①②", "②③", "①④", "③④"], "a": 2, "e": ".【C】本题考查地理国情。①正确，实行退耕还林还草，扩大林草种植面积可有效防风固沙，减少水土流失。②错误，大面积种植棉花会导致自然植被被破坏、土地退化、水土流失加剧。③错误，黄土高原水土流失主要是降水集中和土质疏松等原因导致，与土壤酸碱性无关，且黄土高原土层富含碳酸钙和磷、钾、硼、锰等元素，土壤反应多偏碱性。④正确，在黄土高原塬面平整土地可以增加水分下渗，在沟谷处修建挡土坝，打坝淤地可减少水土流失。综上，①④项措施可以达到治理水土流失的目的。故正确答案为C。", "tag": "地理国情"},
{"id": "geo-126", "q": "关于地球南北极，下列说法不正确的是：", "options": ["南极是地球上唯一没有永久居民的大陆", "每年6～8 月是最适合去北极旅行的季节", "中国在南极建立了长城站、黄河站和昆仑站", "雪龙2 号是我国自主建造的首艘极地科考破冰船"], "a": 2, "e": ".【C】本题考查地理国情A项正确，南极常年温度在-80~-60，经常有风力高达12级的暴风雪，是地球上唯一没有永久居民的大陆。B项正确，每年6～8月北半球处于夏季，此时北极是极昼时间，没有黑夜，相对也是最暖和的，冰层也是最薄的。且北极光在夏至前后出现的可能性较大。因此，每年6～8月是最适合去北极旅行的季节。C项错误，我国在南极相继建成长城站、中山站、昆仑站、泰山站。黄河站属于我国在北极建立的科考站。D项正确，雪龙2号极地考察船是中国第一艘自主建造的极地科学考察破冰船。它能够在1.5米厚冰环境中连续破冰航行，交付使用后将填补我国在极地科考重大装备领域的空白。本题为选非题，故正确答案为C。", "tag": "地理国情"},
{"id": "geo-127", "q": "下列对有关气候效应的解释，正确的是", "options": ["阳伞效应是指由于天空中大块乌云的阻挡而削弱太阳短波辐射，使气温降低", "热岛效应是指由于城市下垫面特性和人类活动影响，使市区的气温比郊区高", "温室效应是指温室气体透过太阳长波辐射，大量吸收地面短波辐射，使气温升高", "海洋沙漠化效应是指海洋因受周围陆地沙漠化的影响，失去了对气温的调节功能"], "a": 1, "e": ".【B】本题考查地理国情。A项错误，阳伞效应指由于大气中固、液体粒子对太阳辐射的强烈阻挡作用，而使地表气温降低的现象。大气中的固、液体粒子来源于人为排放和自然过程如火山喷发、森林火灾等。它们能直接吸收和反射太阳辐射能，还能作为凝结核，使天空云量增加，加大反射率，这些都能使地表所获得的太阳辐射能减少。B项正确，热岛效应指城市气温较四周郊区为高，好像一个温暖的岛屿分布于农村较凉的“海洋”之中。其形成原因主要是：人类活动导致有大量人为热释放；产生污染物质增多，加强了大气保温作用；下垫面吸收的辐射热量，主要用于加热市区空气。C项错误，温室效应是指由于地球表面空气中的二氧化碳等温室气体浓度增加，而导致地表附近气温的升高的现象。其形成原因是：温室气体可以使太阳短波辐射透过，地表由于吸收短波辐射被加热，提高了温度，再以长波向外辐射，而长波又被温室气体吸收，使气温升高。D项错误，海洋沙漠化效应是指倾注到海洋中的废油，在海面形成油膜，起到抑制海水蒸发的作用，同时又减少了海面潜热的转移，使海洋失去调节气温的作用，因而海洋上的空气变得愈来愈干燥，故称之为“海洋沙漠化效应”。故正确答案为B。", "tag": "地理国情"},
{"id": "geo-128", "q": "下列可能出现次生盐碱化的地区是:", "options": ["水土流失严重地区", "地下水位很高的湿润区", "蒸发量较大的旱作漫灌区", "大量抽取地下水致地面下沉的地区"], "a": 2, "e": ".【C】本题考查地理知识。次生盐碱化指由于不合理的耕作灌溉而引起的土壤盐渍化过程，主要发生在蒸发作用强烈的干旱或半干旱地区，因受人为不合理措施的影响，使地下水抬升，在当地蒸发量大于降水量的条件下，使土壤表层盐分浓度进一步增大，引起土壤盐碱化。A项错误，水土流失严重的地区，土壤表层的盐分会随着水土流失排放出去，发生次生盐碱化的可能性低。B项错误，地下水位很高的湿润区，土壤中可溶性盐类随水向表层移动并积累下来，但湿润区降水量大，土壤中的盐分容易被雨水稀释而不易析出，土壤不易发生次生盐碱化。C项正确，蒸发量较大的旱作漫灌区，由于漫灌会使地下水位上升，地下水位上升会把地下的盐分带到地面来，并且干旱地区，蒸发作用强烈，会使盐分留在地表，出现次生盐碱化的可能性大。D项错误，大量抽取地下水致地面下沉的地区，地下水位会降低，发生次生盐碱化的可能性低。故正确答案为C。", "tag": "地理国情"},
{"id": "geo-129", "q": "梯田是在山坡上开辟的农田，样子像楼梯，每一级边缘均筑有田埂。一些历史悠久的梯田已成为受国家保护的文化遗产。修建梯田的主要目的是（）。", "options": ["保护环境", "传承文化", "保持水土", "节约人力"], "a": 2, "e": ".【C】修建梯田可以使田地的坡度减小，防止丘陵斜坡上的水土流失，有利于保持水土，发展农业。A项说的过于宽泛，B、D项与题干无关。故正确答案为C。", "tag": "地理国情"},
{"id": "geo-130", "q": "某地方政府为推进绿色发展准备采取一系列措施，下列措施中最合理的是：", "options": ["向辖区内钢铁厂提供能耗补贴", "对过度包装、浪费和过度消费采取惩罚性措施", "规定居民只能购买新能源汽车", "向公众推出环境质量实时监控信息平台"], "a": 3, "e": ".【D】题干关键词是“绿色发展”，“绿色”体现为低碳、环保、可持续和可循环等特点，更多地侧重发展过程中的人与自然相协调。A项错误：不应该向钢铁企业提供能耗补贴，而应帮助钢铁企业改进生产技术，提高资源利用效率，使用清洁能源。B项错误：对过度包装、浪费、过度消费采取惩罚性措施不具有可执行性。C项错误：行政干预非常明显，政府要以引导为主，而不是强制规定。虽然新能源汽车的使用会减少汽车尾气的排放，但是选项中的做法明显违背了法律的精神。D项正确：关键词是“环境质量”，是四个选项中与环境关系最直接、最明显的，且对环境实时监控，就可以根据环境质量的变化发现存在的问题，进而采取必要的措施。故正确答案为D。", "tag": "地理国情"},
{"id": "geo-131", "q": "我国山脉众多，给自然与人文地理环境带来深刻影响。对此，下列说法错误的是：", "options": ["秦岭山脉是我国南北方的重要地理分界线", "祁连山脉融雪是河西走廊绿洲农业的主要水源", "喜马拉雅山脉是世界上最年轻最高大的山脉", "阴山山脉是传统上重要的农业与林业的分界"], "a": 3, "e": ".【D】本题考查中国山脉的有关知识。A项说法正确：由于秦岭南北面的温度、气候、地形均呈现差异性变化，因而秦岭与淮河一线成了我国地理上最重要的分界线。它主要是我国南方地区与北方地区的分界线、一月份0℃等温线、800mm等降水线量线、暖温带与亚热带分界线、湿润区与半湿润区分界线、温带季风气候与亚热带季风气候分界线等。B项说法正确：河西走廊位于祁连山以东，是西北著名的粮仓，这里农业生产的水源主要是来自祁连山的冰雪融水。C项说法正确：喜马拉雅山在青藏高原南侧，是一条近似东西向的弧形山系，也是世界上最高大的山系，分布在我国西藏以及巴基斯坦、印度、尼泊尔和不丹等国境内。它还是世界上最年轻的山脉，形成至今不过6500万年，并且是在60万年前才变成最高的山脉，由于亚欧板块和印度板块的挤压运动，现在仍在不断升高。D项说法错误：以“东北松嫩平原西部—辽河中上游—阴山山脉—鄂尔多斯高原东缘（除河套平原）—祁连山山脉（除河西走廊）—青藏高原东缘”为分界线，此分界线以东为农区，种植水稻、小麦、玉米、大豆、高粱等作物；以西为牧区，放养牛、羊、马等牲畜。故阴山不是传统意义上的农业和林业的分界线，而是农业和牧业的分界线。本题为选非题，故正确答案为D。", "tag": "地理国情"},
{"id": "geo-132", "q": "预测表明，2020 年到2050 年，我国60 岁以上人口占比将从19.3上升到38.6，对此，下列说法错误的是：", "options": ["我国家庭人口的抚养比系数逐渐减小", "我国的老龄化社会问题将日益严峻", "推动我国经济发展的人口红利逐步消退", "养老保险的支付压力将会越来越大"], "a": 0, "e": ".【A】A项说法错误：抚养比是指在人口当中非劳动年龄人口数与劳动年龄人口数之比，当60岁以上人口增多即非劳动年龄人口增多时，抚养比系数会上升。B项说法正确：60岁以上人口比例大幅增加，说明老龄化的问题将会日益严峻。C项说法正确：人口红利是指一个国家的劳动年龄人口占总人口比重较大，抚养率比较低，为经济发展创造了有利的人口条件，整个国家的经济呈高储蓄、高投资和高增长的局面。当60岁以上人口比例增大时，劳动年龄人口占总人口比例减小，人口红利逐渐减少。D项说法正确：老年人口增多，养老保险支付会随之增加，故压力会加大。本题为选非题，故正确答案为A。", "tag": "地理国情"},
{"id": "geo-133", "q": "关于中国的邻国，下列说法正确的是：", "options": ["哈萨克斯坦是最大的内陆国", "印度最大的宗教是佛教", "阿富汗属亚热带季风气候", "越南与新中国建交最早"], "a": 0, "e": ".【A】A项正确，哈萨克斯坦是世界上最大的内陆国家；B项错误，印度最大的宗教是印度教，信徒人数约占印度人口的80%；C项错误，阿富汗虽位于亚热带，但因远离海洋且海拔高，属于大陆性气候；D项错误，与中国建交最早的邻国是前苏联，于1949年10月2日建交，越南与中国建交于1950年1月18日。故正确答案为A。", "tag": "地理国情"},
{"id": "geo-134", "q": "下列关于推进“十二五”期间资源节约和环境保护的表述，不正确的是：", "options": ["我国耕地资源有限，要加大耕地保护工作的力度", "提高森林蓄积量和覆盖率是“十二五”期间的重要任务", "提高化石能源消费的比重，以降低能耗总值和排放水平", "坚持保护优先和自然修复为主，加大生态保护和建设力度"], "a": 2, "e": ".【C】A项表述正确，“十二五”规划强调要“坚持最严格的耕地保护制度”、“从严控制各类建筑占用耕地”；B项表述正确，“十二五”规划中提到要“推进植树造林，新增森林面积1250万公顷”；C项表述错误，“十二五”规划在“推动能源生产和利用方式变革”中提到要“推进能源多元清洁发展”，可见C项“提高化石能源消费的比重”表述有误；D项表述正确，“十二五”规划第二十五章提到，要“坚持保护优先和自然修复为主，加大生态保护和建设力度，从源头上扭转生态环境恶化趋势”。本题为选非题，故正确答案为C。本题相关知识点：化石能源是一种碳氢化合物或其衍生物，它由古代生物的化石沉积而来，是一次能源。化石燃料不完全燃烧后，都会散发出有毒气体，却是人类必不可少的燃料。化石能源所包含的天然资源有煤炭、石油和天然气。化石能源是目前全球消耗的最主要能源，2006年全球消耗的能源中化石能源占比高达，我国的比例高达。但随着人类的不断开采，化石能源的枯竭是不可避免的，大部分化石能源本世纪将被开采殆尽。从另一方面看，由于化石能源在使用过程中会新增大量温室气体，同时可能产生一些有污染的烟气，威胁全球生态。因而，开发更清洁的可再生能源是今后发展的方向。", "tag": "地理国情"},
{"id": "geo-135", "q": "下列关于雾和霾说法不正确的是（）。", "options": ["雾是由大量悬浮在近地面空气中的微小水滴或冰晶组成的气溶胶系统", "霾是由空气中的灰尘、硫酸、硝酸、有机碳氢化合物等粒子组成的", "任何条件下，霾都不可能转化为雾", "雾和霾都是视程障碍物"], "a": 2, "e": ".【C】本题考查环境常识。A项正确，雾是由大量悬浮在近地面空气中的微小水滴或冰晶组成的气溶胶系统，是近地面层空气中水汽凝结(或凝华)的产物。B项正确，霾指的是由空气中的灰尘、硫酸、硝酸、有机碳氢化合物等粒子组成的能使大气混浊，视野模糊并导致能见度恶化的现象。C项错误，雾和霾在一定情况下，可以相互转化。在稳定的天气条件下，排放入大气中的污染颗粒物浓度越大，霾就会越重，此时如果水汽达到饱和，污染颗粒物就会作为凝结核形成雾滴。而雾形成之后，水汽被阳光蒸发，凝结核却仍然留在空气里，此时雾又转化成了霾。D项正确，雾和霾相同之处就是二者都是视程障碍物。本题为选非题，故正确答案为C。", "tag": "地理国情"},
{"id": "geo-136", "q": "湿地、海洋、森林并称为全球三大生态系统。其中，湿地拥有“地球之肾”的美誉，这是因为湿地。", "options": ["具有维系二氧化碳和氧气的平衡，净化空气和环境的作用", "具有降解污染物、净化水质、维持自然生态健康平衡的作用", "对调节全球的热量分布有重要意义", "是水生动物、两栖动物、鸟类和其他野生生物的重要栖息地"], "a": 1, "e": ".【B】本题考查地理国情，湿地的特点。湿地像天然的过滤器，它有助于减缓水流的速度，当含有毒物（农药、生活污水和工业排放物）和杂质的流水经过湿地时，流速减慢有利于毒物和杂质的沉淀和排除。一些湿地植物能有效地吸收水中的有毒物质，净化水质。沼泽湿地能够分解、净化环境物，起到“排毒”、“解毒”的功能，因此被人们喻为“地球之肾”。假如没有了湿地，好比一个人被割去了肾脏。故正确答案为B。", "tag": "地理国情"},
{"id": "geo-137", "q": "关于紫外线，下列说法错误的是：", "options": ["沙滩和水面对阳光的高反射率导致紫外线辐射更强", "多云的天气，人也会受到紫外线辐射伤害", "紫外线照射影响人体内维生素C 的合成", "紫外线属于不可见光"], "a": 2, "e": ".【C】A项正确，许多物体表面反射阳光，增加了紫外线总体暴露水平，使得辐射更强。例如：草、土壤和水反射约", "tag": "地理国情"},
{"id": "geo-138", "q": "下列不符合我国古典建筑特点的是：", "options": ["不论是墙还是塔都是越往上越细，顶上有锋利的、直刺苍穹的小尖顶", "以木材、砖瓦为主要建筑材料，以木构架为主要的结构方式", "特别注意与周围自然环境的协调"], "a": 0, "e": ".【A】我国的古典建筑屋顶瓦面是弯曲的，当屋顶是四面坡度时，屋顶的四角也就是翘起的。“不论是墙还是塔都是越往上越细，顶上有锋利的、直刺苍穹的小尖顶”是哥特式教堂建筑的特点。本题为选非题，故正确答案为A。", "tag": "地理国情"},
{"id": "geo-139", "q": "习近平总书记在参加2015 年全国两会吉林代表团审议时强调，东北老工业基地振兴发展，不能再唱工业“一柱擎天、结构单一”的“二人转”，要做好“加减乘除”。下列发展措施最接近“乘法”的是：", "options": ["实现创新驱动，大力发展科技创新型产业", "淘汰落后产能，关闭对环境污染大的产业", "调整投资方向，增加对资源依赖少的产业", "切实简政放权，有效服务各类中小型产业"], "a": 0, "e": ".【A】2015年3月9日，习近平总书记在参加2015年全国两会吉林代表团审议时强调，东北等老工业基地振兴发展，不能再唱工业“一柱擎天，结构单一”的“二人转”，要做好“加减乘除”。加法——投资、需求、创新；减法——淘汰落后产能；乘法——创新驱动；除法——市场化程度。可知，四个选项中，A项最接近“乘法”，B项最接近“减法”，C项最接近“加法”，D项最接近“除法”。故正确答案为A。", "tag": "地理国情"},
{"id": "geo-140", "q": "近年来，我国多座城市遭到暴雨袭击。这些灾害性天气现象与“雨岛效应”有关。雨岛效应集中出现在汛期和暴雨之时，易形成大面积积水，甚至形成城市区域性内涝。下列关于雨岛效应的成因说法错误的是：", "options": ["城市热量的超常排放使市区内上升气流加强，有利于云的形成", "城市空气中含有较多的凝结核，吸湿性凝结核增多容易成云致雨", "城市高楼大厦林立摩擦阻碍作用使云层移速减慢，延长下雨时间", "城市绿地和水体增加了空气湿度，有利于低云层在市区上空增多"], "a": 3, "e": ".【D】D项错误，城市雨岛形成的条件有：（1）在大气环流较弱，有利于在城区产生降水的大尺度天气形势下，由于城市热岛环流所产生的局地气流的辐合上升，有利于对流雨的发展；（2）城市下垫面粗糙度大，对移动滞缓的降雨系统有阻障效应，使其移速更为缓慢，延长城区降雨时间；（3）城市空气中凝结核多，其化学组成成分不同，粒径大小不一，当有较多核（如硝酸盐类）存在时，有促进暖云降水作用。上述种种因素的影响，会“诱导”暴雨最大强度的落点位于市区及其下风方向形成雨岛。城市绿地面积和水域面积对于农村来说面积较小，D项错误；A、B、C三项正确。本题为选非题，故正确答案为D。", "tag": "地理国情"},
{"id": "geo-141", "q": "2013 年5 月15 日，北极理事会部长级会议在瑞典宣布，接受中国、印度、意大利、日本、韩国和新加坡6 国成为理事会正式观察员。下列表述正确的是：", "options": ["北极圈埋藏着全世界80%尚未开采的石油资源", "北极是北半球最寒冷的地区，温度比南极更低", "北极理事会正式观察员没有投票权，但有权参加理事会各种会议和活动", "北极航道主要有两条：一条是美国沿岸的“西北航道”，一条是西伯利亚沿岸的“东北航道”"], "a": 2, "e": ".【C】A项错误，石油分布主要集中在中东地区，包揽了全球约的储量。B项错误，世界上最冷的地方在南极洲，年平均气温在以下，绝对最低气温达，也曾出现过的记录。这是由于那里的纬度高，而且是一个冰封的大陆，同时又是世界上风暴最大的地区。C项正确，北极理事会成立于1996年，是由加拿大、丹麦、芬兰、冰岛、挪威、瑞典、俄罗斯和美国8个成员国组成的政府间组织，主要协商、讨论与北极有关的事务。该组织的观察员不具有投票权，也无权在年会上发言，但在北极议题上具有合法的权利。D项错误，北极航道是由两条航道构成：加拿大沿岸的“西北航道”和西伯利亚沿岸的“东北航道”（又称“北方航道”，是由两艘德国货船开辟出的一条商路，西起西欧，穿过西伯利亚与北冰洋毗邻海域，绕过白令海峡到达中、日、韩等国港口）。故正确答案为C。", "tag": "地理国情"},
{"id": "geo-143", "q": "2013 年1 月9 日以来，全国中东部地区陷入严重的雾霾和污染中。下列关于雾霾天气的说法错误的是：", "options": ["雾霾天气不主张早晚开窗通风，应尽量减少户外活动", "应通过补充抗氧化剂，对抗因雾霾进入人体内产生的自由基", "发生霾时空气相对湿度不大，形成雾时空气相对湿度常达100%或接近100%", "发生霾时有效水平能见度小于5 千米，出现雾时有效水平能见度小于1 千米"], "a": 3, "e": ".【D】D说法错误，出现霾时空气则相对干燥，空气相对湿度通常在80%以下。其形成原因是由于大量极细微的尘粒、烟粒、盐粒等均匀地浮游在空中，使有效水平能见度小于10千米的空气混浊的现象，而并非5千米。本题为选非题。故正确答案为D。", "tag": "地理国情"},
{"id": "geo-144", "q": "关于京杭大运河，下列说法不正确的是：", "options": ["北起北京，南到杭州", "流经河南洛阳", "沟通海河、黄河、淮河、长江、钱塘江五大水系", "是世界上最长的人工运河"], "a": 1, "e": ".【B】本题考查地理常识。京杭大运河是世界上里程最长、工程最大的古代运河，是中国古代劳动人民创造的一项伟大工程，是中国文化地位的象征之一。A项表述正确：京杭大运河南起余杭（今杭州），北到涿郡（今北京），排除。B项表述错误：京杭大运河流经北京、天津两市和浙江、江苏、河北、山东四省。流经地属东部省市，而河南洛阳地处我国中部，当选。C项表述正确：京杭大运河贯通海河、黄河、淮河、长江、钱塘江五大水系，排除。D项表述正确：京杭大运河是世界上里程最长、工程最大的古代运河，也是最古老的运河之一，是中国古代劳动人民创造的一项伟大工程，是中国文化地位的象征之一，排除。本题为选非题，故正确答案为B。", "tag": "地理国情"},
{"id": "geo-145", "q": "地震是地球上的主要自然灾害之一。下列关于地震的说法，错误的是：", "options": ["地震活动在时间分布上具有一定的周期性", "环太平洋地震带是地球上地震最活跃的地区", "里氏地震规模每增强一级，释放的能量约增加10 倍", "有记录以来最大的一次大地震是1960 年的智利大地震，其震级为9.5 级"], "a": 2, "e": ".【C】C项表述错误，里氏地震规模每增强一级，释放的能量约增加30倍，并非10倍。本题为选非题，故正确答案为C。", "tag": "地理国情"},
{"id": "geo-146", "q": "大气中二氧化碳含量的逐年上升导致什么现象：", "options": ["雨岛效应", "热岛效应", "温室效应", "臭氧层空洞"], "a": 2, "e": ".【C】温室效应是大气保温效应的俗称，指大气中温室气体吸收了行星表面发出的长波辐射后向各个方向辐射能量，进而导致行星表面平均温度升高的过程。二氧化碳能强烈吸收地面放出的长波辐射能，被称为温室气体。因此，大气中二氧化碳含量的逐年上升会导致温室效应。故正确答案为C。本题相关知识点：雨岛效应和热岛效应都是跟城市有关的地理现象。热岛效应指城市气温高于郊区的现象，其形成原因在于城市人口集中且不断增加，工业发达，工业生产及交通工具消耗大量的燃料，居民生活用能等释放出大量的人为热，同时也受城市建筑结构及下垫面特性的综合影响。雨岛效应指的是由于城市热岛所产生的局部地区气流的上升有利于对流性降水的产生、发展，城区空气中凝结核多时有促进暖云降水作用，同时城市的下垫面粗糙度大，使其降水雨系移动速度减慢，延长地区降水时间的现象。臭氧层空洞是大气平流层中臭氧浓度大量减少的空域，臭氧层空洞跟大量用作制冷剂、喷雾剂、发泡剂等化工制剂的氟氯烃有关，跟二氧化碳没有过多的直接关系。", "tag": "地理国情"},
{"id": "geo-147", "q": "下列关于地理常识的表述，不正确的是：", "options": ["苏伊士运河沟通了地中海与红海", "格陵兰岛是世界上最大的岛屿，位于北美洲", "地球仪上纬线圈的纬度越小，长度越长", "西藏是我国陆地邻国最多的省（自治区）"], "a": 3, "e": ".【D】我国面积最大、国境线最长、交界邻国最多的省区是新疆而非西藏，D项表述错误。本题为选非题，故正确答案为D。", "tag": "地理国情"},
{"id": "geo-148", "q": "下列关于气候常识的表述，不正确的是：", "options": ["大量砍伐森林会导致全球变暖", "地球大气对流层的气温呈上冷下热的状态", "台风、沙尘暴和泥石流均为我国主要气象灾害", "梅雨发生季节正是我国梅子的黄熟季节"], "a": 2, "e": ".【C】我国主要的气象灾害为干旱、洪涝、台风、暴雨、冰雹等，泥石流不属于我国主要的气象灾害，C项表述有误。本题为选非题，故正确答案为C。", "tag": "地理国情"},
{"id": "geo-149", "q": "赤潮主要由（）引起的。", "options": ["珊瑚虫", "低气压", "浮游生物", "火山喷发"], "a": 2, "e": ".【C】赤潮是在特定的环境条件下，海水中某些浮游植物、原生动物或细菌爆发性增殖或高度聚集而引起水体变色的一种有害生态现象。赤潮是一个历史沿用名，它并不一定都是红色。故正确答案为C。", "tag": "地理国情"},
{"id": "geo-150", "q": "下列关于灾害预警信号说法正确的是：", "options": ["大雾橙色预警信号发出时，高速公路可以不关闭", "出现暴雨橙色预警时，除特殊行业外，各单位均应停业", "低温预警信号与寒潮预警信号通常同时发布", "冰雹预警信号严重程度的划分主要依据冰雹颗粒的大小"], "a": 0, "e": ".【A】A说法正确，大雾橙色预警信号发出时交通部门尽量减少雾带来的交通事故，但高速公路不用关闭；B说法错误，当出现暴雨红色预警时，停止集会、停课、停业（除特殊行业外），而非橙色；C说法错误，低温预警信号分二级,分别以蓝色、黄色表示，以最低气温为标准来划分，寒潮预警信号分四级，分别以蓝色、黄色、橙色、红色表示，主要以气温下降度数、风力情况等为标准来划分。二者的划分标准不同，一般不同时发布；D说法错误，冰雹预警信号分二级，分别以橙色、红色表示，划分依据是时间及可能造成的雹灾程度。故正确答案为A。", "tag": "地理国情"},
{"id": "geo-151", "q": "关于诗句涉及的物候特征，下列对应错误的是：", "options": ["不知近水花先发，疑是经冬雪未销——水对温度的调节作用", "羌笛何须怨杨柳，春风不度玉门关——冷锋过境产生的天气变化", "春风疑不到天涯，二月山城未见花——海拔对植物生长的影响", "南枝向暖北枝寒，一种春风有两般——光照对植物的影响"], "a": 1, "e": ".【B】本题考查地理国情。A项正确，“不知近水花先发，疑是经冬雪未销”出自张谓的《早梅》，意思是：“人们不知道寒梅靠近溪水而提早开放，以为那是经过冬天而尚未消融的白雪。”这是因为水的比热容大，其升降温都较慢，所以近水的地方夏季温度较低、冬季温度较高，近水的地方温度高，早春的花先开放了，诗句体现了水对温度的调节作用。B项错误，“羌笛何须怨杨柳，春风不度玉门关”出自王之涣的《凉州词》，意思是：“何必用羌笛吹起那哀怨的杨柳曲去埋怨春光迟迟不来呢，原来玉门关一带春风是吹不到的啊！”诗句中的“春风”是指夏季风，在气候学上，受夏季风影响明显的地方称为季风区，反之则称为非季风区。玉门关正处于非季风区，所以出现“春风不度玉门关”。与冷锋过境无关。C项正确，“春风疑不到天涯，二月山城未见花”出自欧阳修的《戏答元珍》，意思是：“我真怀疑春风吹不到这边远的山城，已是二月，居然还见不到一朵花。”通常情况下，海拔越高，气温越低。海拔每上升100米，气温下降0.6摄氏度。而温度又是影响植物生长的重要因素，故诗句体现了海拔对植物生长的作用。D项正确，“南枝向暖北枝寒，一种春风有两般”出自观梅女仙的《题壁》，从地理角度看，是由于光照强度不同，南枝向阳，光照较强，温度较高；北枝背阳，光照较弱，温度较低。体现了光照对植物的影响。本题为选非题，故正确答案为B。", "tag": "地理国情"},
{"id": "geo-153", "q": "下列表述正确的是：", "options": ["潮汐现象主要是其他行星的引力造成的", "地转偏向力是由地球自转引起的", "地磁场的北极在地理北极附近", "一般来说，纬度越高重力加速度越小"], "a": 1, "e": ".【B】潮汐现象是指海水在天体(主要是月球和太阳)引潮力作用下所产生的周期性运动，A项说法错误。地转偏向力是由于地球自转而使地球表面运动物体受到与其运动方向相垂直的力，B项说法正确。地球本身是一个巨大的磁体，地磁的北极在地理南极，地磁的南极在地理北极，C项说法错误。纬度低的地方，地心引力的一部分要作为向心力来维持物体在地球上做匀速圆周运动。而纬度越高，线速度越小，根据向心力公式，所需要的向心力也小，那么物体受到的重力要比低纬的大。所以纬度越高，重力加速度越大，D项说法错误。故正确答案为B。", "tag": "地理国情"},
{"id": "geo-154", "q": "“春江潮水连海平，海上明月共潮生。”关于海水涨落，下列说法不正确的是", "options": ["地球对海水的引力最大，它使海水有涨有落", "海水的涨落受太阳、地球和月球引力的影响", "由于距离地球遥远，太阳对海水的引力没有月球大", "太阳、月球和地球处在一条线上时，潮汐的潮差最大"], "a": 0, "e": ".【A】本题考查地理国情。A项错误、B项正确，地球表面的海水，随时随地都受万有引力的影响，主要是地球、月球和太阳的引力，其中地球的引力最大。但地球引力只会使海水永恒地依附在地球表面上，海水的涨落是由于受到地球、月球和太阳这三股力量的综合影响，并非只有地球引力。C项正确，太阳虽然远比月球大，但是太阳与地球之间的距离是月球与地球之间距离的约400倍，所以月球对海水的引力比太阳大。D项正确，潮差是指在一个潮汐周期内，相邻高潮位与低潮位间的差值，又称潮幅。每当太阳、月球和地球三者连成一条线过后的一两天，海面所受引力为太阳、月球引力的综合，因而出现最高的高潮和最低的低潮，此时潮汐的潮差最大。而每当太阳、月球和地球三者成直角关系过后的一两天，太阳引力和月球引力相互抵消，便出现最低的高潮和最高的低潮，此时潮汐的潮差最小。本题为选非题，故正确答案为A。", "tag": "地理国情"},
{"id": "geo-155", "q": "飞行距离较远时，民航飞机一般适宜在（）飞行。", "options": ["散逸层", "对流层", "平流层", "中间层"], "a": 2, "e": ".【C】本题考查地理国情。民航飞机一般在对流层顶部（空气运动较稳定）或平流层底部飞行。选择在什么高度飞行，和航线长度有关系。飞行距离较长时在平流层飞行。A项错误，800公里高度以上的大气层称为散逸层，它是大气的最高层，这里温度很高，空气稀薄。民航飞机无法达到这样的飞行高度。B项错误，对流层为大气圈的最低层，云、雨、雪、雾、雷电等天气现象，基本上都发生在此层，其特点是有强烈的对流运动，不太适合飞机长距离飞行。C项正确，自对流层顶至50—55公里的高空为平流层。平流层内水汽和尘埃稀少，基本上无云雨天气，空气垂直运动微弱，气流平稳，利于飞机长距离高空飞行。D项错误，平流层顶到80—90公里高度的大气层为中间层。气温随高度增高而降低。高度较高且有相当强烈的垂直对流运动，不适宜飞机飞行。故正确答案为C。", "tag": "地理国情"},
{"id": "geo-156", "q": "摄影师在野外环境中最不可能拍摄到的是：", "options": ["在云南丽江拍摄成片的针叶林", "在阿拉伯半岛拍摄海豹", "在冰岛拍摄火山喷发"], "a": 2, "e": ".【C】本题考查地理国情。A项正确，针叶林主要由云杉、冷杉、落叶松和松树等一些耐寒树种组成，主要分布于寒温带及中、低纬度亚高山地区的常绿或落叶针叶林。丽江市属低纬亚高山地区，此处分布有丽江云杉等植被，组成单纯林或与其他针叶树组成混交林。因此有可能在丽江拍摄成片的针叶林。B项正确，藏羚羊栖息于海拔3700-5500米的高山草原、草甸和高寒荒漠地带，为中国一级保护动物，主要分布于中国C项错误，海豹主要生活在寒温带海洋中。南极海豹数量最多，其次是北冰洋、北大西洋、北太平洋等地。而阿拉伯半岛常年受副高及信风带控制，非常干燥，几乎整个半岛都是热带沙漠气候区并有面积较大的无流区。因此最不可能在阿拉伯半岛拍摄海豹。D项正确，冰岛型火山喷发，裂隙式喷发。因现仅能在冰岛观察到这种火山喷发，故叫冰岛型火山喷发。其特征是大量喷出易流动的玄武岩质熔岩，形成表面较平坦的熔岩台地。因此有可能在冰岛拍摄火山喷发。本题为选非题，故正确答案为C。", "tag": "地理国情"},
{"id": "geo-157", "q": "下列哪句诗涉及的地形接近下图？", "options": ["横看成岭侧成峰，远近高低各不同", "连峰去天不盈尺，枯松倒挂倚绝壁", "天姥连天向天横，势拔五岳掩赤城", "天寒日暮山谷里，肠断非关陇头水"], "a": 3, "e": ".【D】本题考查地理国情。使用等高线区分地形可以按照以下知识点去判断：等高线弯曲部分向数值低处凸出——山脊；等高线弯曲部分向数值高处凸出——山谷；等高线闭合，数值从中心向四周逐渐降低——山顶；数值从中心向四周逐渐升高——盆地或洼地。题干中等高线地形图，等高线向数值高处凸出，说明图中所示地形为山谷。A项错误，“横看成岭侧成峰，远近高低各不同”形容山峰连绵起伏，忽高忽低，有多个山顶，其等高线图上应有多个闭合圆环。B项错误，“连峰去天不盈尺，枯松倒挂倚绝壁”形容山峰座座相连，越来越高，其等高线接近山脊，即弯曲部分应向数值低处凸出。C项错误，“天姥连天向天横，势拔五岳掩赤城”形容天姥山高耸入云，远远高出周边环境，其等高线图上应有一处闭合圆环且海拔远远高出周边环境。D项正确，“天寒日暮山谷里，肠断非关陇头水”描写的是山谷地形，符合题意。故正确答案为D。", "tag": "地理国情"},
{"id": "geo-158", "q": "关于图中所标示的海峡，下列说法错误的是：", "options": ["①是世界上最繁忙的石油运输航道", "②是世界上最宽的海峡", "③的海峡中心线是国际日期变更线的一部分", "④的附近地区夏季炎热干燥，冬季温和多雨"], "a": 0, "e": ".【A】A项错误：①是位于非洲大陆与马达加斯加岛之间的莫桑比克海峡，是世界上最长的海峡。世界主要石油输出国集中于中东，如伊朗、沙特阿拉伯、阿联酋等，而石油的主要输入国则主要是工业和经济相对发达的国家，如美国、西欧、日本、中国；途经莫桑比克海峡的航道不符合两者的任一特征。世界上最繁忙的石油运输航道应该是中东地区连接波斯湾和阿曼湾的霍尔木兹海峡，该项当选；B项正确：②是位于南美洲南端与南极洲之间的德雷克海峡，是世界上最宽的海峡，排除；C项正确：③是位于亚欧大陆与美洲大陆之间的白令海峡。国际日期变更线是国际经度会议为了避免日期上的混乱规定的一条用于区分地球“昨天”与“今天”的分界线。国际日期变更线通过白令海峡的中心线。该项排除；D项正确：④是沟通地中海与大西洋的直布罗陀海峡，直布罗陀海峡和附近地区属地中海气候，夏季炎热干燥，冬季温和多雨，排除。本题为选非题，故正确答案为A。", "tag": "地理国情"},
{"id": "geo-159", "q": "关于太阳系，下列说法中正确的是：", "options": ["太阳系位于银河系的中心", "矮行星是围绕大行星运行的天体", "距太阳越远的行星公转周期越长", "八大行星的自转方向相同"], "a": 2, "e": ".【C】本题考查关于太阳系的自然常识。A项错误，太阳系位于银河系内，但并不位于银河系的中心，其距离银河系中心尚有几万光年的距离。B项错误，矮行星的体积介于行星和小行星之间，围绕恒星运转，而非大行星。大行星是指太阳系中的八大行星。C项正确，八大行星离太阳越远，公转轨道半径越大，同时公转周期越长。D项错误，八大行星的自转方向多数为自西向东，但是金星为自东向西。所以不能说八大行星的自转方向相同。故正确答案为C。", "tag": "地理国情"},
{"id": "geo-160", "q": "关于海洋环境，下列说法错误的是：", "options": ["海洋是地球上水循环的起点", "海洋水温在垂直方向上，上层和下层截然不同", "波浪、潮汐和海流等都是海水运动形式", "海洋可以分成四种地形区域：大陆架、大陆坡、大洋盆地和大洋高原"], "a": 3, "e": ".【D】D项错误：海洋根据水深、海底坡度和海底沉积物等分成三种地形区域：大陆架、大陆坡、大洋底。A项正确：海洋环境指地球上广大连续的海和洋的总水域。包括海水、溶解和悬浮于海水中的物质、海底沉积物和海洋生物。海洋是地球上水循环的起点，海水受热蒸发，水蒸汽升到空中，再被气流带到陆地上来，使陆地上有降水和径流。陆地上有了水，生物才得到发展。B项正确：海洋水温在垂直方向上，上层和下层截然不同。上部在1000～2000米的水层内，水温从表层向下层降低很快，而2000米以下则水温几乎没有变化。C项正确：在各种力的作用下，海水的质点和水团不停运动着，波浪、潮汐和海流等都是海水的运动形式。本题为选非题，故正确答案为D。", "tag": "地理国情"},
{"id": "geo-161", "q": "下列关于地理位置的描述与城市之间对应关系错误的是：", "options": ["北通汝洛，西带秦蜀，南遮湖广，东瞰吴越——襄阳", "东压江淮，西挟关陇，北通幽燕，南系荆襄——南京", "南抚百越，北望中州，据五岭之要会，扼赣闽粤湘之要冲——赣州", "居浙右之上游，控鄱阳之肘腋，制闽越之喉吭，通宣歙之声势——衢州"], "a": 1, "e": ".【B】A项正确，《读史方舆纪要》称：“襄阳上流门户，北通汝洛，西带秦蜀，南遮湖广，东瞰吴越。”B项错误，洛阳城，雄踞“天下之中”，东压江淮，西挟关陇，北通幽燕，南系荆襄，人称“八方辐辏”“九州腹地”“十省通衢”。C项正确，赣州“承南启北、呼东应西、南抚百越、北望中州”，史称“南抚百越，北望中洲，据五岭之要会，扼赣闽粤湘之要冲”。D项正确，浙江衢州，闽浙赣皖四省边际中心城市，“居浙右之上游，控鄱阳之肘腋，制闽越之喉吭，通宣歙之声势”。本题为选非题，故正确答案为B。", "tag": "地理国情"},
{"id": "geo-162", "q": "下列地貌与成因的连线，正确的是：", "options": ["黄土高原沟壑纵横--风力沉积", "云南的石林---流水侵蚀", "华北平原---地壳上升的结果", "四川盆地---海浪侵蚀"], "a": 1, "e": ".【B】B项正确：云南石林世界地质公园位于云南省昆明市石林彝族自治县境内，保存和展现了最多样化的喀斯特地貌形态。喀斯特是水对可溶性岩石进行以化学溶蚀作用为主，流水的冲蚀、潜蚀和崩塌等机械作用为辅的地质作用，以及由这些作用所产生的现象的总称。由喀斯特作用所造成地貌，被称为喀斯特地貌。A项错误：黄土高原位于中国中部偏北部，为中国四大高原之一。黄土高原是世界上水土流失最严重和生态环境最脆弱的地区之一，地势由西北向东南倾斜，经流水长期强烈侵蚀，逐渐形成千沟万壑、地形支离破碎的特殊自然景观。因此黄土高原沟壑纵横是由流水侵蚀而不是风力沉积作用而成的。C项错误：华北平原是中国三大平原之一，是中国东部大平原的重要组成部分。华北平原中生代时期曾经为隆起区，后来在漫长的时间里逐渐变为了大平原。华北平原主要由黄河、海河、淮河、滦河冲积而成，并非是地壳上升的结果。D项错误：四川盆地是中国四大盆地之一，位于亚洲大陆中南部。关于四川盆地的形成原因，一直以来人们普遍认为是晚三叠世到白垩世时期中国广泛发生的地壳运动——燕山运动使盆地周围褶皱隆起，并且其构造受基底构造的影响极大，经过多次剧烈变动，才造成现代地貌的基本特征，并非海浪侵蚀形成。故正确答案为B。", "tag": "地理国情"},
{"id": "geo-163", "q": "下列地理分界线对应正确的是：", "options": ["横断山脉——内流区和外流区", "本初子午线——东半球和西半球", "200 毫米等降水量线——农耕区和畜牧业区", "祁连山脉——河西走廊和柴达木盆地"], "a": 3, "e": ".【D】本题考查地理国情。A项错误，内流区指地表径流最终不能流入海洋的地区，即内流河流域的区域，与之相对的则是外流区。我国内外流区域的分界线大致是大兴安岭西麓向西南，经阴山—贺兰山—祁连山—巴颜喀拉山—冈底斯山一线。B项错误，本初子午线，即经线，是经过英国格林尼治天文台的一条经线。而西经和东经才是地理上东西半球的分界线。C项错误，", "tag": "地理国情"},
{"id": "geo-164", "q": "下列对气候与城市规划的描述错误的是：", "options": ["街道位于与子午线成30～60 度夹角处，有利于两侧建筑的采光", "我国城市房屋在确定房屋间距时，应以夏至日的日照时间为准", "工业布局一般在该地区盛行主导风向的下风向", "机场一般选在低云和风速较小的地方"], "a": 1, "e": ".【B】B项错误：我国多数城市的住宅间距标准是以冬至日的日照为依据。我国处在北半球，冬至日时正午太阳高度达一年中的最小值，楼房的影子为一年中最长的一天。而夏至日时，太阳就在北半球,北回归线及其以北地区的太阳高度角就是最大的,影子最短。若以夏至日为准，低楼层可能大部分时间都无法接受日照，所以不会以夏至日来规定。A项正确：街道的这种设计是为了充分利用光照资源，因为建筑物的日照条件与街道方位有关。街道的方位影响街道内建筑物的朝向,进而影响建筑物的日照条件。一般而言,朝北的房屋光照条件较差,为了保证居住区街道两侧的所有建筑物都有较好的光照条件,城镇街道宜采取南北方向与东西方向的中间方位,也就是使街道与子午线成30到60度的夹角，以使街道两侧较好地、公平地获得光照。C项正确：工业区一般会产生污染，对城市环境造成危害，因此工业区在布局时，有大气污染的工业应该在盛行风的下风向，而且位于城市的外围。工业区选址盛行风向：严重污染大气的工厂，应该在城市主导风向的下风口地带，或者在主导风向的垂直两侧选择厂址，季风区布置在当地最小风频的风向的上风地带，工业布局在垂直于季风风向的市郊。D项正确：机场选址，宜选少云雾和暴雨频率较少、风速较小、距城较远的地方。本题为选非题，故正确答案为B。", "tag": "地理国情"},
{"id": "geo-165", "q": "下列说法不正确的是：", "options": ["宇宙中的星球除了恒星外都不会发光", "太阳黑子会对地球磁场产生干扰", "太阳系中距离太阳最远的行星是冥王星", "春分时，太阳光直射在赤道附近"], "a": 2, "e": ".【C】C项错误，在2006年8月24日国际天文学联合会大会上，以绝对多数通过决议5A-行星的定义，以237票对157票通过决议6A-冥王星级天体的定义，冥王星从此被视为是太阳系的“矮行星”，不再被视为行星；A、B、D三项正确。本题为选非题，故正确答案为C。", "tag": "地理国情"},
{"id": "geo-166", "q": "以下有关世界地理表述正确的是：", "options": ["欧洲和亚洲之间以苏伊士运河为界", "澳大利亚是独自占有一个大陆的国家", "泰晤士河是瑞士的主要河流", "世界上含盐度最高的海是波罗的海"], "a": 1, "e": ".【B】A项错误，欧洲和亚洲之间以乌拉尔山、乌拉尔河、里海、高加索山脉、黑海、土耳其海峡为分界线；B项正确，澳大利亚是世界土地面积第六大的国家，是世界上唯一一个独占整个大陆的国家,也是大洋洲最大的国家；C项错误，泰晤士河是英国的“母亲河”；D项错误，世界上含盐度最高的海是红海。故正确答案为B。", "tag": "地理国情"},
{"id": "geo-167", "q": "在黄河入海口，下列哪一天白天最长：", "options": ["植树节", "劳动节", "教师节", "元旦"], "a": 1, "e": ".【B】黄河入海口，位于山东省东营市垦利县黄河口镇境内。地处渤海与莱州湾的交汇处，1855年黄河决口改道而成。位于北半球，距离夏至日越近，白天越长，夏至是二十四节气之一，在每年公历6月21日或22日。A项错误，植树节为3月12日；B项正确，劳动节为5月1日，劳动节距离夏至约为53天；C项错误，教师节为9月10日，教师节距离夏至约为80天；D项错误，元旦为1月1日。故正确答案为B。", "tag": "地理国情"},
{"id": "geo-168", "q": "下列选项中，不属于洋流形成原因的是：", "options": ["地转偏向力", "太阳辐射", "大气运动", "磁偏角"], "a": 3, "e": ".【D】洋流又叫海流，它和周期性地改变着自己的流速和流向的潮流不同，而是具有相对稳定流向的海水流动。洋流可以是一支浅而狭窄的水流，仅仅沿着海洋表面流动；也可以是一股深而广阔的洪流，携带着数百万吨海水前进。洋流的成因主要有：大气运动和行星风系、密度差异、流体的连续性形成的补偿作用、陆地的形状和地球自转产生的地转偏向力。风形成的原因有两个，即地球的转动以及地球表面受太阳加热程度的差别，所以太阳辐射会影响到风的形成，进而影响洋流的形成。其中，盛行风是形成洋流的主要动力，但是，在地转偏向力的作用下，风海流的流向并不与风向完全一致。因此洋流的形成与太阳辐射、大气运动以及地转偏向力均有关系。本题为选非题，故正确答案为D。", "tag": "地理国情"},
{"id": "geo-169", "q": "关于地球圈层，下列表述不正确的是：", "options": ["内部圈层自外而内可分为地壳、地幔和地核", "外部圈层包括大气圈、水圈和生物圈", "地幔是平均密度最大的内部圈层", "地壳中含量最高的金属元素是铝"], "a": 2, "e": ".【C】地球的内部圈层可分为地壳、地幔和地核三层。其中，地幔为中间层，厚度约2865公里，主要由致密的造岩物质构成，是地球内部体积最大、质量最大的一层。地幔又可分成上地幔和下地幔两层。上地幔上部存在一个地震波传播速度减慢的层，一般称为软流层，推测是由于放射性元素大量集中，蜕变放热，使岩石高温软化，并局部熔融造成的，很可能是岩浆的发源地。软流层以上的地幔是岩石圈的组成部分。下地幔温度、压力和密度均增大，但密度最大的圈层是地核而非地幔。本题为选非题，故正确答案为C。", "tag": "地理国情"},
{"id": "geo-170", "q": "山东省是中国东部沿海的一个重要省份，境内河湖交错，水网密布，有著名的“南四湖”。下列不属于“南四湖”的是：", "options": ["微山湖", "昭阳湖", "东平湖", "南阳湖"], "a": 2, "e": ".【C】“南四湖”位于济宁市微山县境内，是南阳湖、独山湖、昭阳湖、微山湖四个串连湖泊的总称，因在济宁以南而得名，为山东省最大的淡水湖。湖面狭长，中部较窄，南北长约125公里，东西宽5～30公里，湖面面积约1266平方公里。但由于微山湖面积比其他三湖较大，习惯上统称微山湖。本题为选非题，故正确答案为C。", "tag": "地理国情"},
{"id": "geo-171", "q": "下列关于生物的说法正确的是：", "options": ["植物是异养型生物", "木耳属于植物界", "哺乳动物是恒温动物", "病毒的细胞为原核细胞"], "a": 2, "e": ".【C】A项错误，异养生物是相对于自养生物说的，植物一般都属于自养生物（猪笼草等除外），它们可以从自然界吸收无机物合成有机物，而异养生物只能靠吸收有机物来维持生命，比如我们人类；B项错误，植物是生物界中的一大类，可分为孢子植物和种子植物，有动物所没有的叶绿素和基质，能进行光合作用。木耳属于大型真菌，因为它们的细胞内无叶绿体，不能制造有机物，只能靠现成的有机物生活，异养型，是分解者；C项正确，体温不因外界环境温度而改变始终保持相对稳定的动物，叫做恒温动物。如绝大多数鸟类和哺乳动物；D项错误，病毒无细胞结构，既不属于真核细胞，也不属于原核细胞，属于无细胞结构的生物，不能独立存活，具有寄生性。故正确答案为C。本题相关知识点：原核细胞是组成原核生物的细胞。这类细胞主要特征是没有以核膜为界的细胞核，同时也没有核膜和核仁，只有拟核，进化地位较低。", "tag": "地理国情"},
{"id": "geo-172", "q": "下列地质景观与景区对应错误的是：", "options": ["丹霞地貌——贵州赤水", "火山口湖——云南洱海", "花岗岩山地——黄山莲花峰", "喀斯特地貌——云南石林"], "a": 1, "e": ".【B】A项正确，丹霞地貌系指由产状水平或平缓的层状铁钙质混合不均匀胶结而成的红色碎屑岩(主要是砾岩和砂岩)，在差异风化、重力崩塌、流水溶蚀、风力侵蚀等因素综合作用下形成的有陡崖的城堡状、宝塔状、针状、柱状、棒状、方山状或峰林状的地形。2010年8月2日凌晨，联合国世界遗产委员会（WHC）在巴西举行的第34届世界遗产大会上一致通过湖南崀山、广东丹霞山、贵州赤水、福建泰宁、江西龙虎山、浙江衢州江郎山“捆绑”申报的“中国丹霞”列为世界自然遗产。B项错误，我国的四大火山口湖为长白山天池、湖光岩、西樵山火口湖和大屯火山口湖。云南洱海为断层陷落湖。C项正确，在花岗岩石体基础上，各种外动力形成的形态特殊的地貌类型称为花岗岩地貌。花岗岩山丘大多具有山势挺拔、沟谷深邃、岩石裸露、多球状岩块、多弧形岩壁、多崩块的特征。花岗岩山地丘陵区大多是风景名胜区。黄山莲花峰就是其中的代表之一。D项正确，喀斯特地貌是具有溶蚀力的水对可溶性岩石进行溶蚀等作用所形成的地表和地下形态的总称，又称岩溶地貌。中国喀斯特地貌分布广、面积大。主要分布在西部地区的碳酸盐岩出露地区，面积为91万130万平方千米。其中以广西、贵州和云南东部所占的面积最大，是世界上最大的喀斯特区之一。本题为选非题，故正确答案为B。", "tag": "地理国情"},
{"id": "geo-173", "q": "假如现在是北京时间12 日上午9 点，则伦敦时间和纽约时间分别是：", "options": ["12 日凌晨1 点；12 日晚上9 点", "12 日凌晨1 点；12 日晚上6 点", "12 日凌晨1 点；11 日晚上9 点", "11 日晚上11 点；11 日晚上9 点"], "a": 2, "e": ".【C】C项正确，伦敦时区为零时区，已知北京时间（东八区）时间是12日上午9点，伦敦和北京差八个时区，按照“东加西减”的时区计算原则，计算出伦敦时间为12日凌晨1点，而纽约位于西半球，在日期变更线以东，日期一定是11日。故正确答案为C。", "tag": "地理国情"},
{"id": "geo-174", "q": "金花茶是广西特有花卉，国内誉其为“植物界的熊猫”，国外称它为“梦幻中的黄色山茶花”，目前广西建立了世界上唯一的金花茶自然保护区。", "options": ["龙州", "钦州", "南宁", "防城港"], "a": 3, "e": ".【D】防城港市通过引进龙头企业广西富茶新科技股份有限公司，建设10000亩金花茶种植及加工基地，使这一具有重要药用价值的珍稀植物出现在田间地头，在开发中得到保护。素有“茶族皇后”之称的金花茶是世界珍稀植物，具有极高观赏价值及药用价值，而全世界95%以上的野生金花茶资源生长在广西防城港市。故正确答案为D。", "tag": "地理国情"},
{"id": "geo-175", "q": "亚洲和非洲之间的分界线是：", "options": ["亚马逊河", "苏伊士运河", "白令海峡", "霍尔木兹海峡"], "a": 1, "e": ".【B】苏伊士运河1869年修筑通航，是一条海平面的水道，在埃及贯通苏伊士地峡，连接地中海与红海，提供从欧洲至印度洋和西太平洋附近土地的最近的航线。它是世界使用最频繁的航线之一，也是亚洲与非洲的交界线。亚马逊河，位于南美洲北部，是世界上流量最大、流域最大、支流最多的河流，长度位居世界第二。白令海峡是亚洲和北美洲的分界线。霍尔木兹海峡是连接波斯湾和印度洋的海峡，也是唯一进入波斯湾的水道。故正确答案为B。", "tag": "地理国情"},
{"id": "geo-176", "q": "我国东西南北四个方向与邻国都有分界线，最西部的分界线是：", "options": ["西藏喜马拉雅山脉", "新疆天山山脉", "新疆祁连山脉", "新疆帕米尔高原"], "a": 3, "e": ".【D】曾母暗沙；最东端——在黑龙江与乌苏里江主航道中心线的相交处；最西端——在新疆帕米尔高原。故正确答案为D。", "tag": "地理国情"},
{"id": "geo-177", "q": "下列哪项不在中国地形的第二级阶梯上？", "options": ["秦岭", "呼伦贝尔高原", "鄂尔多斯高原", "巴颜喀拉山"], "a": 3, "e": ".【D】第一级阶梯：在我国西南部的青藏高原，平均海拔在4000米以上，主要有昆仑山、巴颜喀拉山、横断山脉；第二级阶梯：在青藏高原边缘以东和以北，是一系列宽广的高原和巨大的盆地，海拔下降到1000~2000米，主要有阿尔泰山、天山、鄂尔多斯高原、阴山、呼伦贝尔高原、秦岭山脉、大兴安岭、太行山、巫山、雪峰山；第三级阶梯：在我国东部主要有丘陵和平原分布区，大部分地区海拔在500米以下，主要有长白山、大别山、武夷山、南岭、台湾山脉。本题为选非题，故正确答案为D。", "tag": "地理国情"},
{"id": "geo-178", "q": "关于中国地理，下列说法错误的是：", "options": ["九寨沟国家地质公园以雅丹地貌闻名", "藏羚羊主要生活在可可西里国家级自然保护区", "张家界国家森林公园处于武陵山脉的腹地", "三江并流风景名胜区已被列入《世界遗产名录》"], "a": 0, "e": ".【A】A项错误，九寨沟景区属于喀斯特地貌（岩溶地貌）。喀斯特发育区地下水循环通畅，九寨沟以水景最为奇丽，素有“世界水景之王”的美誉，不仅河湖水清澈，而且景色宜人；B项正确，藏羚羊，学名藏羚，是偶蹄目、牛科、藏羚属动物。藏羚羊生活在中国青藏高原（西藏、青海和新疆），有少量分布在印度拉达克地区，被称为“可可西里的骄傲”；C项正确，1982年9月25日，经中华人民共和国国务院批准，将原来的张家界林场正式命名为“张家界国家森林公园”，是中国建立的第一个国家级的森林公园，澧水中上游，属武陵山脉腹地，为中国最重要的旅游资源；D项正确，2002年10月8日至10月20日，国际自然保护联盟的专家对云南“三江并流”地区进行了实地考察。2003年6月，该联盟向联合国世界遗产委员会推荐，建议将“三江并流”按满足世界自然遗产全部四条标准列入《世界遗产名录》。", "tag": "地理国情"},
{"id": "geo-179", "q": "下列关于火山的表述错误的是：", "options": ["喷出的物质有气态、流态和固态三种", "页岩是最常见的岩浆岩", "五大连池的形成与火山喷发有关", "可分为死火山、活火山和休眠火山"], "a": 1, "e": ".【B】A项正确，火山喷出物中，气体物质主要是水蒸气，还有氢气、二氧化碳等，液态物质主要是高温岩浆，固态物质主要是火山弹、火山砂和火山灰。B项错误，页岩是一种沉积岩，成分复杂，但都具有薄页状或薄片层状的节理，主要是由黏土沉积经压力和温度形成的岩石，但其中混杂有石英、长石的碎屑以及其他化学物质。", "tag": "地理国情"},
{"id": "geo-180", "q": "关于海水及其运动，下列说法错误的是：", "options": ["海水的冰点温度比淡水低", "北海道渔场位于寒流与暖流的交汇处", "波罗的海是世界上盐度最高的海域", "波浪、潮汐和洋流是海水运动的主要形式"], "a": 2, "e": ".【C】A项正确，淡水0℃结冰叫作冰点，海水冰点变化与海水盐度和密度有密切关系，因海水含有大量盐，所以海水的冰点温度比淡水低；B项正确，北海道渔场地处亚洲东部的日本北海道，位于千岛寒流与日本暖流的交汇处海域，是世界第一大渔场；C项错误，红海是世界上盐度最高的海域，红海受副高和信风带控制，形成热带沙漠气候，蒸发量大，降水稀少，终年高温；D项正确，海水运动的形式主要有三种：波浪、潮汐、洋流。本题为选非题，故正确答案为C。", "tag": "地理国情"},
{"id": "geo-181", "q": "关于天体及其运行，下列表述错误的是：", "options": ["天球是为了确定天体位置和运动而假想的圆球", "在火星和木星轨道之间存在一个小行星带", "黄道面是指月球绕地球运行的轨道面"], "a": 2, "e": ".【C】A项正确，天文学等领域中，天球是一个想象的旋转的球，理论上具有无限大的半径，与地球同心。天空中所有的物体都想象成是在天球上。与地球相对应，它有天赤道，天极。B项正确，在火星和木星轨道之间存在小行星带，位于火星和木星轨道之间的小行星密集区域，估计此地带存在50万颗小行星。关于形成原因，比较普遍的观点是太阳系形成初期，由于某种原因，火星与木星之间空当地带未能积聚形成一颗大行星，结果留下了大批小行星。C项错误，黄道面就是地球绕日旋转轨道所在的平面，所指的是地球，并不是指月球。D项正确，星座是指在道家占星学上，天上一或器具联系起来，称之为“星座”。本题为选非题，故正确答案为C。", "tag": "地理国情"},
{"id": "geo-182", "q": "旱作农业的农作物中，占重要地位的是：", "options": ["小麦", "玉米", "大麦", "高粱"], "a": 0, "e": ".【A】旱作农业是指无灌溉条件的半干旱和半湿润偏旱地区，主要依靠天然降水从事农业生产的一种雨养农业。我国干旱、半干旱地区的面积占全国土地面积半数以上。位于昆仑山—秦岭—淮河一线以北，大致包括北方15个省、市、自治区。而该区域是我国小麦的主产区。故正确答案为A。", "tag": "地理国情"},
{"id": "geo-183", "q": "“斗柄东指，天下皆春”的意思是北斗七星斗柄指向东方的时候，春天就来了。那么，在冬季，北斗七星的斗柄指向:", "options": ["北方", "南方", "西方", "东方"], "a": 0, "e": ".【A】《冠子环流篇》：“斗柄东指，天下皆春；斗柄南指，天下皆夏；斗柄西指，天下皆秋；斗柄北指，天下皆冬。”意思就是说：若把观测的时间固定于傍晚，则二月春分时斗柄指东，五月夏至时斗柄指南，八月秋分时斗柄指西，十一月冬至时斗柄指北。借助斗柄指向地面上的东、南、西、北四个方位，可以确定四个季节的中间日期，二至二分的所在月确定之后，其他月份也就容易确定了。故正确答案为A。", "tag": "地理国情"},
{"id": "geo-184", "q": "每年10 月下旬，总有“霜降”这个节气。我们看到过降雪，也看到过降雨，可是谁也没有看到过降霜。对此说法不正确的是：", "options": ["霜一般形成在寒冷季节里晴朗、微风或无风的夜晚", "霜不是从天空降下来的，而是在近地面层的空气里形成的", "天空有云有利于霜的形成", "霜总是在有利于物体表面辐射冷却的天空条件下形成"], "a": 2, "e": ".【C】C项错误：霜是近地面空气中的水汽达到饱和，并且地面温度低于0℃，在物体上直接凝华而成的白色冰晶。霜的形成不仅与天气条件有关，而且和地面物体的属性有关。霜是在辐射冷却的物体表面上形成的，所以物体表面越容易辐射散热并迅速冷却，在它上面就越容易形成霜。而云对地面物体夜间的辐射冷却是有妨碍的，天空有云不利于霜的形成。A、B、D项说法均正确。本题为选非题，故正确答案为C。", "tag": "地理国情"},
{"id": "geo-185", "q": "沙尘暴是指强风将地面尘沙吹起使空气很混浊，水平能见度小于1 千米的天气现象。近年来，我国沙尘暴日益严重，下列关于沙尘暴说法正确的是：", "options": ["人类可以消灭沙尘暴", "沙尘暴天气主要发生在春末夏初季节", "沙尘暴多“全是全球变暖惹的祸”", "沙尘暴天气能见度为零"], "a": 1, "e": ".【B】B项正确：沙尘暴天气主要发生在春末夏初季节，这是由于冬春季干旱区降水甚少，地表异常干燥松散，抗风蚀能力很弱，在有大风刮过时，就会将大量沙尘卷入空中，形成沙尘暴天气，正确。A项错误：沙尘暴的形成除了人为因素之外，还有气象因素，沙尘暴的形成是以东亚特殊的大气环流为背景，并与冬季风紧密联系在一起，它的发生主要与冬半年西伯利亚——蒙古高压驱动下的冷锋过境有关。所以人类是不能消灭沙尘暴的，排除。C项错误：强风是沙尘暴产生的动力，沙、尘源是沙尘暴物质基础。除此之外，前期干旱少雨，天气变暖，气温回升，都是沙尘暴形成的特殊的天气背景。所以沙尘暴并不都是全球变暖引起的，排除。D项错误：沙尘暴是指强风从地面卷起大量沙尘，使水平能见度小于1千米，具有突发性和持续时间较短特点的概率小危害大的灾害性天气现象。所以沙尘暴天气并不是能见度为零，排除。故正确答案为B。", "tag": "地理国情"},
{"id": "geo-186", "q": "“坐地日行八万里，巡天遥看一千河”（毛泽东《送瘟神》），这句诗描写的现象是：", "options": ["地球自转", "地极移动", "昼夜交替", "地球公转"], "a": 0, "e": ".【A】A项正确，地球自转是地球的一种重要运动形式，指地球绕自转轴自西向东的运动。地球赤道全长约四万公里，合约八万里，“坐地日行八万里”，说的是住在地球上的人，因为地球自转，不知不觉中，一天就走了八万里路。由此可知，题干诗句描述的是地球自转现象。B项错误，地极移动指的是地球自转轴在地球本体内的运动，题干没有体现地极移动现象。C项错误，地球出现昼夜现象，是因为地球是不发光且不透明的球体，同一瞬间阳光只能照亮半个球，被阳光照亮的半个地球是白昼，没有被阳光照亮的半个地球是黑夜；又因为地球自转，于是产生昼夜交替的现象。题干没有体现昼夜关系。D项错误，地球公转指地球按一定轨道围绕太阳转动，题干没有体现地球绕太阳转动。故正确答案为A。", "tag": "地理国情"},
{"id": "geo-187", "q": "深圳中部和西北部主要为：", "options": ["低山", "平原", "平缓台地", "丘陵"], "a": 3, "e": ".【D】D项正确，深圳中部和西北部主要为丘陵。深圳全境地势东南高，西北低。土地形态大部分为低山、平缓台地和阶地丘陵。东南部主要为低山；中部和西北部主要为丘陵，也有500米以上的低山突起，山间有较大片冲击平原；西南部主要为较大片的滨海冲击平原。故正确答案为D。", "tag": "地理国情"},
{"id": "geo-188", "q": "我国南方和北方的地理分界线是：", "options": ["乌蒙山—长江", "祁连山—黄河", "伏牛山—淮河", "秦岭—淮河"], "a": 3, "e": ".【D】我国南北分界线是秦岭淮河一线，也是我国800mm等降水量线、水田旱地分布分界线、一月份0度等温线、水稻小麦种植分界线、亚热带与暖温带的分界线、温带落叶阔叶林和亚热带常绿阔叶林的分界线、湿润与半湿润的分界线、亚热季风气候与温带季风气候的分界线。从人们生活习俗来看，秦岭淮河南北的差异非常明显。故正确答案为D。", "tag": "地理国情"},
{"id": "geo-189", "q": "关于我国的水资源与水能，下列说法错误的是：", "options": ["我国水能大部分分布在西南地区，按河流统计以雅鲁藏布江水系最多", "我国水能资源理论蕴藏量居世界首位", "我国已经被联合国列为13 个贫水国家之一", "我国是一个水资源短缺、水灾频繁的国家"], "a": 0, "e": ".【A】A项错误，我国水能资源分布不均衡，大部分在西南地区，雅鲁藏布江水能蕴藏量丰富，在我国仅次于长江。其他选项表述无误。本题为选非题，故正确答案为A。", "tag": "地理国情"},
{"id": "geo-190", "q": "树木的年轮不仅记录着树的年龄，而且指示着方向。年轮一般总是一面稀疏、一面密集。那么，在中国北方平原上的树木，年轮密集的一面指向的是：", "options": ["东向", "西向", "南向", "北向"], "a": 3, "e": ".【D】在北半球，树干朝南一面受阳光照射较多，形成层原始细胞分裂也较迅速，径向（沿半径的方向）生长加快，结果茎干南面的年轮也较稀疏。而在茎干背阴朝北的一面，年轮则明显聚集。故正确答案为D。", "tag": "地理国情"},
{"id": "geo-191", "q": "可再生能源是指自然界中可以不断利用、循环再生的能源。以下属于可再生能源的是：", "options": ["风能", "煤炭", "石油", "天然气"], "a": 0, "e": ".【A】B、C、D项均为不可再生能源，排除；只有A项风能为可再生能源，当选。故正确答案为A。", "tag": "地理国情"},
{"id": "geo-192", "q": "据统计，地震常常发生在夜间，而且还常常发生在农历初一或十五前后，这是因为：", "options": ["人们的错觉，因为人们在白天接收的刺激比较多，不容易感知小地震的发生", "农历初一、十五与夜间，地球表面受太阳、月球引力较大", "夜间气温较低，地表容易被炙热的岩浆冲破，而农历初一或十五也常常是当月中气温最低的时段", "地震统计仅统计较为剧烈的地震，而大多数地震是较为轻微的"], "a": 1, "e": ".【B】“地震常常发生在夜间”是外因———太阳和月球引力的结果，太阳和月球的引力可引起海水在一天里两次涨落，而农历初一、十五或十六前后是太阳和月球引力最大的时候，更易发生地震。故正确答案为B。", "tag": "地理国情"},
{"id": "geo-193", "q": "山脉常常成为气候分界线，下列山脉哪个是暖温带和亚热带的分界线？", "options": ["天山", "秦岭", "祁连山", "太行山"], "a": 1, "e": ".【B】秦岭淮河一线，在我国是比较重要的一条线，它不仅是我国暖温带和亚热带的分界线，而且也是年均温零度等温线，我国南北方的分界线，年降水量800毫米等降水量线。故正确答案为B。", "tag": "地理国情"},
{"id": "geo-194", "q": "关于世界地理，下列说法不正确的是：", "options": ["里海是世界上最大的内陆湖", "刚果盆地是世界上最大的盆地", "巴西高原是世界上最高的高原", "安第斯山脉是世界上最长的山脉"], "a": 2, "e": ".【C】本题考查世界地理相关知识。A项表述正确：里海面积约为386400平方千米，是世界上最大的内陆湖泊，排除。B项表述正确：刚果盆地面积约为337万平方千米，是世界上面积最大的盆地，排除。C项表述错误：世界上最高的高原是青藏高原，并非巴西高原，巴西高原是世界上面积最大的高原，当选。D项表述正确：安第斯山脉从北到南全长8900余千米，是世界上最长的山脉，排除。本题为选非题，故正确答案为C。", "tag": "地理国情"},
{"id": "geo-195", "q": "以下城市夏季的白昼时间由长到短排列的是：", "options": ["长沙—郑州—天津—沈阳", "杭州—西安—武汉—合肥", "海口—兰州—上海—太原", "长春—北京—南京—广州"], "a": 3, "e": ".【D】夏季，阳光直射在北回归线附近，北半球每天太阳照到的时间长，照不到太阳光的时间短，所以夏季日长夜短。而且在夏季，越是往北，白天越长。根据四个选项中所述城市的地理位置，从北到南排列的是D项。故正确答案为D。", "tag": "地理国情"},
{"id": "geo-196", "q": "当一种动物对所生存的环境、所食用的食物有着特定的要求时，这种动物往往被认为是脆弱的、容易消亡的。以下动物属于这一类的是：", "options": ["海鸥", "野猪", "华南虎", "眼镜蛇"], "a": 2, "e": ".【C】华南虎，是中国的十大濒危动物之一，目前在野外几乎灭绝，仅在各地动物园、繁殖基地里人工饲养着100余只。一般来说，一只老虎的生存至少需要70平方公里的森林，还必须生存有200只梅花鹿、300只羚羊和150只野猪。题干也强调“所生存的环境”，华南虎由名称可知，主要分布于华南，对于环境依赖度高，符合题意。而海鸥、野猪和眼镜蛇的分布范围更广，相对于其他三种动物而言，华南虎属于“脆弱的、容易消亡的”动物。故正确答案为C。", "tag": "地理国情"},
{"id": "geo-197", "q": "下列四个节日中，杭州市白昼最长的是：", "options": ["元旦", "劳动节", "儿童节", "国庆节"], "a": 2, "e": ".【C】夏至是二十四节气之一，在每年公历6月21日或22日。夏至这天，太阳直射地面的位置到达一年的最北端，几乎直射北回归线，此时，北半球的白昼达最长，且越往北越长。元旦是1月1日，劳动节是5月1日，儿童节是6月1日，国庆节是10月1日，因此，儿童节时间离夏至最近，是四个选项中白昼最长的一天。故正确答案为C。", "tag": "地理国情"},
{"id": "geo-198", "q": "古人归纳总结出许多观天象识天气的谚语。下列与天气变化无关的谚语是：", "options": ["东风是个精，不下也要阴", "天上鱼鳞云，地下雨淋淋", "朝霞不出门，晚霞行千里", "百日连阴雨，总有一日晴"], "a": 3, "e": ".【D】本题考查科技常识。A项是气候谚语，我国温带区域和它的北面（即约在30°N以北的地方）的雨水，主要是由于气旋带来的，气旋的行动，总是自西向东的，在它的前部，盛行着东北风、东风或东南风；气旋将到的时候，风向必定偏东，所以东风可以被看作气旋将来的预兆；而气旋是一种风暴，是温带区域下雨的主要因子，所以我们看到吹东风，可知是雨天的先兆。B项是气候谚语，“鱼鳞云”是秋冬季强冷空气来时出现的一种天气现象。一般而言，冷空气来之前，云层较高，数量也不多。冷空气下来后，云层逐渐压低、加厚，人们会看见成片浓重的云，接着就会下雨了。C项是气候谚语，霞是由于日出和日落前后，阳光通过厚厚的大气层，被大量的空气分子散射的结果。当空中的尘埃、水汽等杂质愈多时，其色彩愈显著。如果有云层，云块也会染上橙红艳丽的颜色。日出前后出现鲜红的朝霞，说明大气中的水汽已经很多，而且云层已经从西方开始侵入本地区，预示天气将要转雨。出现大红色金黄色的晚霞，表示在我们西边的上游地区天气已经转晴或云层已经裂开，阳光才能透过来造成晚霞，预示笼罩在本地上空的雨云即将东移，天气就要转晴。D项不是气候谚语，“百日连阴雨，总有一日晴”说的是逆境只是暂时的，总会有峰回路转的那天，暗示不要失去信心。本题为选非题，故正确答案为D。", "tag": "地理国情"},
{"id": "geo-199", "q": "地球是一个赤道两极部分比较凸出的扁球体，而非几何学中所说的正球体，造成这种现象的主要原因是：", "options": ["自身引力结果", "自转造成", "自身形成过程中形成", "太阳及其他行星引力"], "a": 1, "e": ".【B】由于地球的自转，除地轴以外，地球上的质点都以地轴为中心做圆周运动，因而都产生惯性离心力，只要地球不停止转动，这种力就永远存在，并且力的方向都是垂直于地轴而背离地轴的。惯性离心力可分解为两个分力，一是垂直于地球表面的分力，一是水平分力，水平分力均指向赤道，因此地球上的物质有向赤道运动的趋势，使地球由正球体变成长球体。地球由大陆、大洋两部分组成，大陆是刚体的物质组成，不易发生显著运动，而海洋中的水是流体，可以有明显的运动，地球扁球体的形状不是固定不变的，它因地球自转速度的变化而变化，如果地球自转速度变快，离心力增大，海水从高纬流向低纬，地球偏心率增大；若地球自转速度变慢，离心力减小，海水从低纬流向高纬，地球偏心率减小。故正确答案为B。", "tag": "地理国情"},
{"id": "geo-200", "q": "关于气象和地质灾害的说法，不正确的是：", "options": ["火山喷发能形成地热、矿产等资源", "泥石流活动周期与暴雨、洪水的活动周期大体一致", "沙尘天气形成和变化主要因素是低层大气环流的变化", "我国一般只在春夏季的长江淮河流域发生洪涝灾害"], "a": 3, "e": ".【D】我国洪涝灾害多发生于春、夏、秋季，以夏季最为集中。我国的洪涝灾害最为常见且危害范围较广。雨涝灾害最严重的地区主要为东南沿海地区、湘赣地区、淮河流域，次多雨涝区有长江中下游地区、南岭、武夷山地区、海河和黄河下游地区、四川盆地、辽河、松花江地区。本题为选非题，故正确答案为D。", "tag": "地理国情"},
{"id": "geo-201", "q": "下列关于河流的描述，不正确的是：", "options": ["尼罗河是干流流经国家数量最多的河流", "伏尔加河是世界上最长的内流河", "亚马逊河是世界上水量最丰沛的河流", "湄公河的上游在中国境内被称为澜沧江"], "a": 0, "e": ".【A】多瑙河是一条著名的国际河流，是世界上流经国家最多的一条河流。它发源于德国西南部黑林山东麓海拔679米的地方，自西向东流经奥地利、捷克、斯洛伐克、匈牙利、克罗地亚、前南斯拉夫、保加利亚、罗马尼亚、乌克兰等9个国家后，流入黑海。多瑙河全长2860公里，是欧洲第二大河。多瑙河像一条蓝色的飘带蜿蜒在欧洲的大地上。本题为选非题，故正确答案为A。本题相关知识点：尼罗河是一条流经非洲东部与北部的河流，与中非地区的刚果河以及西非地区的尼日尔河并列非洲最大的三个河流系统。尼罗河长6670公里，是世界上最长的河流。", "tag": "地理国情"},
{"id": "geo-202", "q": "干燥的冷空气和富含水蒸气的暖空气相遇，发生大规模碰撞时形成的极端天气现象是：", "options": ["热带风暴", "台风", "飓风", "龙卷风"], "a": 3, "e": ".【D】龙卷风是在极不稳定天气下，由两股空气强烈对流运动而产生的一种伴随着高速旋转的漏斗状云柱的强风涡旋。龙卷风内部空气极为稀薄，导致温度急剧降低，促使水汽迅速凝结，这是形成漏斗云柱的重要原因。它的形成与暖湿空气强烈上升、冷空气南下、地形作用等有关。故正确答案为D。本题相关知识点：", "tag": "地理国情"},
{"id": "geo-203", "q": "北京时间2011 年9 月29 日，“天宫一号”目标飞行器发射后大约10 分钟，到达了近地点约200 千米、远地点约346千米的轨道。该运行轨道所处大气层的特点是：", "options": ["气温随高度的增加而递减", "对流现象显著，多云雨现象", "气流平稳，天气晴朗，有利于航空飞行", "存在电离层，可反射无线电波"], "a": 3, "e": ".【D】大气层从接近地表排序依次为对流层、平流层、中间层、电离层、外层。其中，电离层大约距地球表面60至", "tag": "地理国情"},
{"id": "geo-204", "q": "下列自然现象的产生与人类排放大气污染物无关的是：", "options": ["阴霾天气", "臭氧层空洞", "酸雨", "雷电"], "a": 3, "e": ".【D】A项正确，气象学上把大气中悬浮的大量微小尘粒、烟粒或盐粒的集合体，使空气浑浊，水平能见度降低到10km以下的一种天气现象称为阴霾天气。汽车尾气、煤燃烧排放物中含有能够对大气造成污染的颗粒物，可造成阴霾天气，故阴霾天气与大气污染物有关。这与排放污染物有关。B项正确，臭氧层空洞主要是由于平流层内超音速飞机排放大量的NO，以及人类大量生产与使用的氯氟烃化合物（氟利昂）等引起的，NO与氟利昂都是大气污染物。C项正确，酸雨主要是由于人类向大气中大量排放二氧化硫、氮氧化物等酸性气体引起的。D项错误，雷电是自然现象，与大气污染物无关。本题为选非题，故正确答案为D。", "tag": "地理国情"},
{"id": "geo-205", "q": "下列关于日食和月食的判断，正确的是：", "options": ["日、月食的成因只与日、地、月三个天体的几何位置有关", "日食与月食都是自然现象，所以它们是不可能准确预报的", "当月相是朔的时候就一定会发生日食", "如果日食带在我国经过，肯定是东部的居民先看到"], "a": 0, "e": ".【A】A项正确，日食是由于月球对太阳光的遮挡形成的，月食是由于地球对太阳光的遮挡形成的，故日、月食的成因只与日、地、月三个天体的几何位置有关。B项错误，日食与月食的发生时间可根据地、月运行规律准确推算得出，是可以准确预报的。C项错误，日食发生需满足两个条件：①日食总是发生在朔日（农历初一，此时月球处于日、地之间，月球阴暗的一面对着地球）；②太阳和月球都移到白道和黄道的交点附近。月球运行的轨道（白道）和太阳运行的轨道（黄道）并不在一个平面上，白道平面和黄道平面有5°9′的夹角，只有当太阳和月球都移到白道和黄道的交点附近时才会发生日食。因此，不是所有朔日必定发生日食。D项错误，由于月亮自西向东运动，月影也是自西向东移动，因此总是西部地区比东部先看到日食。故正确答案为A。", "tag": "地理国情"},
{"id": "geo-206", "q": "下列关于日食的表述不正确的是：", "options": ["一次完整的日食过程的顺序是：初亏、食既、食甚、生光、复圆", "中国的《尚书》上有世界上最早的日食记录", "日食主要有日全食、日偏食和日环食", "日全食是因为地球挡住了太阳光线"], "a": 3, "e": ".【D】本题要求选出表述“不正确”的一项。地球轨道与月球轨道有一个5度的夹角，在特定的时间月球会运行至一个特别的位置，令太阳、月球及地球连成一线，这时月球刚好遮掩了太阳的光球，这样便形成了一次日食。故正确答案为D。", "tag": "地理国情"},
{"id": "geo-207", "q": "“春雨惊春清谷天，夏满芒夏暑相连，秋处露秋寒霜降，冬雪雪冬小大寒。”节气对于指导农业生产具有很强的科学性。下列反映阳历六月初节气的农谚是：", "options": ["立夏桑果像樱桃", "小满养蚕又种田", "芒种玉秧放庭前", "夏至稻花如白练"], "a": 2, "e": ".【C】这道题考查考生对节气的掌握程度。解答本题时，需要考生了解哪个节气出现在六月初。题干引号内的内容是二十四节气口诀，其中“夏满芒夏暑相连”中的第一个“夏”指的是“立夏”，第二个“夏”指的是“夏至”，夏至一般在每年的6月20、21或22日，每个节气的间隔时间为十五天，这样推断，出现在六月初的节气是芒种，正确答案选C。A选项“立夏”是阳历五月初；B选项“小满”是阳历五月底；D选项“夏至”是阳历六月中下旬。故正确答案为C。", "tag": "地理国情"},
{"id": "geo-208", "q": "我国的地势是：", "options": ["东高西低", "南高北低", "西北走", "西高东低"], "a": 3, "e": ".【D】我国地势呈西高东低走势，西南青藏高原平均海拔在4000米以上，东部沿海地区平均海拔500米以下。故正确答案为D。本题相关知识点：第一阶梯包括：青藏高原、柴达木盆地。第二阶梯包括：准噶尔盆地、塔里木盆地、四川盆地、内蒙古高原、黄土高原、云贵高原。第三阶梯包括：东北平原、华北平原、长江中下游平原、辽东丘陵、山东丘陵、东南丘陵。", "tag": "地理国情"},
{"id": "geo-209", "q": "关于地理常识，下列说法错误的一项是（）。", "options": ["昼夜长短主要是由地球自转造成的", "红海是盐度最高的海域", "马达加斯加岛东侧沿海属热带雨林气候", "本初子午线不是东西半球的分界线"], "a": 0, "e": ".【A】本题考查地理国情。A项错误，昼夜的变化，也即白天和黑夜的交替变化是由于地球自转造成的，而昼夜的长短和太阳直射点的位置有关，是由地球公转引起的。B项正确，红海位于非洲东北部与阿拉伯半岛之间，呈现狭长型。其西北面通过苏伊士运河与地中海相连，南面通过曼德海峡与亚丁湾相连。红海地处北回归线高压带控制的范围，腹背由于北非和阿拉伯半岛热带沙漠气候的影响，且受东西两侧热带沙漠夹峙，气候终年干热，降水稀少，是盐度最高的海。C项正确，马达加斯加岛东侧位于山地迎风坡；东南信风来自海洋，带来丰沛的水汽；沿岸马达加斯加暖流增温增湿。全年高温多雨，形成热带雨林气候。D项正确，国际上将通过英国伦敦格林尼治天文台原址的那条经线称为经线，也叫本初子午线，但不是东西半球的分界线，东西半球的分界线是西经20度，东经160度。本题为选非题，故正确答案为A。", "tag": "地理国情"},
{"id": "geo-210", "q": "下列哪一首诗描写的景色离长江入海口最近（）。", "options": ["日照香炉生紫烟，遥看瀑布挂前川", "最爱湖东行不足，绿杨阴里白沙堤", "日暮乡关何处是，烟波江上使人愁", "窗含西岭千秋雪，门泊东吴万里船"], "a": 1, "e": ".【B】本题考查地理国情。长江发源于青藏高原的唐古拉山脉各拉丹冬峰西南侧，干流流经青海、西藏、四川、云南、重庆、湖北、湖南、江西、安徽、江苏、上海11个省、自治区、直辖市，于崇明岛以东注入东海，全长约6300km。A项错误，“日照香炉生紫烟，遥看瀑布挂前川”出自唐朝李白的《望庐山瀑布》，描写的是江西庐山景色。B项正确，“最爱湖东行不足，绿杨阴里白沙堤”出自唐朝白居易的《钱塘湖春行》，描写的是杭州西湖景色。C项错误，“日暮乡关何处是，烟波江上使人愁”出自唐朝崔颢的《黄鹤楼》，描写的是湖北省黄鹤楼景色。D项错误，“窗含西岭千秋雪，门泊东吴万里船”出自唐朝杜甫的《绝句》，描写的是四川省成都一处景色。江西庐山、杭州西湖、湖北黄鹤楼以及四川成都四个地方相比起来，西湖最靠近长江入海口。故正确答案为B。", "tag": "地理国情"},
{"id": "geo-211", "q": "以下有关天文学的说法正确的是（）。", "options": ["行星三大运行定律是由伽利略提出来的", "世界上最早关于太阳黑子的文献记载是在中国", "八大行星中除了地球均会出现冲日现象", "2018 年科学家在金星上发现了液态水湖"], "a": 1, "e": ".【B】本题考查地理常识。A项错误，行星三大运行定律是开普勒提出来的，不是伽利略，所以又叫开普勒定律。这三大定律分别称为轨道定律、面积定律和周期定律。B项正确，世界上公认的最早记载太阳黑子的记录，是《汉书・五行志》中有关公元前28年的太阳黑子记录。C项错误，地球与地外行星分布于太阳同侧，且三者在同一直线上时叫作冲日。如果这时行星又距地球最近则称为“大冲”。这时的行星最亮，整夜可见，最宜于观测。地外行星会出现冲日现象，地外行星包括火星、木星、土星、天王星和海王星。因此，除地球外，水星、金星也不会出现冲日现象。D项错误，2018年7月25日，科学家在火星上发现了第一个液态水湖。故正确答案为B。", "tag": "地理国情"},
{"id": "geo-212", "q": "古有“数九寒冬”之说，“一九二九不出手，三九四九冰上走，五九六九沿河看柳，七九河开，八九燕来，九九加一九，耕牛遍地走。”这首数九歌在我国北方地区广为流传。关于这首歌的说法，下列正确的是（）。", "options": ["入“九”从二十四节气中的立冬日开始算起", "入“九”之后太阳直射点从赤道开始往南移动", "“九九”结束之后我国即将迎来二十四节气中的立春", "“一九”到“九九”的变化与地球的公转有关"], "a": 3, "e": ".【D】本题考查地理国情。A项错误，我国古代将冬至日算起的八十一天分为九段，各为九天，称为冬九九，并按次序定名为“一九”、“二九”、“三九”、“九九”。B项错误，入“九”之日刚好是二十四节气中的冬至。冬至这天，太阳直射地面的位置到达一年的最南端，几乎直射南回归线（南纬）。所以，入“九”之后太阳直射点是从南回归线开始往北移动的。C项错误，自冬至起便开始“数九”，每九天为一个“九”。“九九”之后我国即将迎来的是“春分”节气，而非二十四节气中的“立春”。D项正确，地球每365天5时48分46秒，围绕太阳公转一周。由于地球旋转的轨道面同赤道面不是一致的，而是保持一定的倾斜，所以一年四季太阳光直射到地球的位置是不同的。地球公转的地理意义：1.太阳直射点的回归运动；2.昼夜长短变化；3.正午太阳高度的变化；4.四季和五带划分。所以，“一九”到“九九”的变化与地球的公转有关。故正确答案为D。", "tag": "地理国情"},
{"id": "geo-213", "q": "关于诗文中地理信息的解读，下列说法错误的是（）。", "options": ["“昼晷已云极，宵漏自此长”描写的这天里太阳直射点处于北回归线", "“寻章摘句老雕虫，晓月当帘挂玉弓”中的情景发生在农历初三左右", "“七月流火，九月授衣”中“流火”指的是大火星西沉，天气将转寒", "“冷眼向洋看世界，热风吹雨洒江天”中“热风”指西南和东南季风"], "a": 1, "e": ".【B】本题考查地理国情。A项正确，“昼晷已云极，宵漏自此长”出自唐代诗人韦应物所作的《夏至避暑北池》，意指白天时长已经到了极限（晷是古代用来观测日影以定时刻的仪器），从此夜晚的时长逐渐增加（漏是漏壶，古代滴水计时工具）。夏至日，太阳直射点位于北回归线，北半球各地昼长夜短（北极圈内出现极昼现象），夏至日过后，太阳直射点向南移动，北半球各地昼长逐渐减小，夜长逐渐增加，直至秋分日，太阳直射点到达赤道，全球昼夜平分。B项错误，随着月亮每天在星空中自西向东移动一大段距离，它的形状也在不断地变化着，这就是月亮位相变化，叫做月相。月相变化可粗略概括为：新月（朔月）-上娥眉月-上弦月-满月（望月）-下弦月-下娥眉月（残月）-新月（朔月），如此往复循环，具体而言（以下情形均以东半球观测月相为例）：“寻章摘句老雕虫，晓月当帘挂玉弓”意指我只是有一些写作诗文辞赋的雕虫小技罢了，（发奋写作一夜）破晓时分的月亮像是帘子上挂着的玉弓。由“晓月”可知月亮出现于破晓时分，由“玉弓”可知月相为娥眉月，破晓（黎明）时分看到娥眉月为下娥眉月（残月），时间为廿五廿六。C项正确，“七月流火，九月授衣”出自《诗经‧豳风‧七月》，《毛传》中记载：“火，大火也。流，下也。”其中“大火”是星名，故“火”是指“大火”星，“流”是指星宿西沉，故七月流火意指大火星西沉，天气将寒。“大火”星是指我国古代星宿体系中的“心宿二”，“心宿”是古代东方苍龙七宿之一，包含三颗星，“心宿二”是中间的一颗，是亮度很高的一等星，对应西方星座体系中天蝎座α星（天蝎座主星）。D项正确，“冷眼向洋看世界，热风吹雨洒江天”出自毛泽东主席所作《七律•登庐山》（创作于1959年6月底），庐山位于江西，“向洋看”是望向太平洋，“热风吹雨”是亚热带季风区夏季风带来的雨水，我国夏季风是来自太平洋的东南季风和来自印度洋的西南季风。本题为选非题，故正确答案为B。", "tag": "地理国情"},
{"id": "geo-214", "q": "下列关于极光的说法正确的是：", "options": ["多出现在高磁纬地区上空", "是地球所特有的现象", "是极昼、极夜现象产生的原因", "水汽、磁场和带电粒子是其产生的必要条件"], "a": 0, "e": ".【A】极光是出现于星球的高磁纬地区上空，是一种绚丽多彩的发光现象。在南极被称为南极光，在北极被称为北极光。地球的极光是来自地球磁层或太阳的高能带电粒子流（太阳风）使高层大气分子或原子激发（或电离）而产生。A项：正确，极光产生必备条件之一是高能粒子，由于地磁场的作用，这些高能粒子转向极区，所以极光常见于高磁纬地区。B项：错误，极光不只在地球上出现，太阳系内具备大气、磁场、高能带电粒子的行星上也有极光。C项：错误，产生极昼、极夜现象的原因是倾斜着的地球在沿椭圆形轨道绕太阳公转时，还绕着自身的倾斜地轴旋转。D项：错误，极光产生的条件有三个：大气、磁场、高能带电粒子，水汽不是极光产生的必要条件。故正确答案为A。", "tag": "地理国情"},
{"id": "geo-215", "q": "火星轨道在地球轨道的外圈，与地内行星相比，从地球上能观测到火星的时间和位置变化范围很大。古人有“火星冲日”的说法，在“火星冲日”这天，火星最亮，在夜空停留的时间也最久。“火星冲日”最可能发生在下图（）位置。", "options": ["A", "B", "C", "D"], "a": 2, "e": ".【C】本题考查地理常识中“火星冲日”时火星、地球和太阳三者之间的位置。地球在火星和太阳之间时就发生火星冲日。当火星与太阳视黄经相差180度时，称为火星冲日。这时，火星和太阳分别位于地球的两边，太阳刚一落山，火星就从东方升起，而等到太阳从东方升起时，火星才在西方落下，因此整夜都可观测火星。一般来说，冲日时，火星离地球较近，它的亮度也是一年当中最亮的。故A、B、D三项错误。故正确答案为C。", "tag": "地理国情"},
{"id": "geo-216", "q": "关于北斗七星，下列说法正确的是：", "options": ["北斗七星的相对位置始终不变", "北斗七星是七颗亮度相等的恒星", "北斗七星中的开阳星与其辅星构成双星", "古代“斗牛”中的“斗”指北斗七星"], "a": 2, "e": ".【C】本题考查了天文常识。A项错误，北斗七星在天空中做缓慢的相对运动，其中五颗星以大致相同的速度朝着一个方向运动，而“天枢”和“摇光”则朝着相反的方向运动。因此，在漫长的宇宙变迁中，北斗七星的相对位置会发生较大的变化。B项错误，北斗七星都是恒星，其中“玉衡”最亮，亮度几乎接近一等星。“天权”最暗，是一颗三等星。所以它们的亮度并不相等。C项正确，从北斗七星勺柄数起的第二颗是开阳星，它与其辅星构成了一对观测者能直接用望远镜分辨开出的双星。D项错误，“斗牛”是指“斗宿”和“牛宿”，其中“斗宿”指的不是北斗，而是只有六颗星星的南斗。故正确答案为C。", "tag": "地理国情"},
{"id": "geo-217", "q": "世界大河中，与长江流向大致相同的是：", "options": ["尼罗河", "印度河", "亚马逊河", "伏尔加河"], "a": 2, "e": ".【C】A项尼罗河大体上都是由南向北的流向，B项印度河大体上是由东北向西南的流向，D项伏尔加河是南北走向，大致上是由北向南流向。只有C项亚马逊河与长江的流向一样，都是自西向东。故正确答案为C。", "tag": "地理国情"},
{"id": "geo-218", "q": "关于下列地区的说法错误的是：", "options": ["欧洲北海：既是著名产油区，又是著名渔场", "波斯湾地区：既是著名产油区，又是古文明发祥地", "湄公河流域：既是小麦主产区，又是佛教圣地", "五大湖区：既有世界上面积最大的淡水湖，又跨美加两国边境线"], "a": 2, "e": ".【C】本题考查地理常识。A项正确，北海是著名的产油区，是位于欧洲大陆西北部和大不列颠岛之间的北海海底油田，上世纪80年代开始被大规模开采，使沿岸的英国成为世界上重要产油国之一。北海渔场是受北大西洋暖流与来自北冰洋的南下海水交汇形成的大渔场，冷暖海水在此交汇，为鱼类带来丰富饵料，鱼产丰富，种类繁多，是世界上著名的四大渔场之一。B项正确，波斯湾位于伊朗高原和阿拉伯半岛之间，在波斯湾及其周边形成了一条巨大的石油带，这里蕴藏着占世界石油总储量一半以上的石油。波斯湾地区历史悠久，在伊拉克东南部幼发拉底河和底格里斯河的下游曾诞生苏美尔文明，是两河流域早期文化的创造者。C项错误，湄公河上游在中国境内被称为澜沧江，流经的地区有老挝、缅甸、泰国、柬埔寨、越南，为东南亚重要的水稻产区，因此“小麦主产区”的说法错误。湄公河流域的地区和国家佛教盛行，佛寺众多，因此“佛教圣地”的说法正确。湖、伊利湖和安大略湖。其中苏必利尔湖是世界上面积最大的淡水湖。本题为选非题，故正确答案为C。", "tag": "地理国情"},
{"id": "geo-219", "q": "下表列出了分布在我国的几种土壤的特质，填入表格最合适的是：", "options": ["①紫色土②热带③玉米，苹果", "①黑土②暖温带③甘蔗，油菜", "①黑土②中温带③小麦，茶叶", "①紫色土②亚热带③水稻，荔枝"], "a": 1, "e": ".【B】本题考查地理国情。①紫色土是指亚热带、热带湿润地区紫色砂页岩风化物上发育的一种母质特征明显的土壤，我国主要分布在四川盆地等地区，土壤肥力较高，主要经济作物为油菜、棉花。黑土是指温暖半湿润地区发育的富含腐殖质和植物营养元素的黑色土壤，在我国主要分布于黑龙江、吉林两省，土壤肥力高。根据题目表格，位于中温带土壤肥力高且适合种植大豆、甜菜的，应当是黑土。②温带又可分为寒温带、中温带、暖温带。我国的黄土主要分布于黄土高原地区。黄土高原大部分位于暖温带，故此处应选暖温带。黄土是一种并不非常肥沃的土壤，由很细的粘土和被风吹来的淤积颗粒所组成，其主要的经济作物为棉花、花生。③红土是在亚热带湿热气候条件下由碳酸盐类或硅酸盐类岩石风化形成，一般呈褐红色，是一种具有高含水率、低密度、较高强度和较低压缩性的土。主要分布在我国长江以南地区，主要经济作物为甘蔗、油菜、茶树等。故①为黑土，②为暖温带，③为甘蔗、油菜。故正确答案为B。", "tag": "地理国情"},
{"id": "geo-220", "q": "下列诗句所描述情景出现的时间与图中标示的时间段，对应正确的是：", "options": ["今夜月明人尽望，不知秋思落谁家——④①之间", "接天莲叶无穷碧，映日荷花别样红——②③之间", "天街小雨润如酥，草色遥看近却无——①②之间", "半盏屠苏犹未举，灯前小草写桃符——③④之间"], "a": 3, "e": ".【D】太阳直射点一年中在南北回归线之间移动，大致方向为：（1）春分（3月21日前后）——夏至（6月22日前后），从赤道移动至北回归线。（2）夏至（6月22日前后）——秋分（9月23日前后），从北回归线移动至赤道。（3）秋分（9月23日前后）——冬至（12月22日前后），从赤道移动至南回归线。（4）冬至（12月22日前后）——春分（3月21日前后），从南回归线移动至赤道。A项错误，④到①时段是春分到夏至。而由选项“秋思”可知诗句发生在秋天，不可能是在④到①之间，因此错误。B项错误，②到③时段是秋分至冬至。而由选项“莲叶”“荷花”可知诗句发生在夏季，不可能在②到③之间，因此错误。C项错误，①到②时段是夏至至秋分。而选项诗句出自韩愈的《早春》，发生在春季，不可能在①到②之间，因此错误。D项正确，③到④时段是冬至至春分。而由选项“屠苏”、“桃符”可知是春节，古人春节习俗，有悬挂“桃符”、饮屠苏酒的风俗。农历春节在大寒和立春之间，即太阳直射点在③至④之间，该选项正确。故正确答案为D。", "tag": "地理国情"},
{"id": "geo-221", "q": "关于太阳，下列说法不正确的是：", "options": ["通过核聚变来释放能量", "目前已经进入衰老期", "所产生的能量主要靠辐射方式传播", "集中了太阳系中的绝大部分的质量"], "a": 1, "e": ".【B】B项说法不正确，太阳是一颗黄矮星，黄矮星的寿命大致为100亿年，目前太阳大约45.7亿岁，还没进入衰老期。A、C、D项说法均正确，太阳是太阳系的中心天体，集中了太阳系99.86%的质量，它通过核聚变来释放能量，所产生的能量主要靠辐射方式传播。本题为选非题，故正确答案为B。", "tag": "地理国情"},
{"id": "geo-222", "q": "下列现象与地转偏向力没有直接关联的是：", "options": ["我国河流大都右岸较为陡峭，左岸较为平缓", "北印度洋环流在冬季呈逆时针方向流动，夏季反之", "从卫星云图上看，北半球的台风成逆时针方向旋转，南半球反之", "随着太阳直射点北移，南印度洋的东南信风越过赤道形成西南季风"], "a": 1, "e": ".【B】本题考查地理国情。地转偏向力，是指地球由于自转而形成的一种惯性力，在这种力的作用下，地球上水平运动的物体，无论朝着任何方向运动，都和直线方向发生偏离，在北半球向右偏，在南半球向左偏。地转偏向力对作为气体和流体的气流、河流、洋流等水平运动方向影响很大，具有重要的地理意义。A项正确，我国在北半球，在地转偏向力作用下，河水冲刷右岸严重，左岸则流水较慢，淤积为主。所以，河流左岸平缓，右岸陡峭。B项错误，北印度洋由于受南亚热带季风气候的影响，形成了特殊的北印度洋季风环流，夏季在西南季风的影响下形成顺时针大洋环流圈，冬季在东北季风的影响下形成逆时针大洋环流圈。C项正确，台风是一种热带气旋，形成于赤道地区的温暖水域。当潮湿、温暖的空气开始上升，就会产生一个低压区，进而吸引周围更多的暖湿空气。温暖的空气在上升的过程中开始旋转，并且温度开始下降，冷凝生成云团，释放出热量，释放的热量进一步加快上升运动。在这种正反馈机理的促进下，气旋不断加强，最终形成巨大的台风。如果地球没有自转，那么风只会简单的从高压区吹向低压区。由于地球是旋转的，因此当温暖的空气上升时，受到地转偏向力的作用，就会形成气旋。由于在南北半球地转偏向力的方向恰好相反，因此在北半球风会围绕低压区做逆时针运动，而在南半球绕低压区做顺时针运动。D项正确，随着太阳直射点北移，赤道低气压带北移，南印度洋的东南信风越过赤道，受地转偏向力影响，形成西南季风。本题为选非题，故正确答案为B。", "tag": "地理国情"},
{"id": "geo-223", "q": "掩星是一种天文现象，指一个天体在另一个天体与观测者之间通过而产生的遮蔽现象。科学家经常借助观察这一现象来判断星体是否有大气层。当行星掩过遥远恒星，如果恒星变得模糊之后才消失，那么可以认为：", "options": ["该行星有稠密的大气层", "该恒星有稠密的大气层", "该行星无大气层或大气层稀薄", "该恒星无大气层或大气层稀薄"], "a": 0, "e": ".【A】A项正确：被遮蔽恒星变模糊之后才消失，是由于遮掩行星存在有稠密的大气层。在掩星过程中先是由这层大气层对恒星进行遮掩，由于大气层可以透光，但会对光线进行散射和反射，因此在观测者看来恒星变得暗淡模糊。而当行星完全遮掩恒星后，恒星的光线无法透过行星本体，因此观测者看到恒星消失，当选；C项错误：若行星无大气层或大气层稀薄，在掩星过程中，将不存在恒星变得模糊的过程，排除；B、D项错误：恒星本身具有大气层，若其自身的大气层会导致模糊，则不会仅在掩星现象中模糊。因此掩星现象的发生与被掩蔽恒星是否有大气层无关，排除。故正确答案为A。", "tag": "地理国情"},
{"id": "geo-224", "q": "下列说法中，错误的是：", "options": ["山东省与山西省因位于太行山东西两侧而得名", "湖南省与湖北省因位于洞庭湖南北两侧而得名", "河南省与河北省因位于黄河南北两侧而得名", "广东省与广西省因位于珠江东西两侧而得名"], "a": 3, "e": ".【D】本题考查地理国情。A项正确，山东因在太行山以东而得名，山西以在太行山之西而得名。B项正确，湖南省与湖北省以洞庭湖为界，在洞庭湖以南的是湖南省，在洞庭湖以北的是湖北省。C项正确，河南省与河北省古时以黄河为界，河南省因历史上大部分位于黄河以南，故名河南，河北因位于黄河下游以北而得名。现在更多的说法是河南省河北省以漳河为界。D项错误，历史上，在宋太宗时期，将岭南道改名广南路，随后分成广南东路和广南西路，简称即是广东广西，故广东广西是以处于“岭南道”的地理位置来得名的，而和珠江并无关系。本题为选非题，故正确答案为D。", "tag": "地理国情"},
{"id": "geo-225", "q": "关于大河起源，下列对应错误的是：", "options": ["长江——唐古拉山", "黄河——巴颜喀拉山", "莱茵河——阿尔卑斯山", "亚马逊河——落基山"], "a": 3, "e": ".【D】本题考查世界地理中的大河起源。A项正确，长江是我国第一长河，起源于“世界屋脊”——青藏高原的唐古拉山脉各拉丹冬峰西南侧。自西向东干流流经11个省、自治区、直辖市，于崇明岛以东注入东海。B项正确，黄河是我国第二长河，起源于我国青海省巴颜喀拉山脉。自西向东流经9个省、自治区，最后流入渤海。C项正确，莱茵河是西欧第一大河，起源于瑞士境内的阿尔卑斯山北麓，西北流经列支敦士登、奥地利、法国、德国和荷兰，最后在鹿特丹附近注入北海。D项错误，亚马逊河位于南美洲，是世界第二长河。最西端的发源地是位于太平洋附近的安第斯山，入口在大西洋。落基山位于北美洲。本题为选非题，故正确答案为D。", "tag": "地理国情"},
{"id": "geo-226", "q": "日常生活中经常可以依据动物的某些行为预判天气，下列对应正确的是：", "options": ["麻雀囤食——雨天", "蚂蚁垒窝——晴天", "蜻蜓低飞——雨天", "龟背冒“汗”——晴天"], "a": 2, "e": ".【C】A项错误，麻雀囤食要落雪，麻雀预见到要下雪的话，赶紧多准备食物，否则下雪了无处觅食就会饿死。B项错误，蚂蚁垒窝要下雨，蚂蚁天性喜欢干燥，在它的身体上有一个感知水分的器官，当空气中的水分太高时，它就感觉要下雨了，就会向高处搬家，以免被雨水淹。C项正确，蜻蜓飞得低是因为要下雨了，通常在下雨之前，空气中的湿度相当高，昆虫一遇到潮湿的水气，往往翅膀会沾湿，此时就是蜻蜓捕捉猎物的好时机，所以，才会有看见蜻蜓低飞。D项错误，“龟背冒汗，出门带雨伞”。乌龟背壳潮湿，壳上的纹路混而暗，是天要降雨的征兆；龟壳有水珠，像是冒汗，将要下大雨；龟壳干燥，纹路清晰，预示近期不会下雨。故正确答案为C。", "tag": "地理国情"},
{"id": "geo-227", "q": "吉林雾凇形成的条件是：", "options": ["松花江江心常年不封冻，容易形成大量水蒸气", "松花湖作为人工湖泊处于十分独特的地理位置", "丰满水电站放出的暖水与冷空气间的相互作用", "松花江吉林市段河道变窄，水流湍急形成大雾"], "a": 2, "e": ".【C】雾凇是雾气和水汽遇冷凝结在枝叶上的冰晶，温度够低和湿度够高是形成雾凇的基本条件。吉林市属于寒温带大陆性气候，冬季严寒，但由于丰满水电站的存在，使环绕吉林市的松花江在冬季不封冻。不冻的松花江江面向空中大量蒸发水汽，而因为地面温度低，水汽在上升过程中遇冷凝结或凝华，形成吉林雾凇奇观。故正确答案为C。", "tag": "地理国情"},
{"id": "geo-228", "q": "下列诗句描写的地方都位于长江流域，按照从上游到下游排序正确的是：①猿愁鱼踊水翻波，自古流传是汨罗②白帝城中云出门，白帝城下雨翻盆③昔登江上黄鹤楼，遥爱江中鹦鹉洲④钟山如龙独西上，欲破巨浪乘长风", "options": ["①②③④", "②①④③", "②①③④", "①②④③"], "a": 2, "e": ".【C】长江流经的主要城市自上游至下游依次为攀枝花、重庆、宜昌、岳阳、武汉、九江、芜湖、南京、上海。①“猿愁鱼踊水翻波，自古流传是汨罗”出自唐韩愈的《湘中》，诗中描写的汨罗江在湖南岳阳。②“白帝城中云出门，白帝城下雨翻盆”出自唐杜甫的《白帝》，诗中描写的白帝城位于重庆奉节县瞿塘峡口的长江北岸，奉节东白帝山上。③“昔登江上黄鹤楼，遥爱江中鹦鹉洲”出自唐孟浩然的《鹦鹉洲送王九之江左》，诗中描写的地点位于湖北武汉。④“钟山如龙独西上，欲破巨浪乘长风”出自明高启的《登金陵雨花台望大江》，诗中描写的地点位于今江苏南京。故按从上游至下游排序应为②①③④。故正确答案为C。", "tag": "地理国情"},
{"id": "geo-229", "q": "关于板块构造学说，下列说法错误的是：", "options": ["六大板块是对地球表面陆地板块部分的划分", "建立在大陆漂移和海底扩张学说的基础上", "喜马拉雅是由两大板块碰撞挤压形成的", "火山、地震等地质灾害主要是发生在板块边缘"], "a": 0, "e": ".【A】A项错误，全球地壳六大板块有太平洋板块、亚欧板块、非洲板块、美洲板块、印度洋板块和南极洲板块，其中除太平洋板块几乎全为海洋外，其余五个板块既包括大陆又包括海洋。B项正确，大陆漂移学说是一种关于地壳构造运动的科学假说，由德国气象学家魏格纳首先提出和倡导。海底扩张学说是解释地壳结构和地壳运动的假说，是大陆漂移学说的新形式和进一步的发展。而板块构造学说是在大陆漂移学说和海底扩张学说的基础上发展起来的，对地球上的海陆变化乃至整个地壳运动，作出了新的解释。C项正确，喜马拉雅山脉是由印度洋板块与欧亚大陆板块相互碰撞和交叠相挤形成的。D项正确，火山爆发是地球内部的熔融物质在板块挤压的作用下形成的。地震引发的原因是板块与板块之间相互挤压碰撞，造成板块边缘产生错动和破裂。而板块与板块之间地壳运动活跃，因此，火山、地震等地质灾害主要发生在各大板块彼此间的交界处。本题为选非题，故正确答案为A。", "tag": "地理国情"},
{"id": "geo-230", "q": "当地球运行到C 点时，下列说法符合长春市具体情况的是：", "options": ["昼长达一年最大值", "日落时间将逐渐推迟", "正午太阳高度角将逐渐增大", "正值冬至日"], "a": 0, "e": ".【A】A项正确，当地球运行到C点时，太阳直射北回归线，北半球的昼长达一年最大值，长春位于北半球，因此昼长达一年最大值；B项错误，太阳直射北回归线后，其直射点将逐渐南移，北半球各地白昼逐渐变短，日落时间将越来越早；C项错误，太阳直射北回归线时，北半球各地正午太阳高度角都达到最大值，之后太阳直射点逐渐南移，各地正午太阳高度角逐渐减小；D项错误，太阳直射北回归线时，北半球是夏至日。故正确答案为A。", "tag": "地理国情"},
{"id": "geo-231", "q": "关于地质年代与地层，下列说法错误的是：", "options": ["当岩层之间有切割现象时，被切割的岩层比切割的岩层古老", "发现大量三叶虫化石的岩层比发现大量鱼类化石的岩层古老", "放射性同位素方法可用来测定岩层的形成年代", "在全球范围内，形成于同一地质时期的岩层岩性都是相同的"], "a": 3, "e": ".【D】本题考查地理国情。D项：错误，在全球范围内，形成于同一地质时期的岩层岩性都是相同的，表述过于绝对，形成于同一地质时期、同一地质环境下的岩石性质才大致相同。A项：正确，岩层切割律又称穿插关系，就侵入岩与围岩的关系来说，总是侵入者年代新，被侵入者年代老，这就是切割律。即当岩层之间有切割现象时，被切割的岩层比切割的岩层古老。B项：正确，地球相对年龄的确立主要依据于化石。自从英国地质学家史密斯提出“化石层序律”后，就把时间与生物演化阶段联系起来。人们知道，在不同时代的地层中含有不同的化石，同样，我们得到了这些化石后也可以推断产出这些化石的地层年代。三叶虫出现的时间要略早于鱼类。故发现大量三叶虫化石的岩层比发现大量鱼类化石的岩层古老。C项：正确，该方法是1904年英国物理学家卢福首先提出的，此方法的基本原理是：假设岩石形成时，含有一定量的具放射性的母体同位素，随时间的流逝，该母体同位素蜕变，其含量逐渐减少，蜕变后形成的子体同位素则逐渐增多，只要测定母体同位素与子体同位素之比，则该比值就可作为岩石形成以来的时间的尺度。本题为选非题，故正确答案为D。", "tag": "地理国情"},
{"id": "geo-232", "q": "小王冬季从北京首都国际机场乘坐航班去某个机场，到达后发现手表显示的时间为18 点30 分，而机场所在地时间为22点30 分，他去的可能是以下哪个城市？", "options": ["华盛顿", "马尼拉", "曼彻斯特", "惠灵顿"], "a": 3, "e": ".【D】D项正确：从题干中可以看到，北京时间与所处的机场时间相差四个小时，北京所处的时区是东八区，惠灵顿处于东十二区，与北京相差四个时区，根据时区的计算方法“东加西减”，应加四个小时，当选；A项错误：华盛顿处于西五区，与北京相差13个小时，此时应为5点30分，排除；B项错误：马尼拉处于东八区，和北京属于同一个时区，所以时间是一致的，排除；C项错误：曼彻斯特属于零时区，与北京相差8个时区，此时应为10点30分，排除。故正确答案为D。", "tag": "地理国情"},
{"id": "geo-233", "q": "下列表述正确的是：", "options": ["我国最早出现的种植业位于松花江流域", "被誉为“天上云霞,地下鲜花”的是四川蜀绣", "东北平原是中国第二大平原，也是中国重要的粮棉生产基地"], "a": 0, "e": ".【A】本题考查地理国情。A项正确，鄱阳湖是全世界最大的白鹤集中越冬地，白鹤的数量占全世界总数的以上，堪称鹤之天堂。1983年世界鹤类会议上估计全世界白鹤数量为320只，这年冬季鄱阳湖所见则为409只。从此，逐年增多。1986年1月为1609只，目前多达数千只。1983年已在江西省永修县吴城镇建立了鄱阳湖候鸟保护区。B项错误，我国最早出现的种植业应位于黄河、长江流域。黄河、长江是中国的母亲河，这两条河流的冲积平原地区是中华文明的发祥地且两个平原处在温带湿润、半湿润地区，气候温暖湿润，比较适宜人类居住，所以种植业发展最早。C项错误，被誉为“天上云霞，地下鲜花”的是杭州的织锦。D项错误，东北平原是中国最大的平原，是中国三大平原之一。位于中国东北部，南北长约1000千米，东西宽约400千米，面积达35万平方千米。同时东北平原土地肥沃，是全球仅有的三大黑土区域之一，是中国重要的粮食、大豆、畜牧业生产基地，也是中国重要的钢铁、机械、能源、化工基地。故正确答案为A。", "tag": "地理国情"},
{"id": "geo-234", "q": "一跨国企业计划7 月份在全球两个大城市同期举办大型室外活动。为避免降雨影响活动效果，选择下列哪两个城市最为合理：", "options": ["北京和纽约", "东京和马德里", "上海和伦敦", "罗马和洛杉矶"], "a": 3, "e": ".【D】选项中8个城市都位于北半球，7月北半球正处于夏季。罗马和洛杉矶都属于地中海气候，特点是夏季炎热干燥，冬季温和多雨；北京为温带季风性气候，特点为夏季温热多雨，冬季寒冷干燥；纽约和马德里属于温带大陆性气候，特点为降水稀少且集中在夏季；东京属于亚热带海洋性季风气候，特点为夏季暖热多雨，雨热同季；上海属于亚热带季风气候，特点为夏季湿润多雨，冬季温和少雨；伦敦属于温带海洋性气候，全年多雨。故正确答案为D。", "tag": "地理国情"},
{"id": "geo-235", "q": "京沪铁路没有经过下列哪一名胜所在的省份？", "options": ["景德镇古窑民俗博览区", "蓬莱阁风景区", "承德避暑山庄", "黄山风景区"], "a": 0, "e": ".【A】景德镇古窑民俗博览区位于江西省；蓬莱阁风景区位于山东省；承德避暑山庄位于河北省；黄山风景区位于安徽省。京沪铁路自北向南经过的省份有：北京市、天津市、河北省、山东省、安徽省、江苏省、上海市。所以没有经过的省份是江西省。本题为选非题，故正确答案为A。", "tag": "地理国情"},
{"id": "geo-236", "q": "下列关于地震，说法错误的是：", "options": ["按地震的成因，可分为构造地震、火山地震、塌陷地震和诱发地震四种", "一次地震只有一个震级，但有多个烈度", "四大地震带中，最大的地震带是环太平洋地震带", "距震中越近，烈度越大；反之越小"], "a": 2, "e": ".【C】C项错误：世界上的地震主要集中分布在三大地震带上，即环太平洋地震带，欧亚地震带（地中海-喜马拉雅带）和海岭地震带，是三大地震带，而不是四大地震带。A、B、D项说法均正确。本题为选非题，故正确答案为C。", "tag": "地理国情"},
{"id": "geo-237", "q": "下列说法符合生活实际的是：", "options": ["小满时节，我国东部由低温导致呼吸疾病明显增多", "芒种时节，我国南方居民发现春困的感觉有所加剧", "处暑时节，我国北方医院里中暑病人相对有所减少", "雨水过后我国西部蚊蝇所传播的疾病开始明显增多"], "a": 2, "e": ".【C】A选项错误，小满过后，全国各地渐次进入了夏季，南北温差进一步缩小，温度升高，降水进一步增多，呼吸疾病减少。B选项错误，芒种时节，我国大部分地区温度升高，接近夏季，春困的感觉应该减少。C选项正确，处暑天气由热转凉，北方尤为明显，中暑人数减少。D选项错误，雨水时节气温回升、冰雪融化、降水增多，但仍处于初春低温时期，蚊蝇较少。故正确答案为C。", "tag": "地理国情"},
{"id": "geo-238", "q": "一艘油轮自科威特港驶往大连，其最短航线为：", "options": ["波斯湾→红海→马六甲海峡→南海→黄海→东海", "波斯湾→阿拉伯海→马六甲海峡→南海→东海→黄海", "红海→阿拉伯海→孟加拉湾→南海→东海→黄海", "红海→孟加拉湾→马六甲海峡→南海→黄海→东海"], "a": 1, "e": ".【B】故正确答案为B。", "tag": "地理国情"},
{"id": "geo-239", "q": "2020 年4 月，经国务院批准，海南省三沙市设立南沙区，南沙区人民政府驻永暑礁。以下对永暑礁的描述有误的是（）。", "options": ["永暑礁位于海南省东南部", "永暑礁的气候为热带季风气候", "永暑礁拥有丰富的渔业和矿产资源"], "a": 1, "e": ".【B】本题考查地理国情。A项正确，永暑礁是海南省三沙市南沙区政府驻地，位于海南省东南部。C项正确，永暑礁位于北纬，东经，属于热带季风气候。D项正确，永暑礁海域鱼类属于印度洋-太平洋热带动物区系，以珊瑚礁鱼类和热带大洋性鱼类占绝大多数，是我国海洋鱼类区系的重要组成部分；永暑礁周围海域海底蕴藏着大量矿藏，包括铁、锰、铜、镍、钴、铅、锌等数十种金属元素和沸石、珊瑚贝壳灰岩等非金属矿产，以及热液矿床。本题为选非题，故正确答案为B。", "tag": "地理国情"},
{"id": "geo-240", "q": "关于京杭大运河，下列说法不正确的是：", "options": ["2014 年入选世界文化遗产名录", "世界上里程最长、工程最大的古代运河", "沟通海河、黄河、淮河、长江、钱塘江五大水系", "途经今浙江、江苏、山东、河北、河南五省及天津、北京两市"], "a": 3, "e": ".【D】本题考查地理国情。A项正确，2002年，大运河被纳入了“南水北调”东线工程。2014年6月22日，第38届世界遗产大会宣布，中国大运河项目成功入选世界文化遗产名录，成为中国第46个世界遗产项目。B项正确，京杭大运河是世界上里程最长、工程最大的古代运河，也是最古老的运河之一，与长城、坎儿井并称为中国古代的三项伟大工程，是中国古代劳动人民创造的一项伟大工程，是中国文化地位的象征之一。C项正确，大运河贯通海河、黄河、淮河、长江、钱塘江五大水系，全长约1797公里。运河对中国南北地区之间的经济、文化发展与交流，特别是对沿线地区工农业经济的发展起了巨大作用。D项错误，大运河南起余杭（今杭州），北到涿郡（今北京），途经今浙江、江苏、山东、河北四省及天津、北京两市，全长约1797公里。运河对中国南北地区之间的经济、文化发展与交流，特别是对沿线地区工农业经济的发展起了巨大作用。因此，运河途经四省，无河南省。本题为选非题，故正确答案为D。", "tag": "地理国情"},
{"id": "geo-241", "q": "下列关于雷电的说法错误的是：", "options": ["人们总是先看见闪电后听见打雷", "直击雷的破坏性比球形雷小", "闪电时可能伴随着臭氧的生成", "雷电一般发生在对流层"], "a": 1, "e": ".【B】本题考查自然常识，主要涉及雷电的相关知识。A项正确，由于光在空气中的传播速度快于声音在空气中的传播速度，所以人们总是先看见闪电后听见打雷。B项错误，直击雷就是直接打击到物体上的雷电；球形雷则像火球一样，会飘进室内。直击雷的电压峰值通常可达几万伏甚至几百万伏，破坏性很强，是威力巨大的雷电，而球形雷的威力比直击雷小。C项正确，氧气和臭氧互为同素异形体，闪电可以让大气中的一部分氧气被激发成臭氧。D项正确，对流层是大气层中湍流最多的一层，雷电、雨、雾等天气现象一般发生在对流层。本题为选非题，故正确答案为B。", "tag": "地理国情"}
);
